(window.AQIDA_TEXTS = window.AQIDA_TEXTS || {})["516"] = {"atoms": {"516.1": {"x": [[1, "لأبي عبد الله محمد بن يوسف السنوسي الحسني 830 - 895 ه\rمع المواهب اللدنية في شرح المقدمات السنوسية\rلأبي إسحاق إبراهيم الأندلسي\rالطبعة الأخيرة 1373 ه -1953 م\rالناشر: مكتبة مصطفى البابي الحلبي وألاده\rمصر ص. ب الغورية 71"], [2, "خطبة الكتاب\r"]], "pg": [1, 2]}, "516.2": {"x": [[2, "فاعلم أنه لا إله إلا الله\r(قرآن كريم)\rبسم الله الرحمن الرحيم\rالحمد لله الذي أنعم علينا بنعمة الإيمان والإسلام، وهدانا بنبينا ومولانا محمد عليه الصلاة والسلام، فبين للناس معرفة مولانا العظيم على وجه التمام، وبلغ لهم عن الله تعالى الحلال والحرام وسائر الأحكام، وخص صلى الله عليه وسلم في جميع ذلك بجوامع الكلام، وتيسير المعانى للأعلام والإفهام\r{وبعد} فقد وضعت جملة مختصرة فيما يجب على المكلف اعتقاده في حق الله تعالى وفي حق رسله عليهم الصلاة والسلام على وجه يخرج به المكلف من ظلمات الجهل ... والتقليد، فأردت أن أتبعها بشرح مختصر يكشف عن معانيها كل لبس وتعقيد، والله تعالى أسأل أن ينفع به إنه ولي التوفيق والتسديد (الحمد لله) بدأ بالحمد اقتداء بالكتاب العزيز وامتثالا لما رغب فيه المصطفى صلى الله عليه وسلم حيث قال: كل أمر ذي بال لا يبتدأ فيه بالحمد فهو أبتر ويروى أجذم ويروى أقطع وكلها على طريق التشبيه البليغ بالأبتر والأجذم والأقطع في العيب المنفر وعدم التمام ومعنى الحمد لغة المدح بكل كمال لله لأن الكمال إما قديم فهو وصفه وإما حادث فهو فعله فالكل إذاً له تبارك وتعالى فلا يستحق المدح إذاً على الحقيقة سواء وحكم هذا الحمد الوجوب مرة في العمر كالحج وكلمتي الشهادة والصلاة والسلام على سيدنا ومولانا محمد صلى الله عليه وسلم تسليماً كثيراً (رب العالمين) أصل التربية نقل الشيء من أمر إلى أمر حتى يصل إلى غاية أرادها المربى ثم نقل إلى المالك والمصلح للزوم التربية لهما غالبا والعالمين جمع سلامة للعالم على غير قياس والعالم في اللغة كل نوع أو جنس فيه علامة يمتاز بها عن سائر الأنواع والأجناس الحادثة فيقال في الأنواع عالم الإنسان وعالم الطير وعالم الخيل ويقال في الأجناس عالم الحيوان وعالم الأجسام وعالم الناميات ويحتمل أن تكون المناسبة في تسمية النوع والجنس بالعالم أن لهما من الفصول والخواص ما يعلمان به ونقله المتكلمون إلى كل حادث والمناسبة في هذه التسمية أن كل حادث فيه علامة تميزه عن موجده المولى القديم حتى لا يلتبس به أصلا ولهذا رد مولانا جل وعلا على الضالين الذين جعلوا له شركاء من الحوادث فقال تعالى وجعلوا لله شركاء قل سموهم أي اذكروا أوصافهم حتى ينظر أن فيها ما يصلح للألوهية أم لا ويحتمل أن تكون المناسبة أن كل حادث يحصل العلم للناظر فيه ما يجب للمولى العظيم من عَلِىِّ الصفات وتنزهه عن سمات\r\r[المواهب اللدنية في شرح المقدمات السنوسية]\r{بسم الله الرحمن الرحيم}\rصلى الله على سيدنا محمد وآله وصحبه وسلم، الحمد لله الواجب وجوده الممتنع نظيره والممكن سواء وغيره، القديم الذي لا بداية له الباقي الذي لا نهاية له الحي العليم القادر المتكلم الفرد السميع البصير المريد الشأني المتصف بهذه الصفات القديمة التي لا هي هو ولاهي غيره كما ينبغي لكماله، والصلاة والسلام على سيدنا ومولانا محمد وعلى آله وأصحابه المرسل رحمة للعالمين (({لِيُنذِرَ مَن كَانَ حَيًّا وَيَحِقَّ الْقَوْلُ عَلَى الْكَافِرِين)\r(وبعد) فيقول العبد الفقير المضطر لرحمة ربه القدير أبو إسحاق ابراهيم الأندلسي ثم السرقسطي ابن أبي الحسن على عرف البناني عصمه الله ووقاه وجعل الجنة منزله ومأواه مع جملة أولاده ووالديه وإخوانه والمسلمين بمنه وكرمه: لما قصرت الهمم ونفرت في هذا الزمان مما فيه تطويل سألني بعض الإخوان أن أختصر له شرح العقيدة المسماة ... ((بالمقدمات)) لسيدنا ومولانا شيخ الإسلام ومصباح الأنام أبي عبد الله محمد بن يوسف السنوسي الحسني نفعنا الله به آمين لما رأني"], [3, "المحدثات ولهذا قال جل من قائل (إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالأَرْضِ وَاخْتِلاَفِ اللَّيْلِ وَالنَّهَارِ لآيَاتٍ لِّأُوْلِي الألْبَاب})، وقال جل وعلا: (أَوَلَمْ يَنظُرُواْ فِي مَلَكُوتِ السَّمَاوَاتِ وَالأَرْضِ وَمَا خَلَقَ اللّهُ مِن شَيْءٍ) والآيات في ذلك كثيرة فالمناسبة الأولى في وضع اللغة والاصطلاح تقتضي أن العالم مأخوذ من العلامة والمناسبة الثانية تقتضي أنه مأخوذ من العلم وذكر هذا الوصف وهو رب العالمين بعد الحمد لله شبه البرهان بعد الدعوى لأنه لما ادعى في الجملة الأولى أن كل كمال لله تعالى وحده لا يمدح عليه في الحقيقة سواء وقد عرفت أن الكمال إما قديم وأما حادث أتى بما يدل على أن كلا الكمالين له تعالى بمعنى أن الأول وصفه والثاني فعله والدليل على ذلك العوالم لأنه قد قام البرهان القطعي على حدوثها من جهة تغيرها الذي آذنت به التربية المأخوذة من لفظ رب ومن جهة احتياجها إلى المخصص في اختصاصها ببعض ما تقبله من مقدار وصفة وغيرهما وقد أشعر أيضا بالاحتياج إلى المخصص الإتيان بالجمع في العالمين فانه مؤذن بالاختلاف في المقادير والصفات والأزمنة والأمكنة مع قبول كل مقدار غيره وصفته وزمانه ومكانه فلو وقع ذلك من غير فاعل لزم الجمع بين متنافيين وهما مساواة أحد الأمرين لصاحبه ورجحانه عليه بلا سبب وذلك معلوم الاستحالة فاذا هذا الوصف وهو رب العالمين مؤذن بحدوث جميع العوالم من جهة المضاف لإشعاره بعموم التربية للعوالم المستلزمة للتغير في جميعها وهو دليل على الحدوث والافتقار للمحدث ومن جهة المضاف إليه أيضا لإشعاره بسبب جمعيته وعمومه باختلاف أصناف العوالم وأنواعها وأجناسها في مقاديرها وصفاتها وأزمنتها وأمكنتها وجهاتها مع قبول مادة كل واحد منها لما حصل لغيره وذلك يستلزم حدوثها وافتقارها إلى المخصص.\rولما كان الاحداث والإيجاد موقوفا على كمال ألوهية الموجد واتصافه بوجوب الوجود والقدم والبقاء والقيام بالنفس والمخالفة للحوادث والوحدانية والحياة وعموم القدرة والإرادة لجميع الممكنات وعموم العلم لجميع الواجبات والجائزات والمستحيلات لزم أن كل حادث يدل على وجوب هذه الكمالات لمولانا جل وعلا وبالجملة فالعوالم بعد أن تقرر وجوب حدوثها وافتقارها إلى مولانا جل وعلا شهدت بأن كل كمال قديم هو وصفه تعالى لتوقف حدوثها على اتصاف مولانا جل وعز بذلك الكمال وشهدت بأن كل كمال حادث هو فعله لما شهدت به من وجوب الوحدانية لمولانا تبارك وتعالى فقد شهدت إذا بأن المدح بكل كمال قديم أو حادث إنما هو لمولانا جل وعلا وهو معنى الحمد لله وهذا التقرير يعرفك أن تعقيب جملة الحمد لله في سورة الفاتحة بالوصف برب العالمين هو في غاية الحسن والإعجاز وبالله تعالى التوفيق (والصلاة والسلام على سيدنا محمد خاتم النبيين وإمام المرسلين) لاشك أن أعلى الكمالات الحادثة كلها وأدومها كمال الفوز برضا مولانا جل وعلا\r\r[المواهب اللدنية في شرح المقدمات السنوسية]\rأهلا لذلك وإن كنت لست هنالك بذلك وجمعت ما يحصل به حل ألفاظ العقيدة وربما أزيد على ذلك مفيدة من غيره تتعلق بالمقام لتحصل الفائدة فجاء بحمد الله على وفق المراد واستخرت الله أن يكون من جامع كلامه ليسهل عليه وعلى المبتدئين أمثالي، وأسأل الله الكريم أن يجعله خالصا ً لوجهه العظيم إنه غفور رحيم، وسميته ((بالمواهب الربانية في شرح المقدمات السنوسية)) وأسأله سبحانه أن يرحمنا ويرحم أولادنا ووالدينا وإخواننا ومشايخنا وجميع المسلمين بمنه وكرمه، قال وحيد زمانه تغمده الله بغفرانه: أؤلف مستعينا بـ (بسم الله الرحمن الرحيم) اقتداء بالكتاب العزيز وامتثالا لقوله صلى الله عليه وسلم: كل أمر ذي بال لا يبتدأ فيه ببسم الله الرحمن الرحيم فهو أبتر أو أجذم أو أقطع أي ناقص وقليل البركة فان قلت كثير من الأمور يبتدأ فيه بالبسملة والحمدلة ولا يتم وكثير بالعكس فما المراد بالحديث. فالجواب أن المراد منه أنه لا يكون معا لبرا شرعا. فان قلت هلا قال بالله بدل بسم الله. فالجواب إنما لم يقل ذلك تحرزا من أيمان القسم. فان قلت لماذا كسرت الباء وقاعدة الحروف المفردة البناء على الفتح. فالجواب لتناسب حركة بنائها عملها وهو الجر المناسب للكسر كما قلت. لم لا تكتب الألف بعد الباء على ما هو. قاعدة الخط فالجواب لكثرة الاستعمال المعرض بحسب اللفظ والخط وهو باعث على التخفيف من أي وجه. والاسم مفسق من السموّ وهو العلو وقيل من الوسم وهو العلامة. والله علم على الذات الواجب الوجود المستحق لجميع المحامد والكمالات والرحمن المنعم بحلائل النعم والرحيم المنعم بدقائقها وقدم الله عليهما لأنه اسم ذات وهما اسما صفة والذات مقدمة في التعقل على الصفة وقدم الرحمن على الرحيم لأنه خاص إذ يقال اغير الله بخلاف الرحيم والخاص مقدم على العام والجملة تحتمل الخبرية والله أعلم.\rولما كان النبي صلى الله عليه وسلم هو الواسطة بين الله تعالى وبين عباده والنعم الواصلة من الله تعالى إليهم وأعظمها الهداية لتوحيده والإقرار بربوبيته والتصديق بملائكته وكتبه ورسله على يده صلى الله عليه وسلم فقال بعد بسم الله الرحمن الرحيم (صلى الله على سيدنا محمد) الصلاة من الله رحمة مقرونة بتعظيم وتكريم وتشريف ومن الملائكة استغفار ومن غيرهما تضرع ودعاء والسيد من له السودد والكمال المطلق ومحمد بدل من سيدنا وهو علم منقول من اسم مفعول المضعف سمى به صلى الله عليه وسلم لكثرة خصاله لمحمودة فلإن قلت ما بال المصنف رحمه الله تعالى لم يأت بالحمد بعد البسملة في المقدمات. فالجواب يحتمل أن يكون حمد الله في نفسه عند ابتدائه أو يقال استغنى عنه بالبسملة إذ المقصود الثناء على الله وهو حاصل بها. فان قلت كان ينبغي للمصنف أن يتشهد لخبر أبي داود كل خطبة ليس فيها تشهد فهي كاليد"], [4, "والسلامة من غضبه وقد جعل مولانا سبحانه بفضله نبينا ومولانا محمدا صلى الله عليه وسلم بابا عظيما لذلك مفتوحا في الدنيا والآخرة لايقاربه باب ولا يستغنى عن التعلق بأذياله والإيواء إلى عتبة حرمه وبابه أحد من الأعداء والأحباب كيف ومن أجله خلق الله الكمال الدنيوي والأخروي والعلوي والسفلي وبشفاعته الكبرى في الآخرة وما بعدها من شفاعاته تنقشع أنواع الكرب وترتفع بفضل الله تعالى أسبابها وتتجلى شموس نعم مولانا جل وعلا على كافة المؤمنين وتنفتح أبوابها التي لم يتجاسر أحد من أهل الكمالات على طلب فتحها وتنتشر بعنايته العظمى التي تفضل بها المولى تبارك وتعالى على أهل الإيمان به أنواع السرور وتنكشف عن الظواهر والبواطن أجناس الغموم وأنواع الشرور وببركة مبعثه الشريف وطلوع طلعته البهية السعيدة على أهل الأرض انكشفت ظلمات الكفر والجهالات التي عمت وانتشرت وتمكنت غاية التمكن في جميع الآفاق والقلوب وتشعشعت أنوار الإيمان بالله تعالى وبرسله وكتبه وملائكته وانقلعت بفضل الله تعالى سحائب رين الجهل وغمة السيئات والذنوب وأفاض سبحانه رحمته على الخلق وأخرج لهم على يد مصطفاه سيدنا ومولانا محمد صلى الله عليه وسلم ذخائر المعارف الربانية ونفائس الحكم والعلوم الدينية وحلاهم بجواهر الأسرار التي خبأها لهم في خزائن الغيوب حتى كثرت منهم في كل جيل الأقطاب والأوتاد والنقباء والأخيار والأبدال وعجبت الأرض وجبلها وسهلها برها وبحرها بتوحيد المولى تبارك وتعالى والتنويه بأقدار رسله وملائكته وكتبه واللهج بشكره سبحانه وذكره وحمده على كل حال وبكل كمال وانتشرت أمة نبينا ومولانا محمد صلى الله عليه وسلم وتطاولت أزمنتها إلى موافاة القيامة وحفظ الله سبحانه عليهم الإيمان مع اختلاف الدول وانتشار المحن وبعد العهد عن مشاهدة أهل الحق والسنن والاستقامة ونمى سبحانه أنوارهم المعنوية والحسية\rدنيا وأخرى حتى كادوا كلهم من حكم قلوبهم وسطوع أنوارهم وامتدادها أن يكونوا أنبياء وأكثر سبحانه عددهم كثرة عظيمة تخرج عن الحصر حتى جعلهم بفضله ورحمته ثلثي جميع من يدخل الجنة من السعداء وقد ورد أن صفوف أهل الجنة مائة وعشرون صفا ثمانون صفا منها لهذه الأمة ولعلهم إن كانوا ثلثي أهل الجنة يكون لهم من الجنة ونعيمها أكثر من الثلثين كثلاثة أرباع أو تسعة أعشار ونحو ذلك لما علم من تخصيص المولى تبارك وتعالى لهم بكرامة تضعيف الثواب لهم بالعمل والزمان والمكان والحال، وبالجملة لما لم ينل غيرهم من الجنة إلا اليسير فكأنها إنما خلقت من أجلهم ولهم وإذا عرفت أن منزلة سيدنا ومولانا محمد صلى الله عليه وسلم عند مولانا جل وعلا بهذه المثابة عرفت أن حمده تعالى وشكره على إنعامه به على الخلق من أوجب الواجبات وأن\r\r[المواهب اللدنية في شرح المقدمات السنوسية]\rالجذماء. فالجواب لعله تشهد لفظا ولم يرقمه اختصارا أو بأن الحديث في خطبة النكاح لا الكتب والرسائل بدليل ذكره له في كتاب النكاح {تتمة} في ذكر حقيقة الحمد والشكر تكميلا للفائدة، "]], "pg": [2, 4]}, "516.3": {"x": [[4, "فالحمد لغة الثناء بالجميل على المحمود بجميل صفاته سواء كانت من باب الإحسان أو من باب الكمال المختص بالمحمود كعلمه وشجاعته والشكر لغة فعل ينبئ عن تعظيم بسبب كونه منعما واصطلاحا هو الثناء باللسان وبغيره من القلب والأركان بسبب ما أسدت إلى الشاكر من النعم. فان قلت ما النسبة بين الحمد والشكر. فالجواب نسبة العموم والخصوص من وجه يجتمعان في اللسان في مقابلة الاحسان وينفرد الشكر بالقلب والأركان وينفرد والحمد بتعلقه بالكمال كقولنا الله قديم الله واحد فهذا حمد وليس بشكر لأنه في مقابلة نعمة فاعرفه {مقدمة} تشتمل على فوائد مهمة: "]], "pg": [4, 4]}, "516.4": {"x": [[4, "الأولى أسباب العلم الحادث على طريق الأشعري ثلاثة حواس الخمس الظاهرة السليمة وهي السمع والبصر والشم والذوق واللمس والخبر الصادق متواترا كان أو مسموعا من الرسول المؤيد بالمعجزة والعقل وهو سبب للعلم أيضا أما الإلهام المفسر بإلقاء معنى في القلب بطريق الفيض يثلج له الصدر فليس يسبب للمعرفة بصحة الشيء عند أهل الحق. الثانية في الكلام على شيء من فضل العلم وفضل أهله روى عن ابن عباس رضي الله عنهما أنه قال ((للعلماء درجات فوق المؤمنين بسبعمائة درجة ما بين كل درجتين خمسمائة عام)) وقوله صلى الله عليه وسلم ((العلماء ورثة الأنبياء)) ومعلوم أن لا رتبة فوق رتبة النبوة ولا شرف فوق شرف الوراثة من الأنبياء وقوله صلى الله عليه وسلم ((يستغفر للعلماء من في السموات والأرض)) وأي ّ منصب أعلى من منصب من يشغل ملائكة السموات والأرض بالاستغفار وقوله صلى الله عليه وسلم ((من أحب أن ينظر إلى ... التوسل عتقاء الله من النار فلينظر إلى العلماء والمتعلمين)) وفي الخبر إن الله تعالى يحشر العلماء يوم القيامة في زمرة واحدة حتى يقضي بين الناس ويدخل أهل الجنة الجنة وأهل النار النار ثم يدعو العلماء فيقول يا معشر العلماء إني لم أضع حكمتي فيكم وأنا أريد أن أعذبكم قد علمت أنكم تخالطون من المعاصي ما يخالط غيركم فسترتها عليكم وقد غفرتها لكم وإنما كنت أعبد بفتياكم ادخلوا الجنة بغير حساب. الثالثة في اسم هذه العقيدة فاسمها المقدمات بميم مضمونة فقاف مفتوحة فدال مهملة مكسورة فميم والمراد بها هنا طائفة من العلم نقدم عليه ليتمرن بها المنتدى على الخوض فيما سولها، وعدد مقدماتها ثمانية الأولى مقدمة الأحكام والثانية مثدمة المذاهب والثالثة مقدمة أنواع الشرك والرابعة مقدمة أصول الكفر والخامسة مقدمة الموجودات والسادسة مقدمة الممكنات والسابعة الصفات الأزلية والثامنة مقدمة الأمانة"], [5, "فضل الصلاة والسلام على النبي صلى الله عليه وسلم\r"]], "pg": [4, 5]}, "516.5": {"x": [[5, "التوسل اليه تعالى بحب هذا السيد والتعظيم وكثرة الصلاة والتسليم عليه من اعظم الوسائل للأمن من المخوفات والفوز بأعظم الدرجات. ولو لم يكن للصلاة عليه من فضل العظيم الا ما ورد في الصحاح ان من صلى على سيدنا محمد صلى الله عليه وسلم مرة واحدة صلى الله تعالى عليه عشرا, لكان كافيا للعقلاء كيف وقد ورد في فضلها العظيم ما الّف ائمتنا بالإنفراد تآليف العديدة. وقد رأيت لبعض أئمة التصوف ان من فقد شيوخ التربية فليكثر الصلاة على النبى صلى الله عليه وسلم, فإنه يصل الى المقصود. فلعله أخذ ذلك من قوله صلى الله عليه وسلم لأبي هريرة رضي الله عنه عندما إلتزم ان يجعل جميع صلاته للنبي صلى الله عليه وسلم \"إذا تكفي همك ويغفر ذنبك\" ولا شك أن المريد الطالب على المشائخ التربية قد اهتم بتنقية النفس وشفائها من علائق سواه تبارك وتعالى. فإذ أكثر من الصلاة على سيدنا ومولانا محمد صلى الله عليه وسلم كفى هذا الهم الذي اهتم به والله تعالى أعلى وأعلم.\rفذكرنا في هذه العقيدة بعد حمد الله تعالى والصلاة والسلام على نبيه واشرف خلقه صلى الله عليه وسلم, مناسب من أوجه الأول أنه شبه حمد خاص بعد حمد عام, لأنه لما حمد المولى تبارك وتعالى حمدا مطلقا على جميع الفضائل والفواضل, وإن شئت قامت على كماله وتكميله حمده بعد ذلك حمدا خاصا وهو امتثال أمره سبحانه فيما أمر به من الصلاة والتسليم على نبيه صلى الله عليه وسلم على نعمة خاصة وهي نعمة بعث الله تعالى نبينا ومولانا محمدا صلى الله عليه وسلم ورحمته به سبحانه الخلق دنيا وأخرى وخص هذه النعمة بالذكر لأنها أكبر النعم وأعمها وأدومها الثاني أنه لما حمد المولى جل وعلا وشكره على جميع نعمه التي تفضل بها سبحانه وأوجدها وحده شكر بعد ذلك من أظهر سبحانه على يده تلك النعم وأفاضها ببركته على الخلق دنيا وأخرى وهو نبينا ومولانا محمد صلى الله عليه وسلم لقوله صلى الله عليه وسلم من لم يشكر الناس لم يشكر الله ولما كنا عاجزين عن مكافأته صلى الله عليه وسلم من قبل أنفسنا وجب أن ترجع في ذلك إلى مولانا الكريم القادر الذي بيده خزائن النعم فنطلب منه أن يصلي على هذا النبي الشريف صلى الله عليه وسلم أن ينعم عليه بنعم يصحبها تكريم وتعظيم على ما يليق بمنزلة هذا السيد عنده وأن يسلم عليه أي يعظمه بأن يسمعه من كلامه الذي لا مثل له ما تقربه عينه وتبتهج به نفسه ويتسع به جاهه. الثالث أنه لما صدر عنه الحمد لله رب العالمين وكان ذلك مقتضيا المعرفة توحيد مولانا جل وعلا ومعرفة ما يليق به من أوصاف الألوهية على حسب مامضى تقريره شكر بعده من أوصل سبحانه على يده النعمة العظيمة إذا الناس قبل مبعثه كانوا يمدحون غير الله تعالى الأصنام وغيرها ويضيفون على سبيل الحقيقة في زعمهم نعمه تبارك وتعالى وانواع تربيته إلى غيره من الأسباب العادية وغيرها فلما بعث نبينا ومولانا محمد صلى الله عيه وسلم عرفهم أن الحمد لا يستحقه على\r[المواهب اللدنية]\rفي حق الرسل عليهم الصلاة والسلام فان قلت ما الحكمة في تقديم الأحكام على غيرها وفي عطف باقيها عليها على الترتيب المشاهد. فالجواب إنما قدّم مقدّمة الأحكام على غيرها لأن بها بعرف ما عداها وعطف مقدمة المذاهب على مقدمة الأحكام لاشتراكهما في العدد وهي ثلاثة كما أن الأحكام ثلاثة وقيل المناسبة بينهما لأنه ختم الأحكام بالجائز فعل فعطف الفعل على الفعل وعطف مقدمة أنواع الشرك على مقدّمة المذاهب لاشتراكهما مع مذهب القدرية وعطف مقدّمة أصول الكفر على مقدّمة أنواع الشرك لأن بينهما عموما وخصوصا من وجه فيشتركان في جلها وينفرد الشرك في السادس وينفرد الكفر في الايجاب الذاتي وعطف مقدّمة الموجودات على مقدّمة أصول الكفر لما فيه من شبه البرهان بعد الدعوى وذلك أنه ختم الأصول بالجهل باقواعد العقلية وهو متضمن لمذهب النصارى في حعلهم الإله صفة تعالى الله عن قولهم أتى بالموجودات ردّا عليهم والله أعلم وعطف مقدمة الممكنات على مقدّمة الموجودات لما بينهما من الاشتراك فيشتركان في الأجرام وأعراضها وتنفرد الموجودات بذات مولانا وتنفرد الممكنات بالجائز المعدوم فتأمله وعطف مقدّمة الصفة الأزلية على مقدّمة الممكنات من باب إتيان الطالب في أثر المطلوب وذلك أن القدرة الأزلية طالبة لتعلقها بالممكنات وهي مطلوبة وعطف مقدّمة الأمانة وهي الثامنة على الصدق المندرج تحت مقدّمة الصفات لما بينهما من الاشتراك والتلازم وهذا من منح العلم فاعرفه فانه نفيس.\rفاذا تقرر ها فلنرجع إلى مقصود المؤلف وتقرير كلامه فنقول والله المستعان: قوله رضي الله عنه ونفعنا به (الحكم) يعني اللغوي ويقال الحكم على الاطلاق وحقيقته ... (إثبات أمر) يعني لأمر آخر (أو نفيه) عنه فالضمير يعود على الأمر من حيث هو أمر لا على الأمر الذي جرى فيه الاثبات وإلزام عدم صدق الحد على النفي الذي لم يتقدمه إثبات فيلزم أن يكون الحد غير جامع والحاصل أنه من باب قولهم عندي درهم ونصفه وفيه إذ جعله من باب عندي درهم ونصفه يقتضي أن الضمير في قوله أو نفيه لا يصح عودة على الأمر الأول بنفسه وليس كذلك إذ المراد عوده على الأمر لا بقيد أنه الأول بل أعم منه والله أعلم. فان قلت أي داع لتعريف مطلق الحكم أولا ثم تقسيمه وتعريف كل قسم على حدة فالجواب الداعي إلى ذلك توقف معرفة الأعم كتوقف معرفة الانسان على معرفة الحيوان مثلا فمعرفة حكم خاص عقلي أو عادي موقوف على مطلق الحكم فاعرفه فان قلت ذكر أو في الحد مناف المقصود إذ هي للترديد وهو ينافي التحديد فالجواب إنما يتم إذا لم تكن للتقسيم بأن يكون في المعنى مثلا المحدود كذا أو كذا أو شكا وإذا كان المقصود منها تبيين نوعه وأنواعه مع الجزم"], [6, "الحقيقة إلا الله تعالى إذ لا كمال قديما ولا حادثا إلا له وأنه هو رب العالمين وحده وبلغهم قوله تعالى ياأيها الناس اذكروا نعمة الله عليكم هل من خالق غير الله يرزقكم ونحو ذلك مما هو كثير في القرآن وقد اختصر ذلك كله في الفاتحة لهذا كانت أم القرآن. الرابع أن حمد الله تعالى وشكره الذي دخل تحت عمومه دعاء وطلب من المولى الكريم تبارك وتعالى لمزيد نعمه بطريق وعده الصادق في قوله تعالى لئن شكرتم لأزيدنكم ولهذا ورد في الخبر ((إن أفضل الذكر لا إله إلا الله وأفضل الدعاء الحمد لله)) ولما كانت إجابة أدعيتنا موقوفة على صلاتنا على نبينا ومولانا محمد صلى الله عليه وسلم أتينا بالصلاة والتسليم عليه صلى الله عليه وسلم بعد جملة الحمد المتضمن للشكر المتضمن طلب المزيد من نعم الله تعالى تكميلا لهذا الطلب وتتميما لغرض الحامد.\rالخامس أن قوله رب العالمين أشعر بأن التربية كلها وهي إيصال كل حادث إلى كماله الذي أريد له ليست إلا من المولى تبارك وتعالى وهذه التربية على قسمين عامة وخاصة بالإيجاد والتنمية والإمداد بالحياة والحواس وغيرها مما هو بين عموم الأجساد، والخاصة التربية الروحانية بالعلوم والمعارف العلمية والعملية وضبط الحركات والسكنات للجري على مقتضاهما وهذه التربية هي العزيزة الشريفة الموصلة إلى الفوز برضا مولانا جل وعلا والتمتع بما لا يحاط برصفه من نعيم الجنان أبد الآباد وقد جعا الله سبحانه هذه التربية الخاصة لا تحصل لأحد إلا على أيدي الرسل عليهم الصلاة والسلام وجعل الحاصل منها على يد نبينا ومولانا محمد صلى الله عليه وسلم الحظ الأوفر والنصيب الأكثر مع سهولة فيها وقلة معاناة كما قال تعالى يريد الله بكم اليسر ولا يريد بكم العسر وقال في وصف أمة نبينا صلى الله عليه وسلم ويضع عنهم إصرهم والأغلال التي كانت عليهم وقد عرفت كثرة من تربى على يده هذه التربية الخاصة وأنهم ثلثا أهل الجنة فأشرنا إلى تربية مولانا لخلقه التربية العامة بقولنا رب العالمين وأشرنا إلى التربية الخاصة بذكر أفضل من أجزل الحظ منها على يده مقرونا ذلك بتعظيمه والصلاة والسلام عليه وإنما قد ّمنا في العقيدة وصفه صلى الله عليه وسلم بالسيد على وصفه بالمولى لأن السيد يفزع إليه في كل أمر مهمّ والمولى هو الناصر ولاشك أن الفزع في المهم إلى السيد يكون أولا ونصرته لمن فزع إليه في نيل مهمه يكون ثانيا بعد فزعه إليه ولاشك أنه صلى الله عليه وسلم مفزع الخلائق وناصرهم في الدنيا بما بين لهم من طرق النجاة من أنواع الهدايات حتى تركهم على المحجة البيضاء التي لا غبار عليها ومفزعهم وناصرهم في الآخرة إذ له المقام المحمود هنالك والشفاعات المتكاثرة المشفعة والمقالات المسموعة والسؤال المعطى والجاه الأعظم والمنزلة العليا نسأل الله تعالى أن يهب لنا نصيبا وافرا من النفع بسيادته وجاهه الأعظم دنيا وأخرى ومعنى خاتم النبيين أنه\r--------------\rبأن كلا منهما يصدق عليه المحدود فلا يمتنع. فان قلت الإثبات لفظ مشترك إذ يقال أثبته إذا حبسه والمشترك لا يدخل في الحد. فالجواب الإثبات في الاصطلاح لا يطلق إلا في النسب كالإيجاب والسلب فليس بمشترك سلمنا جدلا ونقول إنما يمتنع دخوله في الحد ّ إذا لم تكن قرينة والقرينة مقابلته بالنفي كالسلب يقابل الإيجاب فاعرفه فان قلت هل حد المصنف للحكم بسيط أو مركب فالجواب هو بسيط لا مركب لأنه لو كان مركبا لقال إثبات أمر أو نفيه مع تصور معناه وإنما لم يركبه لأن التصور شرط على الصحيح والشرط خارج عن الماهية. فان قلت إثبات أمر ولم يقل إثبات معنى فالجواب لأن الأمر أعم فيشمل النفسي والسلبي وغيرهما بخلاف المعنى. فان قلت لم قدم الإثبات على النفي. فالجواب لشرف الإثبات على النفي. واعلم أن الإثبات ينقسم إلى أربعة: إثبات أمر وجودي لأمر وجودي كإثبات العلم لله تعالى إثبات أمر عدمي لأمر عدمي كإثبات استحالة الشريك إثبات أمر عدمي لأمر وجودي كالحدوث للعوالم إثبات أمر وجودي لأمرعدمي باطل لايصح لأن العدم لا يوصف بالوجود، والنفي أربعة أقسام نفي أمر وجودي عن أمر وجودي كنفي الجهل عنه تعالى نفي أمر عدمي عن أمر عدمي كنفي القدم عن الشريك. نفي أمر وجودي عن أمر عدمي كنفي العلم عن الشريك. نفي أمر عدمي عن أمر وجودي كنفي الحدوث عنه تعالى {تنبيه} الاصطلاح عندهم على من أدرك أمرا من الأمور وتصور معناه فقط ولم يحكم بثبوته ولا نفيه كادرا كنا مثلا أن معنى الحدوث الوجود بعد العدم تسمية ذلك الإدراك تصورا وإن أدركنا مع ذلك ثبوت الأمر أو نفيه عنه سميناه تصديقا وحكما أيضا كإثباتنا الحدوث بعد تصورنا لمعناه للعوالم أو نفيناه عمن وجب قدمه ... آخرهم فاثبات الأمر أو نفيه عنه هو المسمى حكما والحكم مصدر يستدعي حاكما ومحكوما به ومحكوما عليه ونسبة حكمية لحاكم إما الشرع أو العادة أو العقل والمحكوم به الوصف مطلقا والمحكوم عليه الذات مطلقا والنسبة الحكمية الارتباط ما بين المحكوم به والمحكوم عليه مثاله في الشرع الصلاة واجبة الحاكم الشرع والمحكوم عليه ذات الصلاة الواجبة والنسبة الحكمية الارتباط ما بين المحكوم به وهو الوجوب والمحكوم عليه وهو ذات الصلاة وفي العقل العالم حادث وفي العادة النار محرقة العقل بكذا أو حكمت العادة بكذا فاقهم. ولما كان الحكم لا بد له من الانقسام أشار المصنف رحمه الله تعالى ونفعنا به إلى تقسيمه بقوله ... (وينقسم) الحكم اللغوي الذي هو إثبات أمر أو نفيه يعني يتنوع (إلى ثلاثة أقسام) جمع قسم بكسر القاف نحو حمل وأحمال وقرب وأقراب يعني أنواع إذ هي من باب"], [7, "آخرهم وبه كمل عددهم الذي هو مائة ألف وأربعة وعشرون ألفا فلا نبي بعده ومن لازمه أن لا رسول بعده لأن النبي أعم من الرسول على الصحيح ونفى الأعم الأخص فكمل سبحانه لسيدنا ومولانا محمد صلى الله عليه وسلم جميع المحاسن التي تفرقت في الأنبياء والرسل قبله وشرف شريعته السمحة بأن جعل أحكامها متصلة بالآخرة لا ناسخ لها ولا مبدل لها وأطلع أمته المشرفة على مساوى الأمم الذين خلوا وعلى العقوبات التي نزلت بهم ليعتبروا بذلك ويرتدعوا عن المعاصي ولا يغتروا بالمهلة ومتعة الدنيا كما اغتر بذلك الذين هلكوا قبلهم فجعلهم مولانا بفضله معتبرين لا معتبرا بهم ومتعظين بهم وشاهدين على غيرهم لا مشهودا عليهم وأظهر سبحانه محاسنهم لمن مضى من الأمم وستر مساويهم بل نوّه المولى الكريم بقدرهم وقدر نبيهم سيدنا ونبينا محمد صلى الله عليه وسلم تنويها عظيما تمنى بسببه كليم الله تعالى صلى الله عليه وسلم أن يكون من هذه الأمة وبالجملة فنعم مولانا الكريم جل وعلا ومواهبه الاختصاصية التي خص بها نبينا ومولانا محمدا صلى الله عليه وسلم دنيا وأخرى لا يمكن إحصاؤها نسأله سبحانه أن يجعلنا من خيار أمته الفائزين بشرف قربه ومتابعته المتحصنين من كل محنة وخوف دنيا وأخرى بحرمة محبته وولايته ولأجل أنه عليه الصلاة والسلام خاتم النبيين مات أولاده الذكور كلهم قبل أن يكونوا رجالا لأنهم لو عاشوا حتى بلغوا من النبوة ثم لم ينبئوا كانوا في ذلك أحط رتبة من أولاد كثير من الرسل الذين خلوا كإبراهيم ويعقوب وداود عليهم الصلاة والسلام فلما ماتوا صغارا انتفت هذه الحطيطة وإلى هذا أشار القرآن في قوله تعالى ((مَّا كَانَ مُحَمَّدٌ أَبَا أَحَدٍ مِّن رِّجَالِكُمْ وَلَكِن رَّسُولَ اللَّهِ وَخَاتَمَ النَّبِيِّينَ)) فجعل سبحانه كونه الصلاة والسلام خاتم النبيين شبه العلة لما نفاه عليه الصلاة والسلام للكفار الذين يطلق عليهم اسم الرجال والنكتة فيه ما سبق تقريره والله تعالى أعلم. قوله وإمام المرسلين أي مقدمهم في جميع الكمالات ومتبوعهم إذ به يتعلقون في شدائد الاخرة وأهوالها المعضلات وقد قال عليه الصلاة والسلام ((آدم فمن دونه تحت لوائي يوم القيامة)) وقد ثبت أيضا أنه تقدمهم وأمهم حسا في ليلة الإسراء وذلك كله دليل واضح على أن هذا السيد صلى الله عليه وسلم أفضل المخلوقات وأكرمها على الله تبارك وتعالى وفيه أيضا دليل على كمال تواضع رسل الله عليهم الصلاة والسلام للمولى تبارك وتعالى وامتلاء صدورهم بهيبته ومحبته والتعظيم لما عظمه والتشريف لما شرفه إذ لم يجعلوا عليهم الصلاة والسلام ما خصصهم الله تعالى به من عظيم فضله مانعا من التواضع لمن آثره الله تعالى بمزيته وخصه بفضله على جميع العوالم وأخلاقهم الكريمة في هذا نظير أخلاق الملائكة عليهم الصلاة والسلام في تواضعهم وسجودهم لآدم صلى الله عليه وسلم امتثالا لأمر\r[المواهب اللدنية]\rتقسيم الكلي إلى جزيئاته لصدق اسم المنقسم على كل واحد بانفراده لا من باب تقسيم الكل إلى أجزائه لعدم صدق اسم المنقسم عليها مجتمعة فاعرفه ثم أبدل من ثلاثة أقسام بدل مفصل من مجمل بقوله (شرعي) وقدمه على العادي والعقلي لشرفه عليهما (وعادي) وقدمه على العقلي وإن كان أقوى منه لاشتراكه مع الشرعي في مطلق الإسناد كما سيأتي بيانه إن شاء الله تعالى في وجه الحصر (وعقلي) أخره عنهما لما قلناه ووجه الحصر في الثلاثة لا رابع لها تقول لا يخلوا الحكم إما أن يستند أولا وإذا استند لا يخلو إما أن ستند إلى معصوم أو لغير معصوم فان استند لمعصوم فهو الشرعي وإن استند لغير معصوم فهو العادي وغير المستند بالكلية فهو العقلي لا رابع لها.\rواعلم أن كل واحد من هذه الثلاثة ينقسم إلى قسمين تصور وتصديق وكل واحد من التصور والتصديق ينقسم إلى قسمين ضروري ونظري وكل واحد من الضروري والنظري ينقسم إلى قسمين واجب ذاتي وواجب عرضي وكل واحد من الواجب الذاتي والواجب العرضي ينقسم إلى قسمين إثباتي ونفي من ضرب ثلاثة في ثمانية بأربعة وعشرين قسما فمثال التصوري في الشرعيات كتصورنا لمعنى الصلاة أنها ذات ركوع وسجود وسلام ومثال التصديق في الشرعيات الصلاة واجبة ومثال الضروري في الشرعيات قواعد الإسلام الخمس ومثال النظري في الشرعيات اقتضاء الطعام من ثمن الطعام لا يجوز وأن الزعفران ليس بربوى ومثال الواجب الذاتي في الشرعيات كتصديق الرسل عليهم الصلاة والسلام ومثال الإثبات في الشرعيات كإثبات المحبة للنبي صلى الله عليه وسلم وإثبات غفران الذنوب بسبب التوبة ومثال النفي في الشرعيات الوتر ليس بواجب وصوم يوم عاشوراء ليس بواجب فهذه ثمانية في الشرع ومثال التصور في العقليات كتصورنا لمعنى العالم أنه كل موجود سوى الله ومثال التصديق في العقليات حدوث العالم وقدم صانعه ومثال الضروري في العقليات الواحد نصف الاثنين والتحيز للجرم ومثال النظري في العقليات الواحد عشر ربع الأربعين ومثال الواجب الذاتي في العقليات وجود الباري ومثال الواجب العرضي في العقليات وجود المخلوقات ومثال الإثبات في العقليات كإثبات حدوث ما سوى الله تعالى وإثبات الزوجية للعشرة ومثال النفي في العقليات كنفي الزوجية عن السبعة ونفي الشريك عنه تعالى فهذه ثمانية في العقل ومثال التصور في العاديات كتصورنا لمعنى الطعام والشراب ومثال التصديق في العاديات الطعام مقتات والتراب غير مقتات ومثال الضروري في العاديات الثوب ساتر والنار محرقة ومثال النظري في العاديات شراب السكنجبين مسكن للصفراء والتوخمة مهضمة للطعام ومثال الواجب الذاتي"], [8, "مولانا جل وعلا وتعظيما لمن عظم وتكريما لمن كرم وحبا لمن أحب وأين هذه الأخلاق الكريمة الزكية من أخلاق إبليس الأحمق المحروم حيث أمره المولى العظيم مع الملائكة الكرام بالسجود لآدم فاستكبر ورأى لنفسه الدنية شفوفا على من فضله المولى تبارك وتعالى وأدركه الزهو ّ والإعجاب بما ليس له ولا يستحقه وإنما هو بمحض فضل من المولى الكريم تبارك وتعالى وأخذ بجهاه وقلة عقله وعدم حيائه وسابق شقائه يعترض على من لاشريك له في ملكه ولا في حكمه بما يشاء ويخص من يشاء بما يشاء لا اعتراض عليه ولا سؤال لأحد عليه وهو الحكيم المحمود على كل حال ويجب على كل مؤمن أن يقتفي آثار الطاهرين المطهرين من كل حق ودنس من رسل الله تعالى وملائكته الكرام صلى الله وسلم على جميعهم فيتواضع لله تعالى ويعظم كل من رأى من المولى العظيم إيثار اله وتفضيل بخاصية من علم أو عبادة أو خلق جميل ولا يجعل ما خصه هو به مولانا جل وعلا من الفضل مانعا من التواضع لذوي الفضل والتعظيم لجنابهم الرفيع عند الله فيهلك ويسلب من فضله ومن كل خير كما هلك بذلك قدرته إبليس اللعين عافانا الله تعالى إلى الممات مما ابتلى به بجاه نبيه وأشرف خلقه سيدنا ومولانا محمد صلى الله عليه وسلم، ولينظر العاقل إلى ما فعله كليم الله تعالى صلوات الله وسلامه عليه مع الخضر عليه السلام عندما سمع من المولى تبارك وتعالى أنه خصه بعلم من لدنه من إتعاب نفسه الشريفة بالسفر إليه حتى لقيه ثم تواضع له في الكلام والتمس منه أن يعلمه بصيغة الاستفهام لا الأمر المستعملة في الإيجاب والاستعلاء فقال عليه الصلاة والسلام ((هل أتبعك على أن تعلمني مما علمت رشدا)) فالتمس منه بطريق الأدب بالعبادة أن يكون تابعا له متعلما منه ثم لما قابله الخضر عليه السلام بأن أغلظ له في القول إذ وصفه بعدم استطاعة الصبر معه جاوبه عليه الصلاة والسلام بتواضع ولين والتزم له أن يطيعه في كل ما يأمر به كما هو شأن العبد مع سيده فقال عليه الصلاة والسلام ... ((ستجدني إن شاء الله صابرا ولا أعصي لك أمرا)) فهذا التواضع من هذا السيد في علم لم يضطر إليه في ظاهره ولا في باطنه وله الفضل العظيم والرتبة الفائقة من اصطفاه مولانا جل وعلاه على الناس برسالته ومناجاته له بلا واسطة بكلامه القديم الذي لا مثل له وبالمعجزات الباهرة والآيات العظيمة القاهرة وقد ثبت أن له مع الله تبارك وتعالى ألف مجلس في المناجاة وكل مجلس يمنح له فيه من العلوم ما يخرج عن حد الحصر وقد ثبت أنه عند المناجاة يرفعه ويقربه حتى يسمع صريف الأقلام يكتب بها في اللوح المحفوظ وإلى هذا أشار القرآن بقوله تعالى ((وقربناه نجيا)) وقد نص بعض الأئمة على أن رتبته في الفضل تلى رتبة أشرف الخلق وأكرمهم سيدنا ومولانا محمد\r[المواهب اللدنية]\rفي العاديات كرفع الفاعل ونصب المفعول ومثال الواجب العرضي في العاديات لباس الطيلسان للعالم عند الأمر والنهي ومثال الإثبات في العاديات كإثبات الإحراق للنار والقطع للسكين ومثال النفي في العاديات خبز الفطير ليس بسريع الانهضام فهذه جملة الأربعة والعشرين قسما على الوفاء والتمام والحمد لله. فان قلت ما الفائدة في تقسيم الحكم الشرعي إلى ضروري ونظري فالجواب فائدة ذلك معرفة ما يوجب إنكاره الكفر وما لا يوجبه فان من أنكر ما علم من الدين ضرورة يكفر بخلاف الخفي الذي لا يعلمه إلا القليل فانه لا يكفر عند كثير من المحققين. ولما قسم الحكم اللغوي الذي هو إثبات أمر أو نفيه إلى ثلاثة أقسام شرعي وعادي وعقلي شرع الآن في تعريف كل واحد بانفراده فبدأ بالحكم الشرعي لشرفه (فالشرعي) أي فالحكم الشرعي تعريفه (هو خطاب الله تعالى) أي كلامه النفسي الأزلي أي ذلك الكلام حالة كونه في الأزل خطايا حقيقية لا مجازا على الأصح كما قاله المحقق المحلي في شرح جمع الجوامع (المتعلق) أي ذلك الكلام النفسي الأزلي (بأفعال المكلفين) أي البالغين العاقلين تعلقا معنويا قبل وجودهم وتنجيزيا بعد وجودهم بعد البعثة بشروط التكليف، وأما المتعلق بوجودهم قبل البعثة فهو تعلق معنوي (بالطلب) متعلق بخطاب على ما هو الظاهر وفيه وصف المصدر قبل إعماله إلا أنه يسهله أن المجرور يعمل فيه العمل الضعيف والقوي قاله المصنف رحمه الله تعالى وأيضا فالمصدر لم يبق على حقيقته وإنما المراد به المخاطب به من إطلاق المصدر على اسم المفعول به فان قلت لم أوّله باسم المفعول. فالجواب كما قاله الإمام الزناتي في حواشيه على أم البراهين بعد نقله لكلام المصنف من شرح المقدمات لأن الحكم الشرعي ليس المعنى ما خوطبنا به، بيانه أن حقيقة الخطاب هو توجيه الكلام للحاضر وليس الحكم هو التوجيه وإنما هو للوجه وكلامه تعالى لا يقال لا يصلح أن يوجه إلا ما هو حادث إذ الموجه مسبوق بالتوجيه وذلك يستدعي حدوثه. لأنا نقول التوجيه ينصرف نحو الموجه إليه وهو المخاطب بمعنى أنه يزال عنه المانع الذي يمنعه من سماع الكلام أو الإقبال عليه أو ما أشبه ذلك مما يليق به ويقال يمكن أن يتعلق بغير ذلك كتعلقه بالمتعلق من حيث المكلف به أي الخطاب تعلق بأفعال المكلفين بسبب الطلب أو الإباحة وفيه تأمل ويمكن أن يكون في موضع الخبر لمبتدأ محذوف أي وذلك متلبس بأفعال المكلفين"]], "pg": [5, 8]}, "516.6": {"x": [[9, "صلى اله عليه وسلم ولهذا هو الذي يدل عليه حديث مسلم في الشفاعة في اعتذار إبراهيم عليه الصلاة والسلام عند ما تطلب منه الشفاعة في الآخرة لأهل الموقف بقوله ((وكنت خليلا من وراء وراء)) قيل معناه وكنت خليلا من وراء موسى كليم الله الذي هو وراء سيدنا ومولانا محمد صلى الله عليه وسلم حبيب الله. انظر يا أخي بعين الاعتبار إلى أخلاق هؤلاء الكرام وعظيم تواضعهم لله تعالى ومحاسن آدابهم مع من يضطرون إليه من ذوي الفضل ولا منة له عليهم وعدم زهوهم وإعجابهم بما خصوا به من الفضل العظيم ثم انظر بعد ذلك إلى أخلاقنا الشيطانية وصفاتنا الجاهلية في معاملتنا لمن اضطررنا إليه أنقذنا الله على يديه من مهالك الدنيا والآخرة من علمائنا وعبادنا إلى زهونا وإعجابنا مع دناءتنا وقلة فضلنا وسوء حالنا وجهالة عاقبتنا، اللهم إنا نتوسل إليك بخواص عبيدك من أنبيائك ورسلك وملائكتك وجميع أوليائك وبأكرم الخلق لديك الشفيع المشفع عندك سيدنا ومولانا محمد صلى الله عليه وسلم أن تغفر لنا ما مضى من الذنوب وأن تصلحنا وتهب لنا سلامة الصدر فيما بقي وتوفقنا ظاهرا لما فيه رضاك عنا بلا محنة يا أرحم الراحمين ياعلام الغيوب وأن ترضى عنا يا مولانا علماءنا وأمهاتنا وكل من له حق علينا بمحض فضلك يوم يتعلق المظلوم بظالمه وتبلى السرائر وتنكشف الغيوب.\rالواجب على المكلف أن يعرف ما يجب وما يستحيل وما يجوز في حق مولانا عزوجل\rوفي حق رسله عليهم الصلاة والسلام\r(اعلم أنه يجب على كل مكلف أن يعرف ما يجب في حق مولانا جل وعز وما يستحيل وما يجوز وكذا يجب عليه أن يعرف مثل ذلك في حق الرسل عليهم الصلاة والسلام) حقيقة المعرفة الحادثة هي الجزم المطابق عن ضرورة أو برهان فقولنا الجزم احتراز من الظن وهو الاحتمال الراجح ومن الشك وهو الاحتمال المساوي ومن الوهم وهو الاحتمال المرجوح وقولنا المطابق احتراز من الجهل المركب فانه جزم غير مطابق لما في نفس الأمر كجزم الفلاسفة بقدم الأفلاك جزم اليهود والنصارى بسلامتهم من الخلود في النار يوم القيامة وقولنا عن ضرورة أو برهان احتراز من جزم المقلد المطابق فانه ليس بمعرفة وإن كان جزما مطابقا لما في نفس الأمر ويسمى في الاصطلاح اعتقادا ومعنى الضرورة إلجاء المولى سبحانه النفس لأن تجزم بأمر جزما مطابقا بلا تأمل بحيث لو حاولت أن تدفع عن نفسها ذلك الجزم بتشكيك أو نحوه لم تقدر ومثاله جزمنا بوجود أنفسنا وبأن الواحد مثلا نصف الاثنين ونحو ذلك مما هو كثير، ومعنى البرهان الدليل المركب من مقدمات قطعية ضرورية في نفسها أو منتهية في الاستدلال عليها إلى علوم ضرورية ومثال ذلك إذا قيل لنا فلان اشترى هذه السلعة بربع عشر الأربعين درهما\r[المواهب اللدنية]\rوحينئذ لا يلزم إعمال المصدر الموصوف فاعرفه. فان قلت لم حذف متعلق قوله بالطلب. فالجواب إنما حذف متعلقه لدلالة ما قبله عليه أي لها أي لتلك الأفعال (أو الإباحة) عطف على قوله بالطلب (أو الوضع لهما) يعني للطلب والإباحة {تنبيه} الخطاب كالجنس يسمل خطاب الله وغيره وبإضافته إلى الله تبارك وتعالى خرج عنه خطاب غيره ولا يتوهم أن طاعة أولى الأمر والسيد واجبة فيكون خطابهما حكما وقد خرج من التعريف لأنهما إنما توجب بإيجاب الله تعالى وخرج بقوله بأفعال المكلفين كما قال المحلى خطاب الله تعالى المتعلق بذاته وصفاته وذوات المكلفين كمدلول ((الله لا إله إلا هو خالق كل شيء، ولقد خلقناكم، ويوم نسير الجبال)) أ هـ. وصفات المكلفين أيضا إذ ليست بأفعال وبقي في الحد قصص أفعال المكلفين والأخبار المتعلقة بأعمالهم كقوله تعالى ((والله خلقكم وما تعملون)) فأخرجهما بالطلب. فان قلت بقي ما يخرج بقوله المتعلق وما يخرج بقوله المكلفين. فالجواب أما الأول فقد قال فيه بعض المحققين إنه ليس للاحتراز بل هو صفة لازمة للخطاب أي خطاب الله تعالى لا يخلو عن تعلق شيء وأما الثاني فأمره في عبارة المصنف رحمه الله تعالى مشكل حيث قال في التعريف أو الوضع لهما فان الصبي والمجنون يتعلق بهما خطاب الوضع على ما صرح به شيخ الإسلام في حاشيته على جمع الجوامع تبعا في ذلك لغيره وقد يقال حيث عرفوا المكلف بالبالغ العاقل يلزم خروجهما من التعريف فأي طريق يتناولهما. فان قلت ما المراد بقوله بأفعال المكلفين. فالجواب كما قال المصنف رحمه الله تعالى في الشرح ما يصدر منه ليشمل القول والنية اهـ ومراده بالصدور أن يكون مكتسبا له بذاته كركعة مثلا أو باعتبار أسبابه كالإيمان بالله ورسله لأن اكتسابه باعتبار أسبابه كالنظر مثلا أما ذاته فمن مقولات الكيف، وبالجملة الإجماع قائم على أن الصبي لا يخاطب بأمر الإيجاب ولا بنهي التحريم فالبلوغ شرط التكليف بهما إجماعا وأما أمر الندب فالصحيح أنه لا تكليف فيه في البالغ فما بالك بالصبي. وأما نهي الكراهة فقال العضد أنه كالأمر في الخلاف وإن الخلف لفظي. وأما الإباحة فأولى بعدم التكليف وهل قطعا أو يجري الخلاف كما جرى في المندوب، وأما خطاب الوضع فيتعلق بالصبي والمجنون كما تقدم خلافا للمصنف وما ذكرناه من تعلق الخطاب بالصبي وعدم تعلقه إنما هو في التعلق التنجيزي. وأما التعلق المعنوي فهو متعلق بالصبي والمجنون"], [10, "فجزمنا بأنه اشتراها بدرهم واحد ليس بضروري لنا ندركه بلا تأمل بل لا يحصل لنا الجزم العرفاني بذلك من غير تقليد لأحد حتى نختبر أنفسنا فنقول أقل عدد له أربعة وربعها واحد وهذه مقدمة واحدة ضرورية لا تفتقر إلى تأمل أعني كون الواحد ربع الأربعة لكن تكفينا هذه المقدمة في معرفة ما اشترى الإنسان به تلك السلعة حتى نعرف معرفة قطعية أن الأربعة عشر الأربعين وهذه المعرفة بهذه المقدمة ليست ضرورية إلا أنها تنتهي بضرورية فإنك إذا قسمت أربعين إلى عشرة أنصباء متساوية خرج لك في كل نصيب أربعة وكذلك لو عددت في أصابعك أربعة ثم أربعة وتجمع إلى أن تفرغ من أصابعك العشرة أو تضع في لوح أربعة وفوقها أربع عشر مرات وتجمع لكان مجموع ذلك أربعين فقد حصل لك علم ضروري لا تقدر أن تدفعه بأن الأربعة عشر الأربعين لكن لم يحصل لك هذا العلم الضروري أو ّ لا بل بعد رؤيتك حسيا انقسام الأربعين إلى عشرة أجزاء متساوية كل جزء منها أربعة فاذا ضممت هذه المقدمة الضرورية انتهاء وهي أن ربع الأربعة ربع عشر الأربعين إلى المقدمة الضرورية ابتداء وهي أن الواحد ربع الأربعة حصل لك منهما أن الذي اشتريت به تلك السلعة درهم واحد فنقول في نظم البرهان يجب أن يكون المشترى به درهما واحدا لأن الدرهم الواحد ربع الأربعة وربع الأربعة ربع عشر الأربعين المشترى به فينتج الدرهم الواحد ربع عشر الأربعين المشترى به فالجزم بهذ النتيجة يسمى معرفة وعلما لأنه جزم مطابق لما في نفس الأمر حاصل عن برهان وهو دليل قطعي لتركيبه من مقدمتين الأولى منهما ضرورية ابتداء والأخرى ضرورية انتهاء ولو جزمت بهذه النتيجة تقليدا لمن تثق به ممن يعرف الحساب ولم تستعمل أنت فكرك في ذلك لسمى جزمك اعتقادا صحيحا ولا يسمى معرفة وعلما ولو لم تثق بمن أخبرك بهذه النتيجة بل ترجح عندك صدقه واحتمل مرجوحا عندك أن يكون مخطئا لكان إدراكك الراجح ظنا وإداركك الرجوح وهما ولو تساوى عندك احتمال صدقه وكذبه لكان إدراكك لكل واحد من الاحتمالين المتساويين شكا واو جزمت على سبيل الغلط إما لوقوعك في شبهة أو لتقليدك من وقع فيها ممن تثق به في زعمك بأن ربع عشر الأربعين اثنان لا واحد لكان جزمك هذا جهلا مركبا لأنك جهلت ما في نفس الأمر وجهلت أنك جاهل به ويسمى أيضا هذا الجزم في الاصطلاح اعتقادا فاسدا فاعتبر من هذا الذي ذكرناه مثال المعرفة وأمثلة أضدادها فاذا عرفت هذه المقدمة عرفت حينئذ معنى قولنا يجب على كل مكلف أن يعرف إلى آخره أي يجب شرعا على كل مكلف أن يجزم بهذه الثلاثة في حقه تعالى وفي حق رسله عليهم الصلاة والسلام جزما\r[المواهب اللدنية]\rوكذا بالعدم بالكلية الذي لم يوجد أصلا فاعرفه فانه نفيس. فان قلت التعلق الذي للكلام ما هو. فالجواب تعلق دلالة إذ التعلق على ثلاثة أقسام تعلق دلالة وهو تعلق الكلام وتعلق العلم والسمع والبصر والإدراك على القول به وتعلق تأثير وهو تعلق القدرة والإرادة. ولما فرغ من تعريف الحكم الشرعي شرع الآن في ذكر أقسامه الداخلة في الطلب فقال (ويدخل) يعني يتدرج (في الطلب) المتقدم ذكره في الحكم الشرعي (أربعة أشياء) يعني أحكام ... (الأول الإيجاب) ولا شك أنه نوع من الخطاب وكذا البواقي (و) الثاني (الندب) أي المندوب (و) الثالث (التحريم) أي المحرم (و) الرابع (الكراهة) يعني المكروه وإنما دخلت الأحكام الأربعة في الطلب لأن الطلب على قسمين إما طلب فعل أو طلب ترك وكل واحد منهما إما جازم أو غير جازم فالمجموع أربعة من ضرب اثنين في اثنين بأربعة ثم أخذ في تعريف هذه الأحكام أوّلا فأولا وبدأ بالواجب فقال (فالإيجاب) أي الواجب هو (طلب) كالجنس شامل للأحكام الأربعة والمراد بالطلب الطلب النفسي العبر عنه باللفظي (الفعل) فصل خرج به التحريم والكراهة لأنهما طلب كف عن فعل لا طلب فعل والمراد بالفعل هما هو الحاصل بالمصدر لا الإيجاد و الإيقاع لأن التكليف إنما يتعلق بالأول دون الثاني لكونه أمرا اعتباريا لا تحقق له كذا قاله السعد وأقره عليه غير واحد كالكمال ابن أبي شريف في حواشي العقائد (طلبا جازما) فصل ثان خرج به الندب لأنه طلب للفعل من غير جزم في الطلب بأن لا يؤذن في الترك بل هذا قد يسمه له في الترك (كالإيمان بالله) أي كطلب الإيمان بالله (وبرسله) عليهم الصلاة والسلام والإيمان لغة: التصديق بما جاء به النبي صلى الله عليه وسلم عن الله جملة وتفصيلا {تنبيه} قد تقرر عندهم أن الكيفيات النفسية لا يكلف بها لكونها ليست من الفعال الاختيارية وقد اشتهر عن السعد وغيره أن المكلف به إنما هو أسباب فلا نطيل به. فان قلت لم عبر المصنف رحمه الله تعالى بالرسل وكان الأولى التعبير بالأنبياء للعموم. فالجواب عبر بالرسل دون الأنبياء على وجه تغليب الأفضل على غيره وإلا فالإجماع والنصوص الصريحة أن الأنبياء كالرسل فيما ذكر والله أعلم. فان قلت أي فائدة في ذكر غير النبي صلى الله عليه وسلم من الرسل مع أن الإيمان به وبما جاء به يتضمن الإيمان بهم. فالجواب فائدته زيادة التي تحصل بالفصيل الذي"], [11, "مطابقا لما في نفس الأمر حاصلا ذلك عن ضرورة أو برهان إلا أن الضرورة لم يجر الله بها العادة فتعين طلبها بالبرهان فلو لم يحصل للمكلف الجزم بهذه الثلاثة في حقه تعالى وفي حق رسله عليهم الصلاة والسلام بل إنما حصل الظن أو الشك أو الوهم لم يكفه ذلك بإجماع ولو حصل له الجزم إلا أنه غير مطابق لما في نفس الأمر كجزم اليهود والنصارى ومن في معناهم وسائر الكفرة بالكفريات التي جزموا بها لم يكف ولم يعذر به إجماعا ولو حصل منه جزم مطابق لما في نفس الأمر إلا أنه لم يكن ضرورة ولا عن برهان وإنما كان عن تقليد ففي ذلك طرق وأقوال أصحها أنه يجب عليه البحث عن البرهان حتى تحصل له المعرفة عنه مهما كانت فيه قابلية لفهم ذلك ثم يجب عليه إذا حصلت له تلك المعرفة بواسطة البرهان أن يقطع أن تلك المعرفة إنما حصلت بمحض خلق الله تعالى فضلا منه سبحانه ولا أثر للبرهان ولا لفكرة المكلف وبحثه في تحصيلها لا بطريق التعليل كما تقول الفلاسفة ولا بطريق التولد كما تقول المعتزلة وإنما المولى تبارك وتعالى هو الذي من ّ بفضله بخلق فهم الدليل وخلق فهم المدلول عليه أثره لا شريك له في ذلك ألبتة واختلف أئمتنا هل خلق الله تعالى معرفة المدلول عقب خلقه معرفة الدليل من غير عروض آفات خاصة ولا عامة لازم عادة كالشبع مع الأكل أو لازم عقلا كالعرض مع الجوهر مثلا فقال الشيخ الأشعري رضي الله تعالى عنه هو لازم عادة فيصح التخلف وقال إمام الحرمين هو لازم عقلا فلا يصح التخلف والأظهر ما قاله الأشعري والله تعالى أعلم.\rثم إن المعرفة بهذه الثلاثة في حقه تعالى وفي حق رسله عليهم الصلاة والسلام هل هي نفس الإيمان الذي كلفنا به وهو مذهب الأشعري أو ملتزمة للإيمان فيكون الإيمان هو حديث النفس التابع للمعرفة وهو مذهب القاضي وصححه بعض الأئمة لأنه أنسب لمعنى الإيمان وبالله تعالى التوفيق (وحقيقة الواجب ما لا يتصور في العقل عدمه إما بلا تأمل ويسمى الضروري ككون الواحد نصف الاثنين مثلا وإما بعد التأمل ويسمى النظري ككون الواحد نصف سدس الانثى عشر مثلا) لما قدم الحكم بوجوب معرفة المكلف شرعا لما يجب عقلا وما يستحيل عقلا وما يجوز عقلا في حق الله تعالى وفي حق الرسل عليهم الصلاة والسلام وكان الحكم على شيء أو بشيء موقوفا على تصور معناهما تعين على كل مكلف أن يعرف معنى الحكم العقلي وأقسامه ومعانيها ليعرف بذلك معنى وجوب ما يجب من الكمالات لمولانا تبارك وتعالى ومعنى استحالة ما ينزه عنه ومعنى جواز ما يجوز في حقه تعالى ويعرف ما تتعلق به الصفات من أقسام الحكم\r[المواهب اللدنية]\rهو المطلوب في عقائد الإيمان (وكقواعد الإسلام) أي وكطلب قواعد الإسلام (الخمسة) وهو التوحيد والصلاة والزكاة والصيام والحج. والإسلام لغة: الاستسلام، واصطلاحا: الانقياد والانخضاع لله تعالى بامتثال أوامره واجتناب نواهيه، فعطف الإسلام على الإيمان من عطف التباين فهما مختلفان ذاتا ومفهوما إن تلازما شرعا بحيث لا يوجد مسلم ليس بمؤمن ولا مؤمن ليس بمسلم (والندب) عطف على قوله بالإيجاب أي ودخل بالطلب الندب وهو أيضا نوع من الخطاب النفسي (طلب) كالجنس شامل للأحكام الأربعة والمراد بالطلب في التعريف الطلب النفسي (الفعل) فصل أول خرج به التحريم والكراهة لأنهما كف عن فعل لا طلب فعل (طلبا غير جازم) فصل ثان خرج به الواجب لأنه طلب الفعل طلبا جازما (كصلاة الفجر) أي ما نشاهد من الحركات والسكنات فيها لا إيقاع ذلك وإيجاده (ونحوها) أي نحو صلاة الفجر كالضحى مثلا (والتحريم) يعني المحرم عطف على قوله الإيجاب ... (طلب) كالجنس شامل الأحكام الأربعة والمراد به النفسي على ما مر (الكف عن الفعل) فصل أول خرج به الإيجاب والندب لأنهما طلب فعل لا طلب كف (طلبا جازما) فصل ثان خرج به المكروه لأنه طلب غير جازم (كشرب الخمر والزنا) أي كترك شرب الخمر وكترك الزنا (والكراهة) عطف على الأول (طلب) كالجنس شامل الأحكام الأربعة والمراد بالطلب في التعريف النفسي كما مر (الكف عن الفعل) فصل خرج به الإيجاب والندب لأنهما طلب فعل لا كف (طلبا غير جازم) فصل ثان خرج به التحريم لأنه طلب جازم (كالقراءة) يعني القرآن (في) حال (الركوع و) في حال (السجود مثلا) أي كتركه ذلك وإنما كره ذلك فيهما لأنهما محل تذلل وكلام الله تعالى يجل قراءته في تلك الحالة والله أعلم (وأما الإباحة) فصلها عما قبلها لأنه لا طلب فيها ولا فيما بعدها وهو الوضع وكأن هذا والله أعلم هو السر في جعل المصنف رحمه الله تعالى قوله في الشرح أو الوضع عطف على الإباحة ولم يعطف على الطلب لأن كلا من الإباحة والوضع لا طلب فيه فكأنهما شيء واحد عطفا على الطلب المقابل لهما فليدر مع اللطف والأمر سهل (فهو إذن الشرع) إذن جنس الطلب الشرع ولطلب غيره مطلقا فأخرج غيره بقوله الشرع وبقي ما هو أعم فأخرج المحرم والمكروه بقوله (في الفعل) وأخرج الواجب والمندوب بقوله (و) في (الترك) وقوله"], [12, "العقلي وما لا تتعلق به منها وبفهم ذلك يتأنى له فهم البراهين وفهم لزوم المعارف لها ورد ّ الشبه والجهالات التي صاحبتها وبذلك يعرف أيضا ً ما يجب في حق الرسل عليهم الصلاة والسلام وما يستحيل وما يجوز، أما معنى الحكم العقلي فهو إثبات أمر أو نفيه من غير توقف على تكرر ولا وضع واضع فقولنا من غير توقف على تكرر احتراز من الحكم العادي أي الذي عرف من العادة فإن الإثبات فيه والنفي إنما عرف وحكم بهما بواسطة التكرر والتجربة كقولنا أكل هذا الطعام يسخن البدن وأكل هذا لا يسخنه وقولنا ولا وضع احتراز من الحكم الشرعي الذي عرف من الشرع فان الإثبات فيه أيضا أو النفي إنما عرف وحكم بهما بواسطة وضع الشرع لهما كقولنا البر بالتمر يجوز فيه التفاضل والبر بالبر لا يجوز فيه التفاضل ومثال الإثبات في الحكم العقلي قولنا مثلا ً كل موجود فهو إما قديم وأما حادث فالحكم بإثبات أحد الأمرين لكل موجود يعرفه العقل بلا واسطة تكرر ولا تجربة ولا واسطة تعليم شرع ووضعه وإنما حصل ذلك بمحض خلق الله تعالى له في القلب عاريا عن القيدين ومثال النفي قولنا مثلا ً كل موجود لا يخلو من القدم والحدوث معا ً ثم هذا الحكم العقلي وإن عرى عن القيدين فقد أجرى الله تبارك وتعالى العادة بأن يخلق بعض أنواعه في القلب ضروريا ً بلا تأمل ويخلق بعض أنواعه عند النظر والتأمل والعلوم الحادثة كلها وإن كانت حاصلة بمحض خلق الله فيصح أن يخلقها في القلوب ابتداء بلا واسطة تجربة ولا بعث رسول ولا نظر ولا فكر فقد أجرى سبحانه بمحض اختياره العادة في خلقها على هذا التقسيم وأما أقسام الحكم العقلي فهي ثلاثة: الوجوب والاستحالة والجواز ووجه الحصر فيها أن كل ما يحكم به العقل إن كان يقبل الثبوت والانتقاء معا ً فهو الجواز وغن كان لا يقبل الأمرين معا ً فإن كان يقبل الثبوت فقط دون الانتفاء فهو الوجوب وإن كان يقبل الانتفاء فقط دون الثبوت فهو الاستحالة. ولما كان الحكم العقلي ينقسم إلى قسمين ضروري وهو ما يدرك بلا تأمل ونظري وهو ما لا يدرك إلا بعد التأمل لزم أن كل واحد من أقسامه ينقسم كذلك إلى ضروري ونظري وإنما تعرضنا في أصل العقيدة لشرح الواجب والمستحيل والجائز دون الوجوب والاستحالة والجواز لاستلزام تصورها تصور مصادرها لأن المشتق أخص من مصدره الذي اشتق منه ومعرفة الأخص تستلزم معرفة الأعم بخلاف العكس، وأيضا ً لما ذكرنا أنه يجب على كل مكلف أن يعرف الواجب والمستحيل والجائز في حقه تعالى وكذا في حق رسله عليهم الصلاة والسلام ولم نقل يجب عليه أن يعرف في حق الله تعالى وفي\r[المواهب اللدنية]\r(معا) تأكيد لئلا يتوهم أن الواو بمعنى أو فيكون أحدهما على البدل هو الإباحة وليس كذلك (من غير ترجيح لأحدهما على الآخر) يحتمل أن يكون زيادة بيان ويحتمل أن يكون من تمام الحمد والله أعلم (كالنكاح والبيع) يعني إذا لم يعرض لكل واحد منهما ما يوجبه أو يحرمه وأما إن عرض له ذلك فليخرج عن كونه مباحا فالتمثيل به إنما هو باعتبار سلامته من العوارض. واعلم أن الذي عليه الجمهور أن الأحكام خمسة وهي المذكورة في كلام المصنف رحمه الله تعالى وزاد بعض العلماء على الخمسة المذكورة ثلاثة الصحيح والباطل وخلاف الأولى فالصحيح ما يتعلق به النفوذ ويعتد به والباطل ما لا يتعلق به المفوذ ولا يعتد به وخلاف الأولى كطلب قيام الليل فانه يدل بالالتزام على النهي عن ضده كنوم الليل كله فيطلق على النوم أنه خلاف الأولى ولا يطلق عليه أنه مكروه وزاد بعضهم الرخصة والعزيمة فهي إذا عشرة {خاتمة} نسأل الله حسنها، سميت هذه الأحكام الخمسة خطاب تكليف توسعا في العبارة فان التكليف من الكلفة والشقة وذلك إنما يتحقق في الواجب للكلفة في تركه والمحرم للكلفة في فعله وما عداهما لا كلفة في فعله ولا في تركه لأن الكلفة توقع العقوبة الربانية وهي لا توجد في غيرهما ولذلك نقول الصبي غير مكلف وإن كان مندوبا للحج والصلاة على الأصح فغلب لفظ التكليف على الثلاثة الأخر تجوزا وتوسعا. ولما فرغ من الكلام على خطاب الطلب والإباحة شرع في الكلام على خطاب الوضع فقال (وأما الوضع) يعني لهما أي للطلب والإباحة (فهو عبارة) أي تعبير\r(عن نصب) يعني وضع وجعل (الشارع) الله تبارك وتعالى ورسوله الصادق الأمين صلى الله عليه وسلم ... ((وما ينطق عن الهوى إن هو إلا وحي يوحى، شرع لكم من الدين ما وصى به نوحا))\r(أمارة) بفتح الهمزة أي علامة وأشار بلفظ أمارة إلى أن أحكام الله تعالى ليست تابعة للأسباب والشروط والموانع بل هذه الأمور أمارة على الأحكام لنعرفها نحن منها لخفائها علينا وليس شيء منها باعثا لمولانا جل وعلا على حكم من الأحكام كما زعم من أضله الله وختم على قلبه وجعل على عينيه غشاوة وعلى سمعه وقرا (على حكم من تلك الأحكام الخمسة) المتقدم ذكرها وهي الواجب والمندوب والمحرم والمكروه والمباح. وضع سببا وشرطا ومانعا للواجب كالظهر فالسبب لها الزوال والشرط العقل والمانع الحيض والإغماء وضع سببا وشرطا ومانعا للمندوب كالنافلة"], [13, "حق رسله الوجوب والاستحالة والجواز كان الأنسب في مطابقة ما سبق أن نتعرض لشرح المشتقات وهي أسماء الفاعلين لا المشتق منه وهي المصادر وإنما بدأنا بشرح الواجب لوجهين: أحدهما أنه أشرف إذ به يتصف مولانا جل وعز، والثاني أنه عرف عرف منه المستحيل والجائز في حقه تعالى وقدمنا المستحيل على الجائز لأنه أقرب إلى الواجب إذ هو مقابله أيضا ً فالجائز شبه مركب لما ثبت للواجب من الثبوت ولما ثبت للمستحيل من النفي والواجب والمستحيل شبه بسيطين إذ لم يثبت لكل واحد منهما إلا أحد أمرين ولا شك أن مرتبة البسيط أحق أن تكون قبل المركب (قوله مالا يتصور في العقل عدمه) يعني لا يدرك في العقل نفيه سواء كانت حقيقة ذلك الواجب وجودية كذات مولانا تبارك وتعالى أو سلبية كقدمه جل وعلا.\rوقوله إما بلا تأمل إلى آخره يعني أن الواجب ينقسم إلى ضروري ونظري بحسب مجرى عادة الله وإلا فيجوز بإجماع أن يصير سبحانه جميع العلوم ضرورية فيلجئ العقل إلى تيقنها وتخلق فيه بلا تأمل أصلا كما يصح في العقل أن يجعل سبحانه جميع حركاتنا اضطرارية لاتجد عادة تيسر تركها وإنما وقع الخلاف في العلوم في عكس ما سبق وهو هل يصح أن تكون العلوم كلها نظرية للعقل ولا يعرف منها شيئا ً بالضرورة أو لا يصح ذلك لمنافاته وجود العقل بناء على نفس العلوم الضرورية أو ملزوم لها فالجمع بين وجود العقل وبين نفي كل علم ضروري جمع بين متنافيين والظاهر القول الأول بناء على أن العقل قبول القلب عادة للعلم وأضداده الخاصة كالظن والشك والوهم والجهل للركب وليس نفس العلم ولا ملزوما ً له ويدل على ذلك وجود المنية المتنكرين لما عدا المحسوسات من العوم ضرورية كانت أو نظرية ووجود السفسطائية المنكرين لجميع العلوم ضروريها ونظريها محسوسها وغير محسوسها، وهم من العقلاء بدليل تعرض الأئمة لبدعتهم في مناظرتهم لدفعها وتمثيلنا للواجب النظري يكون الواحد نصف سدس الأنثى عشر جلى فان هذا الحكم إنما يحصل للعقل بعد استحضار مقدمتين إحداهما وهي الصغرى ضرورية وهي قولنا الواحد نصف الاثنين والأخرى نظرية وهي قولنا ونصف الاثنين نصف لحدس الاثنى عشر لأنها موقوفة على معرفة كون الاثنين سدس الاثنى عشر بقسمتها إلى ستة أقسام متساوية وأن الاثنين أحد أقسامها الستة المتساوية فاذا استحضر العقل بالفكرة الدليل المركب من هاتين المقدمتين وهو أن الواحد نصف الاثنين ونصف الاثنين نصف سدس الاثنى عشر لأن الاثنتين سدس أقسامها الستة المتساوية علم حينئذ نتيجة هذا الدليل\r[المواهب اللدنية]\rفالسبب لها دخول وقتها وشرطها العقل ومانعها وقت المنع. والإغماء وضع سببا وشرطا ومانعا للمحرم كأكل الميتة فالسبب لها موتها حتف أنفها والشرط عدم الضرورة والمانع وجود الضرورة وضع سببا وشرطا ومانعا للمكروه كصيد اللهو فالسبب له اللهو والشرط عدم الضرورة والمانع وجود الضرورة ومنع سببا وشرطا ومانعا للمباح كالنكاح فالسبب له العقد والشرط خلو ّ العقد عن المانع وقوع النكاح في العدة مثلا (وهي) أي الأمارة (السبب والشرط والمانع) ووجه الحصر في الثلاثة أن ما يجعله الشارع أمارة على حكم من تلك الأحكام الخمسة أن يجعل كل واحد من وجوده وعدمه أمارة ودليلا، ويجعل عدمه فقط أو وجوده فقط. فالأول السبب والثاني الشرط والثالث المانع. فان قلت لم قدم السبب على الشرط والمانع. فالجواب إنما قدم السبب لقوته لأنه يؤثر بطرقيه أعني وجوده وعدمه وكانا بخلافه، ألا ترى أن الصلاة إذا أحرم بها قبل الوقت ولو بلحظة لم تجز بتخلف السبب فهو يؤثر بطرفيه بخلاف الشرط فان الزكاة إذا تقدمت على الحول بيسير تجزئ لأنه أخف إذ لا يؤثر إلا بظرف واحد. والحاصل أن اعتبار السبب وملاحظته أشد. {تنبيه} إطلاق خطاب الوضع على السبب والشرط والمانع بطريق التجوّز والمسامحة وإنما هي متعلقات خطاب الوضع الذي هو الخطاب النفسي كما يعلم من كلام المحقق العقلي وغيره فلا تغفل. فان قلت ما الفرق بين خطاب التكليف وخطاب الوضع. فالجواب كما قاله الإمام السيوطي والفرق بينهما من حيث الحقيقة أن الحكم بالوضع هو قضاء الشرع على الوصف بكونه سببا أو شرطا أو مانعا وخطاب التكليف لطلب أداء ما تقرر بالأسباب والشروط والموانع أهـ.\rثم أخذ في تعريف هذه الثلاثة كل واحد بانفراده وبدأ بالسبب فقال (فالسبب) لغة: الحبل قال الله تعالى ((مَن كَانَ يَظُنُّ أَن لَّن يَنصُرَهُ اللَّهُ فِي الدُّنْيَا وَالآخِرَةِ فَلْيَمْدُدْ بِسَبَبٍ إِلَى السَّمَاء)) واصطلاحا (ما) كالجنس شامل للثلاثة والدليل (يلزم من وجوده) أي السبب (الوجود) أي وجود المسبب فصل أول يخرج به الشرط والمانع (و) يلزم (من عدمه) أي السبب ... (العدم) أي عدم المسبب فصل ثان يخرج به الدليل على الحكم من الكتاب والسنة والإجماع والقياس فان الدليل يلزم طرده أي يلزم من وجودة الوجود ولا يلزم عكسه أي لا يلزم من عدمه العدم وأما السبب فانه يلزم طرده وعكسه (لذاته) يعني لذات السبب فالتقييد فيه بالذات راجع"], [14, "وهي أن الواحد نصف سدس الاثنى عشر وقس على هذا وبالله تعالى التوفيق (والمستحيل ما لا يتصور في العقل ثبوته إما بلا تأمل أيضا ً ككون الواحد نصف الأربعة وإما بعد التأمل ككون الواحد سدس الاثنى عشر مثلا) أما تمثيلنا للمستحيل الضروري يكون الواحد نصف الأربعة فظاهر للعام والخاص لأنه لما علم بالضرورة للجميع أن نصفها اثنان لزم أن يعرف بالضرورة انتقاء النصفية عن كل ما سواهما من واحد وغيره. وأما تمثيلنا للمستحيل النظري بكون الواحد سدس الاثنى عشر فهو باعتبار العوام لأنهم قد يجهلون قبل التأمل أن سدسها اثنان أو غيرهما فلا يعرفون ابتداء استحالة كون الواحد سدسا ً منها حتى يعرفوا أن سدس الاثنى عشر هو القسم الواحد من أقسامها الستة المتساوية والواحد ليس كذلك وإنما هو قسم من أقسامها الاثنى عشر المتساوية وأما بالنسبة إلى أهل الحساب لمعرفة استحالة كون الواحد سدس الاثنى عشر ضرورية والخطب في ذلك سهل ومقصودنا التقريب بالمثال والاعتراض على المثل ليس من أدب المحققين وبالله تعالى التوفيق. (والجائز ما يصح في العقل ثبوته ونفيه إما تأمل ككون الجسم أبيض مثلا ً وإما بعد التأمل كتمني الإنسان الموت مثلا ً) لا شك أن وجود البياض وعدمه للأجسام قد عرفه العقل ضرورة بالمشاهدة وصحة وجود الشيء وعدمه أعم من وجوده وعدمه فاذا كان الأخص ضروريا ً للعقل فأحرى أن يكون الأعم ضروريا.\rوأما الحكم على من تمنى الإنسان الموت بالجواز النظري فظاهر لكن في حق أهل العافية الذين لم يذوقوا المصائب التي هي أشد من الموت ويستسهل الموت ويتمنى عندها ولا خالطوا من وقع في ذلك ولا عرفوا المحن بالفكرة والتوهم فهؤلاء يتوهمون ابتداء أنه محال أن يتمنى العاقل الموت لنفسه فاذا فكروا في المحن عرفوا أن هنالك ما هو أشد من الموت فحينئذ يحكمون بأن تمنى العاقل الموت لنفسه ليس بواجب ولا مستحيل بل يصح وجوده إن خاف من المصائب ما هو أشد منه أو رجا شيئا ً عظيما لا يحصل له إلا به. وأما معرفة جواز تمنيه في حق من اتصف بأسباب ذلك خوفا أو رجاء أو اشتياقا فهي ضرورية لا تحتاج إلى تأمل لكن المثال المقصود منه التقريب فيصح التمثيل بما وجد على الجملة أو قدر وجوده وبالله تعالى التوفيق (فاذا عرفت هذا فاعلم أنه يجب لمولانا جل وعز الوجود لتوقف وجود الحوادث على وجوده تعالى والدليل حدوثها لزومها لما يفتقر إلى المخصص) يعني أنك إذا تصورت معنى الواجب والمستحيل والجائز سهل عليك حينئذ معرفة ما يجب لمولانا تبارك وتعالى\r[المواهب اللدنية]\rإلى الجملتين معا (كزوال الشمس) يعني ميلها عن كبد السماء بالنسبة (لوجوب) صلاة (الظهر) ولو قارن هذا السبب فقدان الشرط كعدم العقل لم يلزم من وجوده وجود الحكم الذي هو وجوب الصلاة وكذلك المانع كالحيض ولو خالف السبب سبب آخر لم يلزم من عدمه العدم كعدم سبب القتل مثلا وهي الردة مع وجود السبب الآخر وهي جناية القتل عمدا فاحترز منها بقوله لذاته يعني أن هذا اللزوم إنما هو بالنظر إلى ذاته وأما النظر إلى الأمور الخارجية فقد لا يلزم {تنبيه} ينقسم السبب إلى ثلاثة أقسام: سبب عقلي وسبب شرعي وسبب عادي مثال السبب العقلي الأجرام للأعراض والمعاني للعضوية إلا أن هذا تلازم ومثال السبب الشرعي رؤية هلال رمضان لوجوب الصوم ومثال السبب العادي: الطعام للشبع. ولما فرغ من تعريف السبب شرع في تعريف الشرط فقال (والشرط) في اللغة هو العلامة ومنه أشراط الساعة أي علاماتها قال الله العظيم (فَهَلْ يَنظُرُونَ إِلاَّ السَّاعَةَ أَن تَأْتِيَهُم بَغْتَةً فَقَدْ جَاء أَشْرَاطُهَا) أي علاماتها، وفي الاصطلاح (ما) كالجنس شامل الثلاثة (يلزم من عدمه) أي من عدم الشرط (العدم) أي عدم المشروط فصل أول يخرج به المانع (ولا يلزم من وجوده) أي وجود الشرط (وجود) أي وجود المشروط (ولا) يلزم (عدم) كذلك فصل ثان يخرج به السبب فانه يلزم من وجوده الوجود (لذاته) يعني لذات الشرط فالتقييد فيه بالذات راجع إلى الجملة الأخيرة. وأما الجملة الأولى فمعناها لازم على كل حال (كتمام الحول) أي كماله بالنسبة (لوجوب) إعطاء (الزكاة).\rولو قارن وجود الشرط لوجود السبب كما إذا قارن تمام الحول وجود النصاب فيلزم الوجود وهو وجود الزكاة لكن لا بالنظر إلى تمام الحول بل بالنظر إلى وجود السبب وهو النصاب ولو قارن وجود الشرط لوجود المانع كالآبق فيلزم العدم.\r{تنبيه} ينقسم الشرط إلى ثلاثة أقسام: شرط عقلي وشرط شرعي وشرط عادي مثال الشرط العقلي الحياة للادراك ومثال الشرط الشرعي الطهارة لصحة الثلاثة وتمام الحول لوجوب الزكاة ومثال الشرط العادي النطفة في الرحم. ولما فرغ من تعريف الشرط شرع في تعريف المانع فقال (والمانع) لغة: هو الحد، واصطلاحا (ما) كالجنس شامل للثلاثة ... (يلزم من وجوده) أي وجود المانع (العدم) يعني عدم الحكم الذي هو الصلاة فصل يخرج به السبب والشرط (ولا يلزم من عدمه) أي عدم المانع"], [15, "من الكمالات إذ الحكم بوجوبها لمولانا جل وعلا فرع تصور معنى الواجب وقد عرفته مما سبق، فمما يجب عقلا لمولانا جل وعز الوجود وهذا الواجب من القسم الثاني من قسمي الواجب العقلي وهو الواجب النظري فتتوقف معرفته بحسب ما أجرى الله تعالى به العادة على النظر العقلي وذلك أن تنظر في كل ما سواه تبارك وتعالى فتجده أجراما أي مقادير فراغا يأخذ من الفراغ كل واحد منها قدر ذاته طولا وعرضا وصفات تقوم بها من ألوان وأكوان وغيرهما وما من لون أو كون أو غيرهما إلا وهو جائز يصح وجوده وعدمه بدليل مشاهدة الأمرين فيه في كثير من الأجرام وما لم نشاهده فحكمه ما شاهدناه لاستواء الجميع في حقيقة الجرمية وكذلك ما من مقدار مخصوص للجرم في الطول أو العرض إلا وهو جائز يقبل الوجود والعدم بأن يوجد ما هو أكبر منه أو أصغر إلا أن يكون تناهى في الصغر إلى مقدار الجوهر الفرد وهو المقدار الذي لا يقبل التجزئة لا حسا ولا عقلا فيقبل حينئذ مقداره العدم بأن يوجد ما هو أكبر منه لا بأن يوجد ما هو أصغر منه إذ لا أصغر منه وقبول كل مقدار مخصوص وكل صفة من صفاته للوجود والعدم هو لازم ذاتي لا يمكن انفكاكه عنه ضرورة وهذان الأمران المقبولان وهما الوجود والعدم متساويان في القبول والجواز لا ترجيح لأحدهما على الآخر من حيث ذاته فاذا يستحيل عقلا أن يكون جرم من الأجرام أو صفة من صفاته قديما لم يسبق وجوده عدم لما يلزم عليه من ترجيح وجود المقدار المخصوص الجائز على عدمه المساوي له في القبول والجواز وترجيح وجود صفته المخصوصة الجائزة على مقابلتها بلا مرجح وذلك جمع بين متنافيين وهما الاستواء والرحجان وذلك لا يعقل، فاذا قد دل كل ما سوى مولانا تبارك وتعالى من جهة مقداره المخصوص وصفته المخصوصة على أمرين أحدهما وجوب وجود المولى تبارك وتعالى ليرجح بإرادته مقدار كل جرم وصفته المخصوصين على مقابلهما ويوجد ما شاء من ذلك على وفق إرادته.\rالثاني الحدوث لكل جرم وصفاته لما ثبت من طريق الجواز من وجوب افتقارها للفاعل لأن لا يكون إلا واجبا غنيا من الفاعل. فإن قلت ما المانع أن يكون ما سوى الله قديما ويكون الترجيح لوجود مقاديره وصفاته بطريق التعليل أو الطبع لا بطريق الاختيار. فالجواب أنه لو كان كذلك لما اختلفت مقاديره وصفاته ولما تأخر منها شيء عن الأزل لأن العلة الواحدة والطبيعة الواحدة يستحيل اختلاف آثارهما أو تأخر شيء منها عن جودهما في الأزل والمشاهدة الضرورية تقضي بخلاف ذلك لأن اختلافهما في مقاديرها\r[المواهب اللدنية]\r(وجود) أي وجود الحكم وهو الصلاة لتوقفه على سبب وهو دخول الوقت فقد لا يحصل (ولا) يلزم (عدم) أي للحكم كذلك (لذاته) يعني لذات المانع فالتقييد فيه بالذات راجع إلى الجملة الأخيرة وأما الجملة الأولى فمعناها لازم على كل حال (كالحيض) يعني وجوده بالنسبة (لوجوب) إسقاط (الصلاة) ولو قارن عدم المانع عدم السبب فيلزم عدمه لكن بالنظر إلى عدم السبب وهو عدم زوال الشمس {تنبيه} ينقسم المانع إلى ثلاثة أقسام: مانع عقلي ومانع شرعي ومانع عادي، مثال المانع العقلي الموت بالنسبة للمعاني فقط فتأمل وإما مع الموت إذ يكون المخالف ميتا أو الواحد ونحو ذلك. ومثال المانع الشرعي الحيض بالنسبة إلى وجوب الصلاة. ومثال المانع العادي الشهوة الكلية بالنسبة للشبع. فان قلت لم قدم الشرط على المانع وكان حقه أن يقدم المانع لأنه يؤثر في الوجود والشرط يؤثر في العدم والذي يؤثر في الوجود أولى بالتقديم. فالجواب لما كان الشرط شرطا في صحة العبادة والمانع مانع منها قدم الشرط على المانع لذلك فان قلت أي ّ نسبة بين خطاب التكليف وخطاب الوضع. فالجواب نسبة العموم والخصوص من وجه يجتمعان في النكاح من حيث سبب الإباحة هو خطاب وضع ومن حيث هو مندوب هو خطاب تكليف وكذلك الطهارة من حيث كونها شرطا وضعية ومن حيث هي واجبة تكليفية وينفرد الوضع بزوال الشمس وأوقات الصلوات فهي وضعية ولا تكليف فيها وينفرد التكليف بدون الوضع في الإيمان والكفر فان الإيمان سبب في عصمة الدم والكفر سبب في إباحته.\rولما فرغ من الكلام على الحكم الشرعي التكليفي والوضعي شرع الآن في الكلام على الحكم العادي فقال (وأما الحكم العادي) في اللغة ربط سبب بآخر، وفي الاصطلاح (فهو إثبات الربط) أي القرآن (بين أمر) يعني سواء كان الأمر وجوديا كالأكل (وأمر) يريد عدميا كعدم الأكل فينشأ عن الأكل الشبع ونفي الجوع وينشأ عن عدمه الجوع ونفي الشبع فالسبب على هذا اثنان وهو الأكل وعدمه وينشأ عن كل واحد منهما اثنان فتأمله (وجود) أي في المربوط به أو في أحدهما (وعدما) أي كذلك لتدخل الأقسام الأربعة وهي ربط وجود بوجود وربط عدم بعدم وربط وجود بعدم وربط عدم بوجود فاثبات الربط بين أمر وأمر الخ كالجنس شامل للحكم الشرعي كربط وجوب الظهر بوجود الزوال وعدم وجوبها بعدم وجود الزوال وشامل للحكم العقلي كربط وجود المعنوية"], [16, "وصفاتها كثيرة لا حصر له وتأخير جميعها عن الأزل معلوم على القطع لمشاهدة التأخير في كثير من الأجرام وصفاتها اللازمة لها فوجب أن يكون جميعها كذلك لوجوب استوائها في صفة الافتقار إلى الفاعل. فان قلت لا شك أن تأخير الأجرام وصفاتها عن الأزل يدل قطعا على أن إيجادها ليس على طريق التعليل إذ العلة العقلية يستحيل مفارقتها لمعلولها. وأما دلالة التأخير على أن الإيجاد ليس بطريق الطبع فقد لا يسلم لما تقرر أن تأثير الطبيعة عند من يقول بها من المبتدعة ليس على طريق اللزوم بكل حال بل إنما يلازمها مطبوعها إذا توفرت الشرائط وانتفت الموانع فعلى هذا تأخير العوالم عن الأزل لوجود مانع منع منها في الأزل وانتفاء شرط هناك.\rفالجواب أنه لو وجد مانع يمنع من وجود العوالم في الأزل لما انتفى أبدا لأن ما ثبت قدمه استحال عدمه فيلزم أن لا يوجد شيء من العوالم أبدا ولو انتفى شرط وجود العوالم في الأزل لما وجد ذلك الشرط أبدا فلا يوجد أيضا شيء من العوالم أبدا لأن وجود ذلك الشرط فيما لا يزال متوقف على انتفاء مانع أزلي أو تسلسل شرائط إلى غير أول وكلاهما محال فقولنا في أصل العقيدة لتوقف وجود الحوادث على وجوده تعالى يتحقق المجرور باللام وهو لتوقف باعلم لا بقولنا يجب لمولانا جل وعز الوجود لما يلزم عليه أن يكون وجوب الوجود له تبارك وتعالى إنما ثبت له بعد وجود الحوادث كيف ووجوب الوجود لمولانا تبارك وتعالى قديم قيل وجود الحوادث غير معطل بوجودها نعم وجود الحوادث سبب عادة في علمنا بوجوب وجوده تعالى فلذلك وجب تعليق هذا المجرور باللام بقولنا اعلم لا بالمضارع في قولنا يجب أي اعلم وجوب الوجود لمولانا تبارك وتعالى من أجل معرفتك بتوقف وجود الحوادث على وجوده تعالى لاستحالة ترجيح وجودها الجائز على عدمها المساوي له في القبول والجواز بلا مرحج وكذلك يستحيل ترجيح وجود زمانها المخصوص ومكانها المخصوص وجهتها المخصوصة على ما يقابلها بلا مرجح وكذلك يستحيل ترجيح مقاديرها المخصوصة وصفاتها المخصوصة إن كانت أجراما على ما يقابلها من غير مرجح وإنما توقف وجود الحوادث على كون وجود فاعلها واجبا لا على مطلق وجوده وإن كان جائزا لأن تقدير جواز الوجود له يستلزم استحالة الوجود له على ما يأتي في برهان القدم فتعين أن يكون وجودها موقوفا على كون وجود فاعلها واجبا لا جائزا قوله ودليل حدوثها لزومها لما يفتقر إلى المخصص يعني أن الحوادث تنقسم إلى أجرام وأعراض وهي الصفات التي تتصف بها الأجرام ولا شك أن الأعراض لا يفارقها التغيير حصولا أو قبولا\r[المواهب اللدنية]\rبوجود المعاني وعدم وجودها بعدم وجود المعاني (بواسطة التكرر) فصل يخرج به العقل والشرعي فانهما لا بواسطة التكرر وبقي الحد لمحدوده والجار والمجرور يتعلق بالمصدر الذي هو إثبات. فان قلت هل يكفي في التكرر مرتان. فالجواب نعم يكفي كما هو ظاهر. قولهم التكرر: ذكر الشيء مرة بعد أخرى (مع صحة التخلف) فيوجد الإحراق ولا توجد النار ولا يوجد الإحراق، وتوجد السكين ولا يوجد القطع، ويوجد الشبع ولا يوجد الأكل ويوجد الأكل ولا يوجد الشبع (وعدم تأثير أحدهما) يعني السبب (في الآخر) أي في المسبب (ألبتة) بفتح الهمزة أي القطع أي فليس الحار هو الذي أثر في البارد ولا البارد هو الذي أثر في الحار عند اجتماعهما وإنما يخلق الله تعالى حالة وسطا وهي انكسار صولة الحار بالبارد وصولة البارد بالحار. فان قلت ثوله مع صحة التخلف الخ هل هو من تمام الحد أو زيادة بيان. فالجواب قيل هو من تمام الحد بناء على أن الجهل ببعض الصفة يستلزم الجهل بالموصوف وقيل زيادة بيان بناء على أن الجهل ببعض الصفات لا يستلزم الجهل بالموصوف. ولما فرغ من تعريف الحكم العادي أخذ الآن في ذكر أقسامه فقال (وأقسامه) الضمير يحتمل عوده على الحكم ويحتمل عوده على الربط والذي يؤخذ من شرح المصنف رحمه الله تعالى عوده على الربط فتأمله (ربط وجود) السبب (بوجود) السبب (كربط وجود الشبع) بكسر الشين وفتح الموحدة نقيض الجوع وبسكونها اسم لما يشبع قاله الإمام الشمني رحمه الله تعالى.\r(بوجود الأكل و) الثاني (ربط عدم) المسبب (بعدم) السبب (كربط عدم الشبع) وهو السبب (بعدم الأكل) وهو السبب (و) الثالث (ربط وجود) نقيض المسبب (كربط وجود الجوع بعدم الأكل) الذي هو السبب (و) الرابع (ربط عدم) نقيض المسبب وهو الجوع (بوجود) السبب وهو الأكل (كربط عدم الجوع بوجود الأكل) والضابط في هذا أنك تثبت الشبع وتنفيه وتثبت الجوع وتنفيه ما يرتبط بكل قسم فيرتبط ثبوت الشبع بثبوت الأكل واعلم أن للحكم العادي سببا وشرطا ومانعا مثال سببه الأكل ومثال شرطه عدم الشهوة الكلية، ومثال مانعه وجود الشهوة الكلية. ولما فرغ من الكلام على تعريف الحكم العادي شرع الآن في الكلام على تعريف الحكم العقلي فقال (وأما الحكم العقلي)"], [17, "إن قدّرنا بقاءها والتغيير يستلزم الحدوث والافتقار إلى الفاعل وينافي القدم إذ القديم لا يكون إلا واجبا فلا يقبل التغيير. واما الأجرام فلازمة للصفات المتغيرة المفتقرة إلى الفاعل وملازمة للمقادير والأمكنة المخصوصة المفتقرة إلى المخصص فاذا جميع العوالم لا تنفك عما يحوجها إلى الفاعل فتكون كلها حادثة.\rمن الصفات الواجبة له تعالى: القدم والبقاء والمخالفة للحوادث\r("]], "pg": [9, 17]}, "516.7": {"x": [[17, "ويجب له تعالى القدم والبقاء وإلا لكان محتاجا إلى الفاعل فيكون حادثا فيجب له من العجز ما وجب لسائر الحوادث بل يكون حينئذ وجوده مستحيلا لما يلزم على تقدير حدوثه من الدور أو التسلسل المستحيلين) يعني أنه يجب له تبارك وتعالى أن يكون قابل للعدم في الأزل وهو معنى القدم ولا فيما لا يزال وهو معنى البقاء إذ لو كان قابلا للعدم لما كان واجب الوجود بل يكون جائز الوجود وكل جائز فهو مفتقر إلى الفاعل كسائر الجائزات فيكون حادثا مثلها وذلك مستحيل لوجهين: أحدهما أنه يلزم أن يكون عاجزا ً كسائر الحوادث لمساواته لهما في الحدوث والجواز فلا يصح إسناد شيء من الحوادث إليه لعموم العجز عن الإيجاد لكل حادث وإنما يلزم عجزه عن الإيجاد من أجل المّانع بينه وبين موجده الذي افتقر إليه وأيضا ً إسناد الممكنات إليه بالخصوص دون موجده تخصيص بلا مخصص وأيضا ً فليس إسناد سائر الممكنات إليه بالخصوص بأولى من العكس.\rالثاني أنه يلزم أن يكون وجوده حينئذ مستحيلا لا يتصور في العقل ثبوته لأنه إذا قدّر قبول ذاته العدم صار جائزا ً مفتقرا ً إلى الفاعل ويلزم أن يكون فاعله جائزا مفتقرا إلى الفاعل لأنه مثله في الألوهية ثم ننقل الكلام إلى فاعل الفاعل ثم كذلك أبدا فإن انتهى العدد وانحصر لزم الدور فيلزم أن يكون الأول الذي انتهى إليه العدد إنما أوجده بعض من بعده ممن تأخر وجوده عنه فيكون سابقا ً عليه في الوجود متاخرا ً عنه وذلك لا يعقل وإن لم ينته العدد بل تسلسل إلى غير أول لزم وجود ما لا نهاية له عددا ً والفراغ من ذلك فيما مضى وذلك لا يعقل إذ ما لا نهاية له من الأعداد كأنفاس أهل الجنة وأزمنتهم ونعيمهم مثلا لا يسعه إلا المستقبل بأن يوجد فيه شيئا فشيئا ً أبد الأبد. وأما أن يوجد كله في الحال والماضي فلا يعقل فقولنا بل يكون وجوده حينئذ مستحيلا ً إضراب انتقال من لازم محال إلى لازم أشد منه في الاستحالة لا إضراب إبطال، وبالله تعالى التوفيق (ويجب له تعالى أن يكون مخالفا ً في ذاته وصفاته لكل ما سواه من الحوادث وإلا كان حادثا ً مثلها) يعني أنه لما تقرر بالبرهان القطعي فيما سبق وجوب القدم والبقاء له تعالى لزم أن تكون ذاته العلية وصفاته المرتفعة ليستا من جنس الحوادث فيستحيل على ذاته وصفاته الجرمية\r[المواهب اللدنية]\rأي المنسوب إلى العقل واشتقاقه من عقل البعير يجامع الرد ّ، وهو لغة المنع لمنع صاحبه من العدول عن سواء السبيل، واصطلاحا جوهر لطيف تدرك به الغائبات لوسائط والمحسوسات بالمشاهدة والمراد بالغائبات الأمور الكلية، والمراد بالمحسوسات الأمور الجزئية المشاهدة للأعيان، ومحل العقل القلب بشهادة ((أم لهم قلوب يعقلون بها)) ونوره في الدماغ كما ذهب إليه الإمامان مالك والشافعي رحمهما الله تعالى وجمهور المتكلمين، والدليل على جوهرية العقل ما ورد في الحديث الشريف عنه صلى الله عليه وسلم أنه قال ... ((أول ما خلق الله العقل قال له أقبل فأقبل ثم قال له أدبر فأدبر ثم قال له اقعد فقعد ثم قال له قم فقام فقال وعزتي وجلالي ما خلقت خلقا ولا شيئا أعز علي ّ منك، بك آخذ وبك أعطي)) وفي بعض الروايات: ((بك أعبد وبك أعصى)) ولو كان عرضا ما تأتي منه هذه الحركات التي لا تكون إلا للجواهر قبل العقل ألف جزء في جميع الخلق جزء واحد والباقي للمصطفى صلى الله عليه وسلم. فان قلت هل العقل أفضل من العلم أم العلم أفضل. فالجواب كما قال الإمام السيوطي أن العلم أفضل، لأنه أحد أوصافه تعالى دون العقل. فان قلت ما حكمة إضافة الحكم هنا إلى العقل دون غيره من سائر الأحكام. فالجواب أن مجرد العقل كاف في إدراك هذا الحكم إما مع فكرة ويسمى نظريا أو دون فكرة ويسمى ضروريا وأما الحكم العقلي (فهو إثبات أمر) كإثبات القدم الذاتي له تعالى وكالواحد نصف الاثنين وكالتحيز للجرم (أو نفيه) كنفي الحدوث عنه تعالى وكنفي الواحد أنه ليس بنصف الأربعة فاثبات أمر أو نفيه كالجنس في الحد (من غير توقف) أي استناد (على تكرر) فصل يخرج به الحكم العادي. فان قلت ها نحن نثبت إسهال السقمونيا للصفراء وإن لم يتكرر عندنا ولا جربناه.\rفالجواب إنما أثبتنا هذا الحكم بواسطة التجربة التي صدقنا فيها لأطباء وليس شرط التجربة في الحكم العادي أن تكون من كل واحد بل هو المسند لثبوت الحكم العادي وإن حصل من النفع المنوط بتجربته (ولا وضع واضع) يعني جعل جاعل فصل يخرج به الحكم الشرعي. فلن قلت كيف يصح في الحكم الشرعي أنه حصل بالوضع وهو خطاب الله تعالى قديم والقديم ليس بموضوع. فالجواب المراد بالحكم الشرعي التعلق التنجيزي لخطاب الله تعالى القديم وهو ليس بقديم وإطلاق الحكم الشرعي على التعلق التنجيزي مشهور عند الفقهاء والأصوليين. ولما فرغ"], [18, "والعرضية وكل لازم من لوازمها المقضية للحدوث كالمقادير والجهات والأمكنة والقرب والبعد بالمسافة والصغر والكبر والمماسة والحركة والسكون إذ لو اتصفت ذاته العلية أو صفاته المرتفعة بمماثلة الحوادث لزم ان يكون حادثا ً. أما لزوم حدوثه في مماثلة ذاته للحوادث فظاهر، وأما لزوم حدوثه في مماثلة صفاته للحوادث فانه لما لزم حينئذ أن تكون صفاته حادقة والذات يستحيل عروّها عن الصفات لزم أن تكون الذات حادثة مثل صفاتها لأن ملازم الحادث حادث ضرورة وهذا معنى قولنا وإلا كان حادثا ً مثلها أي وإن لم يكن مخالفا ً في ذاته وفي صفاته للحوادث بل كان مماثلا للحوادث فيهما أو في أحدهما لزم حدوث ذاته على كل تقدير من ذلك وبالله تعالى التوفيق.\rقيامه بنفسه، ومعنى ذلك\r("]], "pg": [17, 18]}, "516.8": {"x": [[18, "ويجب له تعالى أن يكون قائما ً بنفسه أي ذاتا ً موصوفا ً بالصفات غنيا ً عن المحل والفاعل إذ لو كان في محل لكان صفة فيلزم أن لا يتصف بالصفات الوجودية ولا لوازمها إذ لو قبلت الصفة صفة وجودية لزم أن لا تعرى عنها صفة كالذات وذلك يستلزم التسلسل ودخول ما لا نهاية له في الوجود ولو كان محتاجا ً إلى الفاعل لكان حادثا ً وهو محال) اعلم أن هنا مقدّمتين باطلتين يعتقدهما العقل الناقص تبعا ً للوهم الفاسد: إحداهما أن كل ما ليس بجرم أو حادثا ً فهو صفة ومستند الوهم في اعتقاد هذه المقدمة استقراء الحوادث فان ما ليس بجرم فيها فهو لا يكون إلا صفة فعمم ذلك الوهم الفاسد في حقه تعالى وقاس من غير جامع فاعتقد أن الله تعالى صفة لا ذات لما ثبت بالبرهان القطعي أنه ليس بجرم وقد قال بمقتضى هذا الفاسد النصارى وبعض الباطنية ممن ينتسب في زعمه إلى طريق التصوّف وهو كفر صراح.\rالمقدمة الثانية الباطلة أن كل ذات موصوف بالصفات فهو جرم وهذه القضية لازمة للقضية الأولى إذ هي في معنى عكس نقيضها الموافق الذي هو كل ما ليس بصفة فهو جرم ومستند الوهم في اعتقاد هذه القضية هو مستنده في القضية الأولى وهو النظر إلى ما تقرر في الحوادث والقياس عليها من غير جامع فاعتقد بهذا النظر الفاسد أن الذات العلية جسم لما قام البرهان القطعي على أنه تعالى ذات موصوف بالصفات العلية لا صفة وقد قال أيضا ً بمقتضى هذا الوهم الفاسد في هذه القضية المجسمة كالحشوية واليهود ومن تبعهم على ذلك ومنهم من اعتقاد هذه المقدّمة الباطلة وقادته إلى تعطيل وهي نفي وجود الإله أصلا وأن العوالم وجدت وجودا اتفاقيا بغير فاعل لأنه لما استقر في الحوادث أن الفاعل منها لا يكون إلا جسما قاس من غير جامع وقال لو كان للعوالم فاعل لوجب أن يكون جسما لكن الجسم يستحيل منه إيجاد\r[المواهب اللدنية]\rمن تعريف الحكم العقلي شرع الآن في تقسيمه (وأقسامه) أي أقسام الحكم العقلي بمعنى المحكوم به وكثيرا ما يطلقون الحكم بذلك المعنى قال بعضهم إنه يطلق بطريق الاشتراك عليه فيكون في كلام المصنف رحمه الله تعالى استخدام وحينئذ فلا يحتاج إلى تكلف في عبارة المصنف رحمه الله تعالى ونفعنا به. وأقسام جمع قسم بكسر القاف نحو حمل وأحمال وقرب وأقراب وهذا بيانها (ثلاثة) الأول (الوجوب) وهو عبارة عن نفي قبول العدم (و) الثاني (الاستحالة) وهو عبارة عن نفي قبول الوجود (و) الثالث (الجواز) وهو عبارة عن قبولهما. فان قلت تقسيم الحكم العقلي إلى هذه الثلاثة هل هو من باب تقسيم الكل إلى أجزائه أو إلى جزئياته. فالجواب ليس من تقسيم الكل إلى أجزائه ولا إلى جزئياته لعدم صدق المنقسم على كل واحد بانفراده. فان قلت بناء على تقدير مضاف وهو إثبات الوجوب وإثبات الاستحالة وإثبات الجواز هل يصح أن يكون من باب تقسيم الكلي إلى جزئياته. فالجواب يصح أي يتعين لوجود ضابطه الذي هو المنقسم على كل من الأقسام ألا ترى أنه يصح أن يقال إثبات الوجود أو إثبات الاستحالة أو إثبات الجواز حكم عقلي، ويصح أن يقال الوجوب أو الاستحالة أو الجواز متعلق الحكم العقلي ووجه الحصر في الثلاثة أن كل ما يحكم به العقل إما أن يقبل الثبوت فهو الواجب أو يقبل النفي فقط فهو المستحيل أو يقبلهما معا فهو الجائز. ولما كان تعريف الواجب والمستحيل والجائز يستلزم معرفة الوجوب والاستحالة والجواز لأنها أخص ومعرفة الأخص تستلزم معرفة الأعم أشار إلى ذلك بقوله (فالواجب) الفاء فصيحة وأل للعهد (ما) أي معلوم أو مفهوم أو مذكور كالجنس (لا) نافية (يتصور) أي لا يحصل (في العقل) يتعلق بقوله لا يتصور صورة (عدمه) أي ذلك المعلوم أو المفهوم أو المذكور أو ما صدقاته أي أفراده في العقل بل ليس الحاصل في العقل إلا وجود تلك الماصدقات لذلك المفهوم، وقوله لا يتصور في العقل عدمه فصل يخرج به الجائز والمستحيل وبقي الحد لمحدوده وعدمه معناه لا يتصور إلا وجوده فظاهره أن كل واجب موجود وليس كذلك بل ثم شيء واجب لله تعالى وليس بموجود وهي الصفات المعنوية والسلبية وعلى هذا لا يقدر على ما ذكر لخروج هذه الصفات الواجبة لله تعالى وإنما يقدر ما لا يتصور في العقل إلا ثبوته فيكون ذلك شاملا لجميع ما يجب في حقه تعالى جل ثناؤه"], [19, "الأجرام وكثير من الصفات فتعين أن أجسام العوالم وجدت بلا فاعل، فاذا عرفت هذا عرفت أن وجوب قيامه تعالى بنفسه يدفع هاتين المقدمتين الباطلتين لأن معناه احتوى على جزءين:\rأحدهما كونه تعالى غنيا ً عن المحل أي عن ذات يقوم بها ويكون لها فهو جل وعلا ذات موصوف بالصفات العلية لا صفة لغيره. الثاني كونه جل وعلا غنيا ً عن الفاعل واجب الوجود لا جائزة، فالجزء الأول أبطل المقدمة الأولى وهي اعتقاد الوهم الفاسد أن كل ما ليس بجزم فهو صفة لغيره فإن مولانا جل وعلا ليس بجزم وهو مع ذلك ذات موصوف بالصفات ويستحيل أن يكون صفة لغيره، والجزء الثاني أبطل المقدمة الثانية وهي اعتقاد الوهو أن كل ذات موصوف بالصفات فهي جرم فان مولانا جل وعز ذات موصوف بالصفات وهو مع ذلك يستحيل أن يكون جرما ً أو مماثلا ً لشيء من الحوادث فهو تعالى ذات حقيقة ولا مثل له من الذوات وبهذا الجزء الثاني باينت ذاته تعالى سائر الذوات الحادثة فإنها كانت غنية عن المحل أي لا تكون صفة قائمة بغيرها فهي مفتقرة إلى الفاعل افتقارا ً لازما ً لايمكن انفكاكها عنه لوجوب حدوثها وافتقارها إلى المولى الكريم ابتداء. والحاصل أن بالجزء الأول من معنى القيام بالنفس باين جل وعلا سائر الصفات فليس من جنسها وبالجزء الثاني باين تبارك وتعالى سائر الذوات فلا شبيه له منها ولا يشاركها في أجناسها ولا في فصولها فقولنا في أصل العقيدة أي ذاتا ً موصوفا ً بالصفات غنيا ً عن المحل هو تفسير للجزء الأول من القيام بالنفس وهو الذي منع كونه تعالى صفة وزيادتنا الوصف يغنيا عن المحل بعد قولنا ذاتا ً موصوفا بالصفات للتأكيد وإلا فكل ذات موصوفة بالصفات فهي غنية عن المحل أي عن ذات تقوم بها وقولنا والفاعل هو تفسير للجزء الثاني من جزأي القيام بالنفس وهو الذي منع ثوهم كون ذاته تعالى تشبه شيئا ً من الذوات.\rأما برهان الجزء الأول وهو أنه تعالى ذات لا صفة فما أشرنا إليه في أصل العقيدة وهو أنه تعالى لو كان صفة لزم أن لا يتصف بالصفات الوجودية وهي صفات المعاني التي هي القدرة والإرادة والعلم والحياة والسمع والبصر والكلام ولا بلوازمها التي هي الصفات المعنوية وهي كونه قادرا ً ومريدا ً وعالما ً وسميعا ً وبصيرا ً ومتكلما ً والدليل القطعي دل على وجوب اتصافه تعالى بها فليس بصفة لأن الصفة لو قبلت أن تتصف بالصفات الوجودية لاستحال عرو ّ كل صفة عنها كما في الذوات لأن القبول نفسي فلا يتخلف وذلك يستلزم التسلسل ودخول ما لا نهاية له في الوجود لأنه يجب لصفة الصفة ما وجب\r[المواهب اللدنية]\rوأن الطالب حين إيرادها يقول اشتراط كون الحد ّ جامعا مانعا غير متفق عليه فقد حوّز بعضهم كونه غير جامع بأن يكون أخص خصوصا في التعاريف اللفظية التي منها هذا التعريف. فان قلت هل يجوز أن تكون مافي قول المصنف رحمه الله تعالى مالا يتصور في العقل واقعة على موجود أو شيء. فالجواب نعم يجوز وحينئذ فلا ترد عليه السلوب إذ هي ليست بموجودة ولا شيء ويكون التعريف قاصرا على واجب الوجود لذاته وهو الله سبحانه إذ لا واجب بالذات إلا هو وعلى صفاته الذاتية سواء قلنا إنها واجبة الوجّود لذاتها كما وقع في عبارة بعضهم وإليه يميل المصنف رحمه الله تعالى ونفعنا به أو لموضوعها. ولما كان الواجب العقلي ينقسم إلى ستة أقسام ذاتي وعرضي وإثباتي ومنفي وضروري ونظري أشار إلى الضروري والنظري ممثلا لكل واحد منهما بقوله (إما ضرورة) أي بديهة وهو ما يدركه العقل بلا تأمل (كالتخيز) أي ثبوته (للجرم) وهو أخذه قدر ذاته من الفراغ بحيث يسكن فيه أو يتحرك ويمنع غيره أن يحل محله فان وجوب هذا المعنى له ضروري للعقل فلا بفتقر إلى تأمل، وأفاد بقوله (مثلا) أن التحيز لا يختص بالجرم فلا يخرج الجوهر الفرد (وإما نظرا) وهو ما يدركه العقل بعد التأمل (كوجوب العدم) الذاتي (لمولانا) أي فخالقنا وناصرنا ومتولي أمورنا (جل) اتصف بالرفعة التي لا تماثل وتنزهه عما لا يليق به (وعلا) ارتفع عن أن يحاط بمنزلته الرفيعة فان وجوب هذا له إنما يدركه العقل بالتأمل فما يترتب على نفيه من المستحيلات كالدور والتسلسل وتعدد الإله وتخصيص كل واحد منهم بنوع من الممكنات بلا مخصص ومثال الواجب الذاتي كوجود مولانا جل وعلا ومثال الواجب العرضي كدخول الصحابة العشرة الجنة ومثال الواجب الإثباتي كإثبات الألوهية لله تعالى وسائر الكمالات ومثال الواجب المنفي كنفي النقائص عنه تعالى.\rولما فرغ من ذكر الواجب شرع في ذكر المستحيل فقال (والمستحيل) اسم فاعل من استحال عقلا من الإحالة التي هي عدم قابلية الوجود والسين والتاء فيه للطلب أي طلب الشارع من المكلف نفي الشريك عن الباري عز اسمه والواو فيه يصح أن تكون عاطفة ويصح أن تكون للاستئناف (ما) أي مفهوم أو مذكور ممتنع بقرينة مقابلته بالواجب وهي بمنزلة الجنس فيشمل الممتنع بالغير وما بعدها بمنزلة الفصل مخرج له (لا) نافية (يتصور) أي لا يدرك، والإدراك وصول الشيء إلى المعنى بتمامه (في العقل) على"], [20, "للصفة الأولى من الاتصاف بالصفات الوجودية ثم هكذا إلى ما لا نهاية له وذلك لا يعقل ومن هنا تعرف استحالة قيام الصفة بالصفة وأن قبول الاتصاف بالصفات الوجودية ولوازمها من خصائص الذوات لا مشاركة بينها وبين الصفات وإنما خصصنا البرهان بالصفات الوجودية ولوازمها لأنها هي التي تقوم بموصوفها ويلزم فيها دخول ما لا نهاية له في الوجود أما الصفات النفسية فهي راجعة إلى حقيقة موصوفها ولا تسلسل لها وأما الصفة السلبية فلا وجود لمعانيها في الخارج فلا يلزم من تقدير تسلسلها دخول ما لا نهاية له في الوجود ولهذا كان الاتصاف بهذين النوعين مشتركا بين الذوات والصفات ولهذا توصف الذات العلية وصفات المعاني القائمة بها بالوجود والقدم والبقاء والمخالفة للحوادث والوحدانية. وأما برهان الجزء الثاني فواضح لا يحتاج إلى بيان وبالله تعالى التوفيق.\rالوحدانية في الذات والصفات والأفعال\r("]], "pg": [18, 20]}, "516.9": {"x": [[20, "ويحب له تعالى الوحدانية أي لا مثل له في ذاته ولا في صفة من صفاته ولا مؤثر له في فعل من الأفعال إذ لو كان معه مثل أو مؤثر لما كان واجب الوجود لاحتياجه حينئذ إلى من يخصصه بما يمتاز به عما يماثله عموما ً أو خصوصا ً وذلك يستلزم الحدوث والعجز عن كل ممكن) لا شك أن وجود المثل له تعالى يستلزم أن يكون كل واحد من المثلين حادثا جائزا ويمتنع أن يكون كل واحد منهما قديما واجبا وبرهان ذلك أن المثلين لما استحال أن يكون أحدهما عين الآخر لزم أن يمتاز أحدهما عن الآخر وتمييزه لا يمكن أن يكون بالذاتيات الواجبات لوجوب اشتراك المثلين في جميعها فتعين أن يكون بعرضي جائز اختص به أحدهما عن الآخر مع جواز أن يكون لصاحبه إذ كل ما اتصف به أحد المثلين من الجائزات فانه يجوز أن يتصف به مماثلة وكل جائز فوجوده لا يكون إلا حادثا فتعين أن يكون العرضى الذي امتاز به كل من المثلين عن الآخر حادثا وكل من المثلين ملازم لهذا العرضى الذي يميزه عن صاحبه فتعين أن يكون هو أيضا حادثا لأن ملازم الحادث حادث والحدوث ينافي الألوهية لما عرفت في برهان قدم الإله وبقائه وايضا ذلك العرضى إما أن يكون كمالا فقدفات الآخر وفوت الكمال نقص فيلزم أن يكون كل واحد منهما ناقصا وهو محال وإن كان ذلك العرضى نقصا لزم أيضا اتصاف الإله بالنقص من أول مرة وهو ظاهر الاستحالة وأبضا تعدد الإله أما أن يكون بعدد خاص متناه فيلزم افتقاره إلى المخصص فيكون حادثا وإما أن يكون بعدد لا نهاية له فيلزم دخول ما لا نهاية له في الوجود وهو ظاهر الاستحالة وأيضا يلزم أن يكون كل واحد منهما عاجزا عن كل ممكن لمساواتهما في الإمكان والحدوث لسائر الحوادث التي قد عرفنا\r[المواهب اللدنية]\rما هو الظاهرمن بناء يتصور للمجهول أو ما لا يمكن (وجوده) أي ثبوته على أنه مبني للمعلوم والضمير في وجوده يرجع لما صدق الفهوم الذهني كما يتبادر إلى فهم بعض الطلبة على ما قلناه قول المولى سعد الدين في حاشية العضد ما نصه وحاصل معنى قولنا اجتماع النقيضين ممتع أن المعنى الحاصل في الذهن من هذا اللفظ ممتنع أن يوجد في الخارج فرد يطابقه اهـ كلامه رحمه الله ولما كان المستحيل ينقسم إلى ستة أقسام ذاتي وعرضي وإثباتي ونفي وضروري ونظري أشار إلى الضروري والنظري ممثلا لكل واحد منهما بقوله (إما ضرورة) أي بديهة وهو ما يدركه العقل بلا تأمل (كتمرى) يعني تجرد (الجرم عن الحركات والسكون معا) بحيث لا يتصف بواحد منهما فانه لا يخفى أن الحكم باستحالة هذا العروض ضروري للعقل إذ الجرم ما له حيز أي قدر من الفراغ فهو أن يثبت فيه فيكون ساكنا أو ينتقل عنه فيكون متحركا وكونه لا يثبت في حيازه ولا ينتقل عنه مستحيل ضرورة وهذا معنى ولهم الحركة كونان في آنين في مكانين والسكون كونان في آنين في مكان واحد وعلى كل من التفسيرين لا يكون الجرم في أول حدوقه متحركا ولا ساكنا وإنما وصف بهما بعد تقرره في الخارج فاعرفه فأنه نفيس (وإما نظرا) هو ما يدركه العقل بعد التأمل ... (كالشريك) أي المشارك (لمولانا) أي لخالقنا وناصرنا ومتولي أمورنا (جل) اتصف بالرفعة التي لا تماثل وتنزه عما لا يليق به (وعز) انفرد بصفة الجلال أو غلب قاهر لجميع الأشياء.\rفان استحالة الشريك على الله تعالى لا تترك إلا بعد النظر والتأمل ومثال المستحيل الذاتي كون الذات العلية جرما تعالت ومثال المستحيل العرضي كدخول الصحابة العشرة النار ومثال المستحيل الإثباتي كإثبات الزوجية للثلاثة ومثال المستحيل النفي كنفي الزوجية عن الأربعة. ولما فرغ من ذكر المستحيل شرع في ذكر الجائز فقال (والجائز) اسم فاعل من جل وجوده إذا أمكن وهو بهمزة محققة مبدلة من واو إذ أصل ماضية جوز لآنه من الجواز وتقرر في التصريف إبدال الهمزة من الواو ومن الياء في اسم الفاعل مما أعل عينا (ما) بمنزلة الجنس واقعة على معلوم أو مفهوم ولا ينبغي أن تكون على لأن الشيء في اصطلاح المتكلمين هو الموجود فيقتضي أن العدوم لا يتصف بالإمكان والجائز قد يكون معدوما ويتصف بالإمكان الذي هو الجواز نعم"], [21, "بالضرورة عجزها عن إيجاد الأجرام وإعدامها ويلزم أيضا عجز المثلين في الألوهية من جهة التمانع بين إرادتهما سواء اتفقا على ممكن واحد أو اختلفا أما إن اختلفا فظاهر وأما إن اتفقا فلأن لكل ممكن وجودا واحدا فيستحيل أن تنفذ فيه إرادتان وإلا لزم ما لا ينقسم أو تحصيل الحاصل فلا بد ّ إذا من عجز إحدى القدرتين وإحدى الإرادتين ويلزم منه عجز الأخرى لما انعقد بينهما من المماثلة هذا كله في المثل الحقيقي العام. وأما إذا فرض المثل خاصا في بعض الصفات كالقدرة والإرادة مثلا فإنه يلزم الحدوث أيضا لكل من المثلين لأن كل واحدة من الصفتين المتماثلتين تحتاج إلى مخصص يخصصها بالمحل الذي وجدت فيه لقبول كل واحدة منهما حينئذ المحلين فيلزم أن يكون كل واحدة منهما جائزة الوجود حادثة عارضة لكل من الموصوفين وكل واحد منهما لا يمكن أن يعرى عن هذه الصفة الحادثة أو ضدها ولا يكون ذلك الضد إلا حادثا فيلزم أن يكون كل واحد من الموصوفين حادثا وذلك ينافي ما ثبت للاله من وجوب الوجود، ويلزم حينئذ العجز لأجل الحدوث والتمانع إن فرض المثل في القدرة والإرادة فقولنا ولا مؤثر معه في فعل من الأفعال هو من باب عطف الخاص على العام لأن وجود المؤثر معه تعالى يرجع إلى وجود المثل له تعالى في بعض صفاته وهي القدرة والإرادة فلو وجدت صفة في حادث يتأتى بها الإيجاد والإعدام لكانت مماثلة لقدرة الباري جل وعلا فتكون حادثة لاحتياجها إلى مخصص يخصصها بالذات العلية ويخصصها بعموم التعلق عن نظيرتها وحدوث الصفة يسلتزم حدوث موصوفها وذلك يستلزم حدوث الذات العلية تعالى عن ذلك. فان قيل تاتي الإيجاد والإعدام على وفق إدارة القادر وعلمه هو حقيقة القدرة الأزلية ولا مثل لها في ذلك لأن الإيجاد والإعدام اللذين يدعيان لبعض القدرة الحادثة ليسا من حقيقة تلك القدرة الحادثة بل هو عرضي لها يجعل الله تعالى لها ذلك فهي تؤثر على وفق إرداة موصوفها وعلمه.\rفالجواب أن تأتي التأثير إذا كان عرضيا لهذه القدرة الحادثة فانه يلزم أن لا يرد على هذه القدرة على حياله لأنه حال والأحوال لا يمكن أن تفعل على حيالها فلا بد من خلق صفة معنى وجودية في هذه القدرة الحادثة تكون علة لما عرض لها من تأتي الإيجاد بها والإعدام ويلزم عليه قيام العرض بالعرض والتسلسل لنقل الكلام إلى ذلك الثاني هل إيجابه للتأثير ذاتي فلا يتوقف بعد وجوده على إرادة أو هو عرضى لها فيحتاج إلى عرض آخر بوجب له الإيجاب للتأثير وهلم جرا، وبالجملة فالذي يجب\r[المواهب اللدنية]\rالشيء لغة يطلق على الموجود قال الله تعالى (({إِنَّمَا أَمْرُهُ إِذَا أَرَادَ شَيْئًا أَنْ يَقُولَ لَهُ كُنْ فَيَكُون} [) (صح) بكسر الصاد كشح يشح وعبر بالصحة في الجائز دون التصور لأن التصور يطلق على الأقسام الثلاثة والصحة خاصة بالجائز والواجب فنقول في ذلك كل ما صح يتصور كالواجب والجائز وليس كل ما يتصور يصح كالمستحيل فانه يتصور في الذهن ولا يصح في الخارج (في العقل) المتبادر منه تعلقه بيصح وقيد الصحة بالعقل ليدخل نحو تعذيب المطيع ولو كان ملكا وما هو أفضل منه قال الله تعالى ((يغفر لمن يشاء ويعذب من يشاء)) لأن العقل هو الذي يحكم بصحته ضرورة أنه لا يلزم من فرض وجوده محال والشرع العزيز لا يصحح ذلك لأنه إنما أخبر بتنعيمه على سبيل التفضيل (وجوده) أي وجود أفراده كالشريك والولد والنقائص (وعدمه) أي عدم إراده كذواتنا وصفاتنا خرج به أيضا الواجب لأنه لا يصح عدم إفراده كذات الله تعالى وصفاته بل هي واجبة الوجود لنفسها ولموضوعها ولما كان الجائز العقلي ينقسم إلى ستة أقسام ذاتي وعرضي وإثباتي ونفي وضروري ونظري أشار المصنف رحمه الله تعالى إلى الضروري والنظري ممثلا لكل واحد منهما بقوله (إما ضرورة) أي بديهة وهو ما يدركه العقل بلا تأمل (كالحركة لنا) والسكون بالخصوص فانا بالمشاهدة نعلم صحة وجودها وعدمها للجرم (وإما نظرا) وهو ما يدركه العقل بعد التأمل (كتعذيب المطيع) الذي لم يعص الله طرفة عين قط (وإثابة العاصي) الذي لم يطع الله طرفة عين قط فان العقل يحكم بصحة هذا المعنى بعد التأمل والنظر وأما الشرع العزيز فلا يصحح ذلك لأنه إنما أخبر بتنعيمه على سبيل التفضيل كما تقدم ومثال الجائز الذاتي كوجودنا ومثال الجائز العرضي كدخول الصحابة الجنة ومثال الجائز الإثباتي كإثبات دخول المؤمنين الجنة ومثال الجائز النفي كنفي العذاب عن المطيع {تنبيه} وينقسم الجائز أيضا إلى خمسة أقسام "]], "pg": [20, 21]}, "516.10": {"x": [[21, "زائدة على الأقسام السابقة وذكرها المصنف رحمه الله تعالى في الشرح الأول جائز مقطوع بوجود كتنعيم أهل الجنة في الجنة والثاني جائز مقطوع بعدمه كدخول الكافر الجنة والثالث جائز محتمل الأمرين كقبول الطاعة منا والرابع جائز محتمل مشكوك فيه كقبول الطاعة وفوزنا بحسن الخاتمة والخامس جائز جوّزه الشرع كسائر المباحات. فان قلت لم تعرض المصنف رحمه الله تعالى لشرع الواجب والمستحيل والجائز دون الوجوب والاستحالة والجواز. فالجواب لاستلزم تصورها تصور مصادرها"], [22, "اعتقاده وقام البرهان القطعي عليه أن لا مثل له تبارك وتعالى لا في الذات ولا في الصفات ولا في الأفعال\rالقدرة والإرادة المتعلقتان بكل ممكن\r("]], "pg": [21, 22]}, "516.11": {"x": [[22, "ويجب له تعالى القدرة والإرادة المتعلقتان بكل ممكن إذ العجز عن بعضها مستلزم للعجز عن جميعها وذلك يستلزم استحالة وجودها لتوقف كل حادث في وجوده وإعدامه على اقتدار فاعله وفي تخصيصه على إرادته وفي كونه مرادا على علمه) القدرة الأزلية صفة يتأتي بها إيجاد كل ممكن وإعدامه على وفق الإرادة والإرادة صفة يتأنى بها تخصيص كل ممكن بالجائز المخصوص بدلا عن مقابله ولاشك أن كل حادث يدل على أربعة مطالب لهاتين الصفتين الأول وجودهما الثاني وجوب الوجود لهما الثالث عموم تعلقهما بجميع الممكنات الرابع وحدتهما.\rأما وجه دلالة كل حادث على وجودهما فلأنه لو انتفت القدرة لوجد ضدها وهو العجز وذلك يستلزم عدم التمكن من الفعل ولو انتفت الإرادة للجائز المخصوص لزم ترجيحه على مقابله له بلا مرجح وذلك محال وأما وجه دلالة كل حادث على وجوب هاتين الصفتين ويدخل في ذلك وجوب القدم والبقاء لهما فلأنهما لو كانتا جائزتين لزم حدوثهما وافتقارهما إلى فاعل ولا فاعل إلا الله لما تقدم في الوحدانية فيلزم أن يتصف قبل فعلهما بقدرة أخرى عليهما وإرادة لهما لما عرفت في المطلب الأول من وجوب توقف كل حاذث على وجودهما قبله ثم تنقل الكلام إلى القدرة والإرادة الأخريين فيلزمهما من الحدوث ما لزم الأوليين فيتوقفان أيضا في إحداثهما على قدرة وإرادة أخريين ثم هلم جرا فان وقف العدد لزم الدور وإن لم يقف لزم التسلسل وكلاهما مستحيل ولزوم المستحيل مستحيل فيكون وجود القدرة والإرادة الحادثتين مستحيلا كيف وكل حادث توقف وجوده وإعدامه عليهما فيلزم أن لا يتأتى بهما الإحداث والتخصيص حتى تكونا واجبتي الوجود وأما وجه دلالة كل حادث على عموم التعلق لهما بجميع الممكنات فلأنهما لو اختصتا ببعض الممكنات ووقع العجز عن بعضها لزم في ذلك أمور مستحيلة الأول تعميم العجز في جميع الممكنات لاستوائها في حقيقة الإمكان المحوج إلى الفاعل فاذا تعذر من الفاعل فعل بعضها لزم فعل جميعها ويلزم أيضا حدوثهما لافتقار عددهما المخصوص إلى مخصص.\rالثاني لزوم حدوثهما لاحتياجها حينئذ إلى الفاعل الذي خلفهما لبعض الممكنات وخلق ضدهما لبعضها لجواز أن تعلقا بجميع الممكنات أو بالبعض الذي تعلق به لبعض العجز فاختصاصهما حينئذ بما اختصتا به يوجب افتقارهما إلى الفاعل المخصص.\rالثالث لزوم التمانع بينهما وبين القدرة والإرادة اللتين تعلقتا بهما وإلى بعض هذه اللوازم وهو الأول منها أشرنا\r[المواهب اللدنية]\rلأن المشتق أخص من مصدره الذي اشتق منه ومعرفة الأخص تستلزم معرفة الأعم بخلاف العكس. فان قلت ما الحكمة في تقديم الواجب ثم المستحيل وأخر الجائز. فالجواب قدم الواجب لشرفه وثنى بالمستحيل لأنه ضده يفهم منه وأخر الجائز لأنه مركب منهما.\rواعلم أن تقسيم هذه الأقسام الثلاثة إلى ضروري ونظري هو بحسب إجراء الله تعالى العادة فان العلوم بعضها ضروري وبعضها نظري ويجوز بالإجماع أن تصير كلها ضرورية وإنما الخلاف في عكسه فمن جعل العقل هو العلوم الضرورية أو ملزوما لها منع أن تكون كلها نظرية ومن قال إن العقل ليس نفس العلوم الضرورية ولا ملزوما لها جوزّ. واعلم أن هذه الأقسام الثلاثة هي نفس العقل عند إمام الحرمين وجماعة فمن لم يعرفها فليس بعاقل بدليل أن الإنسان إذا أوصى بثلث ماله للعقلاء فانه يصرف لمن عرف هذه الثلاثة. واعلم أن الحركة والسكون يصح التمثيل بهما للأقسام الثلاثة فالواجب ثبوت أحدهما لا بعينه والمستحيل نفيهما واجتماعهما في محل واحد والجائز ثبوت أحدهما بالخصوص {خاتمة} نسأل الله حسنها.\rمن المقرر عندهم أن الوجوب والإمكان والامتناع اعتبارات عقلية وليست من قبيل الجوهر ولا من قبيل العرض. فان قلت إذا كانت هذه الأمور اعتبارات عقلية وعدومة في الخارج فما معنى الله واجب وقديم وزيد ممكن حادث في الخارج واجتماع النقيضين ممتنع في الخارج فالجواب كما قاله بعض المحققين معناه أن العقل إذا نسبه تعالى إلى الوجود الخارجي حصل معقول هو الوجوب والقدم وإذا نسب زيدا إلى الوجوب الخارجي حصل له معقول هو الإمكان والحدوث وإذا نسب اجتماع 7 إلى الوجود الخارجي حصل له معقول هو الامتناع {فائدة} مجموع الأقسام التي تفرغت من الحكم اللغوي الذي هو إثبات أمر أو نفيه خمسة وثمانون قسما فتأملها وعدّها تجدها كما قلنا والحمد لله على ذلك وإنما أطلت بهذا الكلام رغبة مني في إطلاع الطالب على بعض أبحاث تلك الحدود إذ هذه الحقائق لا غنى للطالب عنها والأعمال بالنيات ((وأما بنعمة ربك فحدث)) اللهم يامن لا ينتفع بطاعة الطائعين ولا يتضرر بمعاصي العاصين وهو غني عنهم أجمعين وهم مفتقرون لله في كل حين اغفر لنا وارحمنا وأولادنا ووالدينا ولإخواننا ولمشايخنا ولجميع المؤمنين. ولما فرغ المصنف رحمه الله تعالى من مقدمة الأحكام وما يتعلق بها شرع في مقدمة المذاهب وعطفها عليها لاشتراكهما في العدد وهي ثلاثة كما أن الأحكام"], [23, "بقولنا إذ العجز عن بعضها مستلزم للعجز عن جميعها فالضمير المؤنث في بعضها وجميعها يعود على الممكنات المفهومة من قوله لكل ممكن واما وجه دلالة كل حادث على وحدتهما فلأنه لو وقع التعدد فيهما لزم العجز للزوم التمانع بين القدرتين والإرادتين كما لزم في تعدد الإله. فان قيل نفرض تعدد كل واحدة منهما بعدد الممكنات بحيث يكون لكل ممكن قدرة وإرادة خاصتان به فلا تمانع حينئذ. فالجواب أنه يلزم عليه دخول ما لا نهاية له في الوجود إذ عدد الممكنات لا نهاية له وأيضا يلزم عليه الافتقار إلى المخصص لأن قدرة وإرادة حينئذ يجوز أن تتعلقا بغير ما تعلقنا به فاختصاصها بما اختصتا به يوجب الافتقار إلى المخصص وأيضا يلزم من عجزها عن التأثير في غير ما تعلقنا به العجز عن الجميع ولهذا يصح أن تأخذ مطلبين وهما الوحدة وعموم التعلق من قولنا في أصل العقيدة إذ العجز عن بعضها مستلزم للعجز عن جميعها وتأخذ المطلبين الآخربن وهما الوجود والوجوب من قولنا لتوقف كل حادث في وجوده إلى آخره وبالله تعالى التوفيق.\rالعلم المتعلق بجميع الواجبات والجائزات\r("]], "pg": [22, 23]}, "516.12": {"x": [[23, "ويجب له تعالى العلم المتعلق بكل واجب وجائز ومستحيل لأن الاختصاص بالبعض يستلزم الحدوث لافتقار الصفة حينئذ إلى الفاعل وحدوثها يستلزم حدوث موصوفها لاستحالة تعريه عنها وعن أضدادها) لا شك أن كل حادث يدل أيضا على أربعة مطالب لهذه الصفة كما سبق في القدرة وإنما لم يقم في أصل العقيدة البرهان على وجود هذه الصفة لأنه قد سبق له في قوله وفي كونه مرادا على علمه أي فكما توقف وجود كل حادث على الإرادة لزم أن يتوقف على العلم إذ القصد إلى جائز معين مع عدم العلم به مستحيل ويؤخذ برهان مطلب الوجوب لهذه الصفة مما ذكرنا في برهان عموم تعلقها وإذا كان اختصاص تعلقها يوجب لها الحدوث لكونه يستلزم جوازها فكيف إذا كانت من أول مرة جائزة الوجود وكذا أيضا يؤخذ ففي التعدد من هذا البرهان لأن العدد يوجب الحدوث لافتقار العدد الخاص إلى محدث وقولنا وحدوثها يستلزم حدوث موصوفها يعني ويلزم الدور أو التسلسل وأيضا خفاء البعض يستلزم خفاءالجميع إذ لا فرق وقد سبق ذلك كله في القدرة والإرادة وقولنا وعن أضدادها يعني ولا تكون تلك الأضداد إلا حادثة لأنها ضد العلم الحادث فان جاء العلم بعدها فدليل حدوثها طرو ٌ عدمها وما ثبت قدمه استحال عدمه وإن جاءت بعد العلم فحدثها ظاهر إذ لا معنى للحادث إلا وجوده بعد عدم وبالله تعالى التوفيق. (ويجب له تعالى السمع والبصر المتعلقان بجميع الموجودات والكلام المنزه عن الحرف والصوت والتقديم والتأخير والكل والبعض والجديد\r[المواهب اللدنية]\rثلاثة وقد تقدم وجه المناسبة في عطف أحد هذه المقدمات بعضها على بعض في أول الكتاب من أوّلهما إلى آخرها فانظرها نمت إن شئت، قال رحمه الله تعالى (والمذاهب في الأفعال ثلاثة) المذهب في اللغة: الطريق، وفي الاصطلاح: هو عبارة عن الشيء الموصل إلى المعنى ويعني بالأفعال أفعال الحيوانات عاقلة أو غير عاقلة ويدخل فيها مشى الشجر وتسبيح الحصى وحنين الجزع وإظلال الغمام وكلام ذراع الشاة له صلى الله عليه وسلم، ووجه الحصر فيها على المشهور أن الأفعال الاختيارية إما أن يقول بنفي القدرة الحادثة فيها أو لا فالأول مذهب الجبرية.\rوالثاني إما أن يقول بتأثير القدرة الحادثة أو لا فالأول مذهب القدرية والثاني مذهب أهل السنة رضي الله عنهم الأول من الثلاثة (مذهب الحرية) بسكون الباء طائفة من أهل الضلال وسموا بذلك لقولهم بالجبر المحض ولا يكفرون (و) الثاني (مذهب القدرية) بتحريك الدال طائفة من أهل الزيغ والضلال تنكر أن الله تعالى قدّر الأشياء في القدم ولذلك سموا بالقدرية لنفيهم القدر وقد قيل بكفرهم والأصح عدم كفرهم وهو قول الأكثر بشهادة قوله صلى الله عليه وسلم ((فاذا قالوها)) يعني الشهادة ((عصموا مني دماءهم وأموالهم إلا بحقها وحسابهم على الله تعالى)) فالعصمة مقطوع بها مع الشهادة (و) الثالث (مذهب أهل السنة) رضي الله عنهم وأرضاهم وهي الفرقة الناجية السالمة من جميع البدع المشتغلون بالرد على جميع الفرق والزياغة من أهل الكفر والضلال والطغيان بالحجيج الساطعة والبراهين القاطعة التي هي أمضى من السيوف الحسان والمثبتون لما وردت به السنة المحمدية وهي طريقته صلى الله عليه وسلم قولا وفعلا وتقريرا ومضى عليه جماعة الصحابة والتابعين رضي الله عنهم في باب العقائد لا سيما إمام أهل السنة والجماعة الشيخ أبو الحسن الأشعري وأتباعه ومن كان بمثابتهم والإمام أبو منصور الماتريدي وأتباعه فسموا أهل السنة والجماعة وكانوا أحق بها وأهلها شكر الله سعيهم. فان قلت لم قدم مذهب الجبرية والقدرية وهما فاسدان على مذهب أهل السنة وهو صحيح. فالجواب قدم مذهب الجبرية وهو بسيط وعلق مذهب القدرية لاشتراكهما في الفساد وأخر ما كان برهانا ثم شرع في بيانها بقوله (فمذهب الجبرية وجود الأفعال) يعني الاختيارية والاضطرارية من غير فرق منهم بينها (بالقدرة القديمة الأزلية فقط من غير مقارنة) يعني مصاحبة ... (لقدرة حادثة) زعما منهم أن العبد منبع لظهور الأفعال كخيط معلق في الهواء"], [24, "والسكوت المتعلق بما يتعلق به العلم ودليل هذه الثلاثة الشرع) اعلم أن عقائد الإيمان تنقسم إلى ثلاثة أقسام: الأول ما لا يصح أن يعلم إلا بالدليل العقلي وهو كل ما تتوقف عليه دلالة المعجزة كوجوده تعالى وقدرته وإرادته وعلمه وحياته فانه لو استدل على هذا القسم بالدليل الشرعي وهو متوقف على صدق الرسل المتوقف على دلالة المعجزة لزم الدور. القسم الثاني ما يصح أن يستدل عليه بالدليل الشرعي وهو كل ما لا تتوقف عليه دلالة المعجزة كالسمع والبصر والكلام والبعث وأحوال الآخرة جملة وتفصيلا. الثالث ما اختلف فيه لتردد فيه هل هو من القسم الأول أو من القسم الثاني كالوحدانية فانه اختلف فيها هل يكفي فيها الدليل السمعي بناء على عدم توقف دلالة المعجزة عليها في علم الناظر وإن توقف وجود المعجزة عليها في نفس الأمر لاستحالة وجود الفعل مع وجود الشريك أو لابد فيها من الدليل العقلي نظرا إلى توقف دلالة المعجزة على صحة وجود المعجزة المتوقف على الوحدانية لأن المعجزة فعل والفعل يستحيل وجوده على تقدير الاثنينية في الألوهية والمتوقف على المتوقف على شيء متوقف على ذلك الشيء وقولنا في السمع والبصر المتعلقان بجميع الموجودات "]], "pg": [23, 24]}, "516.13": {"x": [[24, "أي ينكشف لسمعه تعالى وبصره جميع الموجودات قديمة كانت أو حادثة وليس كسمع المخلوق الذي يختص عادة تعلقه بالأصوات ولا كبصر المخلوق إنما يتعلق عادة بالأجسام والألوان والأكوان وبرهان عموم التعلق لسمعه تعالى وبصره أن مصحح تعلقهما إنما هو الوجود فلو تعلقا ببعض الموجودات دون بعض لافتقرا إلى مخصص فيكونان حادثين وقيام الحوادث بذاته تعالى مستحيل.\rوالحاصل أن ثبوت هاتين الصفتين أخذ من الشرع وتعلقهما بجميع الموجودات أخذ من الدليل العقلي وكذا ثبوت الكلام له تعالى أخذ من الشرع وكونه منزها عن الحرف والصوت والتقديم والتأخير إلى ما ذكر أخذ من الدليل العقلي فانه لو اتصف كلامه تعالى بشيء مما ذكر لزم أن يكون حادثا وحدوث الصفة يوجب حدوث الموصوف. فان قلت إثباتهم الكلام بالدليل الشرعي يلزم منه الدور لأن الدليل الشرعي موقوف على دلالة المعجزة وهي متوقفة على الكلام بناء على الصحيح من أن دلالتها وضعية أي تتنزل منزلة تصديق الله تعالى لمن ظهرت على يديه بالقول. فالجواب أن تنزلها منزلة التصديق بالقول إنما معناه أنها تدل على ما يدل عليه القول من صدق الآتي بها لا معناه أن فاعلها تكلم بتصديق من ظهرت على يديه بالقول وذلك كما تقول الإشارة تدل على ما يدل عليه القول وهل المشير متكلم أو أبكم محتمل ليس في الإشارة\r[المواهب اللدنية]\rيميله الريح يمينا وشمالا فالحيوانات عندهم في أفعالها بمنزلة الجمادات لا تتعلق بها قدرها لا إيجاداواختراعا ولا تناولا واكتسابا فلا شك أنهم سخفاء العقول من حيث إنهم خفي عليهم الفرق بين الحركات الاختيارية والاضطرارية وهم مبتدعة أيضا من حيث إنهم نفوا محل التكليف والثواب والعقاب شرعا إذ التكاليف وقع في الشرع بحسب اختياره تعالى بما هو مقدور للمكلف وفي وسعه عادة قال اله تعالى ((لا يكلف الله نفسا إلا وسعها)) أي ما تسعه طاقتها بحسب الظاهر والعادة وأما بحسب ما في نفس الأمر أي الواقع فليس في وسعها فعل من الأفعال (ومذهب القدرية) مجوس هذه الأمة وخصماء الله تعالى في القدر بشهادة حديث ... ((ينادي يوم القيامة ليقم خصماء الله تعالى فيقوم القدرية ولاعتقادهم أن العبد يقدر على ما يوجبه الله مع كراهته له فلزمهم أن يقع في ملكه تعالى ما لا يريد (وجود) أي اختراع ... (الأفعال الاختيارية) وهي التي لا تحصل في حال الاضطرار إلى الأفعال (بالقدرة الحادثة) وهي التي خلق الله تعالى للحيوان على سبيل الاستقلال وهو معنى قوله (فقط) وليس للمولى تبارك وتعالى فيها اختراع عندهم وإنما الذي يوجد سبحانه وتعالى فيها ما لا يتيسر منها عليهم كالألوان والطعوم والروائح وحركات الارتعاش ونحو ذلك (مباشرة) وهو ما يوجد من الأفعال الاختيارية في محل قوته كالرمي بالحجر والضرب بالسيف والسهم والرمح ونحو ذلك فهذه أفعال متولدة عندهم بواسطة اختياره ولا شك أن هؤلاء مبتدعة مناقضون لما دل عليه العقل من وجوب انفراده تعالى باختراع جميع الكائنات ابتداء بلا واسطة على وفق ما شاء جل وعلا ومناقضون أيضا ما دل عليه الكتاب والسنة ووقع عليه إجماعا سلف الأمة من أن لا خالق إلا الله تعالى وأن ما شاء الله سبحانه كان وما لم يشأ يكن (ومذهب أهل السنة) رضي الله عنهم وهو الحق (وجود) يعني اختراع وإيجاد وإنشاء (الأفعال) يعني أفعال الحيوانات (كلها) اختيارها واضطرارها (بالقدرة) القديمة (الأزلية) السرمدية (فقط) ليس إلا دون القدرة الحادثة إذ ليس لها تأثير بوجه من الوجوه بل هو عرض مخلوق لمولانا جل وعلا ينعدم في كل وقت وحين ويتجدد أمثاله مدة بقاء الجرم على التعاقب فلا مؤثر بالقدرة إلا الله تبارك وتعالى لا موجد للأفعال إلا الله تعالى فقط (مع مقارنة) يعني مصاحبة (الأفعال الاختيارية)"], [25, "ما يدل على شيء من ذلك وهي في نفسها تدل بالوضع دلالة الكلام بلا إفراق سواء كان المشير متكلما أو أبكم وهذا غاية التحقيق في وجواب السؤال وإن كان قد استهوله وعظمه كثير من الأئمة وهذا الجواب القصير المحقق لم يترك عليه غبارا والله تعالى أعلم وبه التوفيق (ويجب له تعالى الحياة لاستحالة وجود الصفات السابقة بدونها) مراده بالصفات السابقة القدرة وما ذكر بعدها إلى الكلام فان كل واحدة من هذه الصفات يستحيل وجودها لغير الحي ولهذا أخر ذكر الحياة إلى هذا الموضع وهو من باب تأخير المدلول عن الدليل وإلا فهي من جهة أنها شرط في تلك الصفات مقدمة بالذات عليها لتوقف وجود الشروط على وجود شرطه إلا أن التوقف هنا توقف معية لا توقف تقدم إذ صفات المولى جل وعلا كلها أزلية يستحيل تقدم بعضها على بعض في الوجود وبالله تعالى التوفيق.\rالمستحيل في حقه تعالى، والجائز أيضا\r("]], "pg": [24, 25]}, "516.14": {"x": [[25, "وأما المستحيل في حقه تعالى ما ينافي هذه الصفات الواجبات) لا شك أنه لما وجب جل وعلا عقلا الوجود وما بعده من الصفات استحال عليه عقلا ونقلا كل ما ينافيها فينافي الوجود العدم وينافي القدم الحدوث وينافي البقاء الفناء وينافي المخالفة للحوادث مماثلتها وينافي القيام بالنفس الافتقار إلى المحل والمخصص وينافي الوحدانية وجود التعدد في الذات والصفات والأفعال وينافي القدرة العامة العجز العام والخاص وينافي الإرادة العامة وجود الأفعال أو بعضها مع الكراهة وينافي العلم العام الجهل وما في معناه بشيء من المعلومات وينافي السمع العام لجميع الموجودات الصمم وهو غيبة ما شيء ما من الموجودات عن سمعه تعالى وينافي البصير العام العمى وهو خفاء شيء من الموجودات عن بصره تعالى وينافي الكلام اليكم وهو خروج شيء من المعلومات عن دلالة كلامه جل وعلا وكون كلامه تبارك وتعالى حروفا أو أصواتا أو متصفا بشيء من لوازمهما وينافي الحياة الموت وإنما سكتنا في أصل العقيدة عن إثبات إدراكات زائدة على الصفات السابقة وهي إدراك المعلومات وإدراك المذوقات وإدراك المشمومات وإدراك الملموسات بادراكات زائدة على السمع والبصر والعلم فتكون عند من أثبتها عامة لكل موجود من غير اتصال ولا تأثير بما يلازمها عادة لأجل الخلاف في إثبات هذه الادراكات والذي اختاره بعض المحققين الوقف فيها وسكتا أيضا عن الصفات المعنوية وهي كونه تعالى قادرا ومريدا وعالما وحيا وسميعا وبصيرا الخ إما لأنها لازمة لصفات المعان عند من أثبت الأحوال وإما لأنها عبارة عن وجودها وبالله تعالى التوفيق (وأما الجائز في حقه تعالى فعل كل ممكن أو تركه صلاحه كان أو ضده قبل من وجوب عموم قدرته\r[المواهب اللدنية]\rدون الاضطرارية بالموافق والمخالف على أنها مخلوقة الله تعالى لا كسب للحيوان فيه ... (القدرة حادثة) يعني مسبوقة بالعدم (لا تأثير) يعني اختراع (لها) وهيهات هيهات أن لها ذلك ونفي حليف العجز العام والافتقار الذاتي على سبيل الدوام (لا مباشرة) وهو يوجد في محل قوته كحركاته وقيامه وتعوده ومشيه وجريه وغير ذلك (و) كما أن الحيوان لا اختراع له في أفعاله مباشرة كذا (لا) اختراع له (تولدا) وهو ما يوجد خارجا عن محل قوته كالضرب بالسيف والرمح والحجر ونحو ذلك فهذه الأفعال حادثة غير مكتسبة للعبد لأنها خارجة عن محل قدرته إلا أنها لما كانت مخلوقة عند كسب عادة أخرى فيها التكليف والثواب والعقاب، وبالجملة فمذهب أهل السنة أن الموجد لأفعال العباد هو الله تبارك وتعالى وحده غير أن الاختارية منها تقارنها قدرة حادثة من غير تأثير لها فيها أصلا وهذه الأفعال هي التي في وسع المكلف على حسب ما دل عليه الشرع قال جل من قائل ((لا يكلف الله نفسا إلا وسعها)) أي إلا ما تسعه طاقتها بحسب الظاهر والعادة وأما بحسب ما في نفس الأمر أي الواقع فليس في وسعها فعل من الأفعال لا يقال الجبر لازم لأهل السنة حيث لم يجعلوا للعيد تأثيرا في أفعاله لأنا نقول الجبر المحظور هو الحسنى كما ذهب إليه الجبرية أما العقلي وهو سلب الخالقية عن العبد فهو متوجه على جميع الفرق ولا يضر بل هو الإيمان فاعرفه وبالجملة فمذهب أهل السنة مجانب للمذهبين الفاسدين لأنهم جمعوا بين الحقيقة والشريعة وسلموا بتوفيق الله من بدعة الفريقين لأنهم جانبوا الجبرية بتقسيمهم الأفعال إلى قسمين اختيارية واضطرارية وأن الأولى مقدروة للعباد بمعنى أن لهم قدرة حادثة تلك الأفعال الاختيارية ويتعلق بها من غير تأثير وجانبوا أيضا القدرية لأنهم لم يجعلوا لتلك القدرة الحادثة المخلوقة لله في الحيوانات تأثيرا ألبتة في أثر ما بدليل برهان الوحدانية ووجوب عموم القدرة والارادة لجميع الممكنات ودل عليه الكتاب والسنة واجماع الأمة ولما عرفنا بالضرورة عدم استواء الأفعال بالنسبة إلينا احتيج من أجل هذا إلى بيان معنى الكسب الذي هو محل التكليف الشرعي وهو الذي جعل أمارة على الثواب والعقاب والمدح والذم الشرعيين فقال (واما الكسب) عبر بالكسب دون التعلق تبركا بالقرآن العظيم في قوله تعالى"], [26, "تعالى وإرادته لجميع الممكنات ويدخل في ذلك جواز خلق الله تعالى الرؤية لذاته العلية والسمع لكلامه القديم والثواب في دار النعيم والبعث لرسله الأكرمين صلوات الله عليهم أجمعين) لا شك أن الجواز لا يتطرق للذات العلية ولا لشيء من صفاتها المرتفعة لوجوب الوجود لجميع ذلك وإنما مرجع الجواز التعلق التنجيزي لقدرته تعالى وإرادته وهذا التعلق ليس بقديم ومرجعه إلى صدور الكائنات عن قدرته تعالى وإرادته ولما عرفت فيما سبق من عموم تعلق قدرته تعالى وإرادته لجميع الممكنات وعرفت وجوب وحدانيته تعالى عرفت أن كل ممكن فهو جائز أن يكون بقدرة الله تعالى وإرادته وليس فيه ما هو واجب عقلا كالصلاح والأصلح كما قاله بعض من ضل لأنه يلزم عليه قلب حقيقة الصلاح والأصلح الجائزة بأن ترجع واجبة وذلك يمنع وقوع ضدها وهو الفساد كيف وهو موجود بالمشاهدة ومن الممكنات الجائزة عند أهل الحق رؤية المخلوق لمولانا جل وعلا على ما يليق به تبارك وتعالى من غير جهة ولا جرمية ولا تحيز لأنه تعالى موجود وكل موجود يصح أن يرى واستدعاء الرؤية المقابلة للمرئي والجهة له والتوسط بين القرب جدا والبعد جدا إنما هو عادي يقبل التخلف وكما صح أن يعلم مولانا جل وعلا على ما يليق بجلاله وعظمته من غير إحاطة فكذلك يصح أن يرى تبارك وتعالى بالبصر على ما يليق به جل وعلا وليست الرؤية بانبعاث شعاع يتصل بالمرئي حتى تستحيل رؤيته جل وعلا لاستحالة اتصال الشعاع به تبارك وتعالى إذ لو كانت الرؤية باتصال شعاع بالمرئي لزم أن لا يرى الرائي إلا مقدار حدقته كيف وهو يتكشف للرائي في نظرة واحدة أضعاف ذاته أضعافا لا حصر لها بحيث يقطع أنه لا يمكن أن ينفصل عنه شعاع يتصل بأدنى شيء منها وكذا من الجائزات إثابة الله تعالى المطيع إذ لا حق لأحد عليه إذ لا نفع له تعالى بطاعة أحد وأيضا فالطاعة خلق له تبارك وتعالى وليس للعبد فيها إلا الا اكتساب والاتصاف ولا أئر له فيها أصلا وكذا من الجائزات بعث الله تعالى الرسل عليهم الصلاة والسلام لأن ما قدر الله سبحانه وتعالى معهم من المصالح الدينية والدنيوية فيمحض فضله ولا أثر للرسل عليهم الصلاة والسلام في شيء من تلك المصالح ولاحق لأحد على مولانا جلا وعلا في هداية ولا في مصلحة دنيوية ولا أخروية وأوجبت المعتزلة عقلا على الله تعالى بعث الرسل على أصلهم الفاسد في وجوب مراعة الصلاح والأصلح على الله تعالى ولا يخفى فساده واما البراهمية فجعلوا بعث الرسل عليهم الصلاة والسلام مستحيلا ورأوا أن العقل يصل وحده بتحسينه وتقبيحه إل أحكام الله تعالى ولا تخفى سخافة عقولهم\r[المواهب اللدنية]\r((لها ما كسبت وعليها ما اكتسبت)). فان قلت ما الفرق بين الكسب والاكتساب. فالجواب الكسب تحصيل على أي وجه كان والاكتساب المبالغة والاعتمال فيه ففي الآية تنبيه على لطف الله تعالى بخلقه فأثبت لهم ثواب الفعل على أي ّ وجه كان ولم يثبت عليهم عقاب الفعل إلا على وجه مبالغة واعتمال (فهو عبارة) أي تعبير (عن تعلق القدرة الحادثة) احترز به من تعلق القدرة القديمة فلا يقال فيه كسب بل هو اختراع واحترز (بالمقدور في محلها) أي في محل القدرة الذي خرج عن محل القدرة كالرمي بالحجارة والضرب بالسيف والرمح والقتل والجرح ونحو ذلك ولما كانت هذه الأفعال خارجة عن محل قدرته غير مكتسبة للعبد وكانت مخلوقة عند كسبه عادة جرى فيها التكليف والثواب والعقاب واحترز بقوله (من غير تأثير) مما تعتقده القدرية مجوس هذه الأمة من أن ّ تعلق القدرة الحادثة بالأفعال إنما هو تعلق اختراع وتأثير لا تعلق اقتران ودلالة على الأفعال. فان قلت هل يقال المقدرور الواحد دخل تحت قدرتين قدرة الله تعالى وقدرة العبد. فالجواب نعم يقال لكن بجهتين مختلفتين تحت قدرة الله تعالى بجهة الخلق وتحت قدرة العبد بجهة الكسب فافترقا. ولما فرغ من الكلام على المقدمة وهي مقدمة المذاهب في الأفعال شرع الآن في مقدمة أنواع الشرك فقال (وأنواع) جمع نوع أي أصناف (الشرك ستة) "]], "pg": [25, 26]}, "516.15": {"x": [[26, "الشرك لغة هو عبارة عمن أدخل الغير مع الله تعالى، واصطلاحا هو عبارة عن كل ما يوجب الكفر والكفر لغة الستر والتغطية ومنه قوله تعالى ((كمثل غيث أعجب الكفار)) أي الزراع في نباته ويسمى البحر كافرا لستر ما فيه كما أن الزّراع يسقون البذر بالأرض واصطلاحا هو الجهل بالله تعالى والكفر أخص من الشرك بدليل انفراد الشرك عن الكفر في شرك الأعراض وهو العمل لغير الله تعالى والتقابل بين الكفر والإيمان تقابل الضدين وقيل تقابل العدم والملكة وعطف هذه الأنواع على المذاهب لاشتراكهم مع مذهب القدرية في الاشتراك وبدأ بالمجوس لأن القدرية مشبهون بهم في قوله صلى الله عليه وسلم ((القدرية مجوس هذه الأمة)) فهو من باب إثبات المشبه به باثر المشبه ووجه تشبيهم بالمجوس أن المجوس جعلوا للخير فاعلا ولشر فاعلا والقدرية أيضا منعوا نسبة الشر إلى الله تعالى وأضافوه إلى إبليس سببا"], [27, "في غاية لما عرفت أن مرجع أحكام الله تعالى الشرعية إلى نصب أفعال خلقها الله تعالى وجعلها بمحض اختياره أمارة على ماشاء من ثواب أو عقاب أو غيرهما ولا حسن في فعل ولا قبح يوجب له حكما من الأحكام ومن عرف انفراده تعالى بايجاد جميع الكائنات ونفوذ إرادته فيها مع التنزه عن الأعراض لا يخفى عليه فساد تلك المقالة الشنيعة وبالله تعالى التوفيق.\rالواجب في حق الرسل عليهم الصلاة والسلام: الصدق\r(وأما الرسل عليهم الصلاة والسلام فيجب لهم الصدق أي مطابقة كل ما أخبروا به وثواب وعقاب وغيرهما لما في نفس الأمر لأن الله تعالى قد صدقهم بما تنزل من المعجزة التي خصهم الله بها منزلة قوله تعالى \"صدق عبدي في كل مايبلغ عني\") هذا هو الجزء الثاني من جزأي الإيمان لأن الإيمان مركب من جزأين: أحدهما الإيمان بالله تعالى وهو حديث النفس التابع للمعرفة بما يجب له تعالى وما يستحيل وما يجوز.\rالثاني الإيمان بالرسل عليهم الصلاة والسلام وهو أيضا حديث النفس التابع للمعرفة بما يجب لهم وما يستحيل وما يجوز ولما كان الجزء الثاني موقوفا على الجزء الأول إنما يعرف ويحصل بعد معرفته قدّم علماؤنا الكلام على الجزء الأول قبل الكلام على الجزء الثاني، والرسل جمع رسول وهو إنسان بعثه الله سبحانه إلى عبيده بايمانه ليبلغهم عنه أحكامه التكليفية والوضعية وما يتبعهما من وعد ووعيد ونحوهما وهل شرطه أن يكون له شرع جديد أو كتاب مخصوص أو نسخ بشرع من قبله أو لا يشترط فيه شيء من ذلك أقوال ونحن مكلفون بمعرفة الرسل عليهم الصلاة والسلام ولا يتم إيماننا إلا بذلك ولا يحصل لنا إيمان إلا بمعرفة ما يجب لهم وما يستحيل وما يجوز فما يجب لهم عليهم الصلاة والسلام الصدق في كل ما يبلغون عن المولى تبارك وتعالى أي لا يكون خبرهم في ذلك إلا مطابقا لما في نفس الأمر ولا يقع منهم الكذب في شيء من ذلك لا عمدا ولا سهوا عند المحققين وبرهان ذلك أنه لو وقع الكذب في شيء مما بلغه الرسول عن الله تعالى لزم أن يسري ذلك الكذب إلى خبره تعالى لأنه تبارك وتعالى أشار إلى تصديق الرسل بفعل أوجده خارقا للعادة تحدّى به الرسول أي ادعاء قبل وقوعه وطلبه من المولى جل وعلا دليلا على صدقه في كل ما يبلغ عنه فأوجده تبارك وتعالى له على وفق دعواه وأعجز سبحانه وتعالى كل من يقصد تكذيبه ومعارضته أن يأتي بمثل ذلك الخارق فتنزل هذا الفعل من المولى تبارك وتعالى باعتبار الوضع والعادة وقرينة الحال منزلة التصريح بالكلام بصدق رسله عليهم الصلاة والسلام بحيث لا يجد الموفق فرقا بين تصديق الله تعالى لرسوله بهذا الفعل الموصوف بما سبق وبين تصديقهم بكلامه الصريح ألا ترى أن ملكا\r[المواهب اللدنية]\rوسعيا وإلى العبادة مباشرة وجعلا وهذه المسئلة التي بين المعتزلة والمجوس تعين اسم المرادين بالقدرية في الحديث دون ما عليه أهل الحق رضي الله تعالى عنهم وعطف شرك التبعيض لاشتراكهما في العدد وقدم الشرك التقريب على شرك الأسباب لأنه بسيط وذلك مركب وعطف عليه فرعه لئلا يفصل بين الأصل وفرعه وأخر شرك الأعراض لضعفه والله أعلم: الأول من الستة (شرك الاستقلال) "]], "pg": [26, 27]}, "516.16": {"x": [[27, "يعني الانفراد، استقل برأيه إذا انفرد به حيث أفردوا إلها وللشر إلها (وهو) أي شرك الاستقلال (إثبات إلهين) اثنين (مستقلين) يعني منفردين أحدهما لخلق الخير ويسمى عندهم هرمز والآخر لخلق الشر ويسمى عندهم يزدان واتفقوا على قدم هرمز واختلفوا في قدم يزدان فزعم بعضهم أنه قديم وزعم بعضهم أنه حادث من فكرة رؤية حصلت من هرمز والوصفان متباينان له يمكن اجتماعهما في موصوف واحد فوجب أن يكون موصوفهما اثنين ويلزم على مقتضى هذا النظر الفاسد إثبات إله ثالث ليفعل من الممكنات ما ليس بخير ولا شرك وإن نفوا هذا القسم وحصروها في الخير والشر فهم مباهتون وجاحدون لما قطع بوجوده وايضا يلزمهم في الشاهد أن الفاعل للخير لا يتأنى أن يصدر منه الشر والعكس والعيان يقطع ببطلانه ويلزم أيضا على قولهم حدوث إلهين وافتقارهما إلى إله ثالث يخصص كل واحد بما اختص به من الخير والشر وكذا الثالث يفتقر إلى رابع وهلم جرا فان انتهى العدد لزم الدور وإن لم ينته لزم التسلسل وذلك محال لا يتصور في العقل وجوده فاذا فرض وجوده إله آخر مع الله مستحيل لا يتصور بوجه من الوجوه وأيضا يلزم التمانع بين الإلهين المفروضين عند إرادة أحدهما اختراع الخير في محل وإرادة الآخر اختراع الشر فيه في زمن واحد فما تخيله هؤلاء الكفرة باطل بوجه من الوجوه (و) "]], "pg": [27, 27]}, "516.17": {"x": [[27, "والثاني من أنواع الشرك (شرك التبعيض) يعني التجزى (وهو) أي شرك التبعيض (تركيب) يعني تأليف (الإله) يعني ذات الإله تعالى الله عن قولهم (من آلهة) ثلاثة يعني أقانيم أي أصول ثلاثة وهو أقنوم الوجود وأقنوم العلم وأقنوم الحياة وحكموا عليها بأنها آلهة ثلاثة مع أنها صفات ثم قالوا بعد ذلك إن مجموع الثلاثة إله واحد فجمعوا بين نقيضين وحدة وكثرة فجعلوا الذات تتركب عندهم لا عندنا من مجرد أحوال"], [28, "من الملوك لو جمع في بعض الأوقات أهل مملكته وقام من المجلس بعض عبيده بمرأى منه ومسمع وقال للناس إن الملك قد بعثني إليكم بكذا وكذا وها هو عالم بمقالتي هذه إليكم سميع بصير قادر على إهلاكي إن كذبت وآية صدقي فيما ادعيته عليه أو أطلب منه أن يصدقني بأن يفعل كذا وكذا مما لم تجر عادته أن يفعله وأن يخصني بذلك ولا يفعله لأحد ممن يقصد معارضتي وتكذيبي ثم طلب من الملك ذلك الفعل ففعله له على وفق ما طلب منه وخصه به دون غيره ممكن يقصد معارضته والقدح في صدقه فيعلم على الضرورة أن الملك نازل في الدلالة على صدق ذلك الدعى منزلة صريح قول الملك إنه صدق فيما بلغ عني لا فرق بينهما أصلا وإذا ثبت ذلك لزم من كذب الرسول كذب الملك الذي قد صدقه لأن تصديق الكاذب كذب ولما كان الكذب على المولى تبارك وتعالى مستحيلا لأن خبره على وفق علمه جل وعلا والعلم لا يحتمل النقيض بوجه من الوجوه فالكلام التابع له كذلك لزم أن يكون الكذب في حق رسله عليهم الصلاة والسلام مستحيلا وذلك ظاهر وبالله تعالى التوفيق.\rالأمانة والتبليغ\r(ويجب لهم الأمانة أي حفظ ظواهرهم وبواطنهم من الوقوع في محرم أو مكروه لأن أتباعهم أمروا بالاقتداء بهم في جميع أقوالهم وأفعالهم وذلك يستلزم عصمتهم فيها من كل منهى عنه) هذا كمال ثان واجب للرسل عليهم الصلاة والسلام وهو كونهم أمناء لا خيانة لهم في شيء من الأشياء والأمين هو الذي يترك كل أمر على الوجه الذي أوصى مالكه أن يترك عليه ولا يجوز أن ينقله بسبب الشهوة من الموضع الذي ينبغي أن يكون فيه بوصية مالكه الذي تجب طاعته فالأمانة في الواجب والمندوب أن يدخلا في شريف صندوق الوجود كما أوصى بذلك فيهما مولانا جل وعلا ولا يخان بنقلهما إلى آفة العدم والأمانة في المحرم والمكروه أن يدخلا في صندوق العدم ولا ينقلا عنه إلى شريف الوجود كما أوصى أيضا بذلك فيهما تبارك وتعالى ولا شك أن الذوات والأفعال كلها ملك مولانا جل ّ وعلا وقد أوصى سبحانه وتعالى فيهما بوصايا وهي أحكامه الشرعية فالأمانة المحافظة على وصاياه جل وعلا وعدم التبديل فيها والتغيير، ولما كان الرسل عليهم الصلاة والسلام أكرم الخلق على الله وأتقاهم وأعرفهم بالله وأشدهم خوفا كانوا أعظم الناس أمانة وأشدهم محافظة على وصاياه تبارك وتعالى ولما أكرمهم سبحانه وتعالى بأعظم أمانة وعصمهم من كل خيانة جعلهم قدوة وأطلق في متابعتهم ولم يجعل فيها تقييدا فلو جوزنا أن يقع في أفعالهم ما هو محرم أو مكروه لزم أن يجتمع في ذلك المحرم والمكروه الإذن في فعلهما\r[المواهب اللدنية]\rلا وجود لها أو وجوه واعتبارات لا توجد إلا في الأذهان وذلك غير معقول لعاقل فان صح ذلك عندهم فمعناه الله ثلاثة وإلا فمعناه الله ثلاث ثلاثة والذي أفاده القرآن تصريحهم بأن الله والمسيح ومريم ثلاثة آلهة وأن المسيح ولد الله من مريم بشهادة قوله تعالى (أَأَنتَ قُلتَ لِلنَّاسِ اتَّخِذُونِي وَأُمِّيَ إِلَهَيْنِ مِن دُونِ اللّهِ) وقوله ((وقالت النصارى المسيح ابن الله)) وقد اشتهر عندهم أنهم قالوا إن ألوهيته من جهة الأب وناسوته من جهة الأم بشهادة قوله ((الْحَقِّ إِنَّمَا الْمَسِيحُ عِيسَى ابْنُ مَرْيَمَ رَسُولُ اللّهِ وَكَلِمَتُهُ أَلْقَاهَا إِلَى مَرْيَمَ)) فأثبت أنه ولدها اتصل بها اتصال الأولاد بأمهاتهم وأما اتصاله به تعالى فإنما هو من حيث إنه رسول وإيجاده بابتداعه جسدا حيا بلا أب يعني اتصاله به اتصال الأبناء بالآباء فهو مما أفاده قوله في الآية رسول الله ثم زعموا أيضا أن أقنوم العلم اتحد بعيسى وتدرع بناسوت جسده بطريق الامتزاج كالخمر بالماء عند الملكانية وبطريق الإشراق كالشمس في كوة بلور عند النسطورية وبطريق الانقلاب لحما ودما بحيث صار الإله هو المسيح عند اليعقوبية وهذه الآراء كلها سابقة ولاحقة هذا يانات فسلوها غنى ّ عن بيانه ((إن هم إلا كالأنعام بل هم أضل سبيلا)) (كشرط النصارى) سموا بذلك لقولهم ((نحن أنصار الله)) وقيل سموا هؤلاء الكفرة بذلك لناصرية قرية ((قاتلهم الله أنى يؤفكون اتخذوا أحبارهم ورهبانهم أربابا من دون الله والمسيح بن مريم وما أمروا إلا ليعبدوا إلها واحدا لا إله إلا هو سبحانه عما يشركون يريدون أن يطفئوا نور الله بأفواههم ويأبى الله إلا أن يتم نوره ولو كره الكافرون هو الذي أرسل رسوله بالهدى ويدن الحق ليظهره على الدين كله ولو كره الكشركون)) اللهم ثبتنا بالقول الثابت في الحياة الدنيا وفي الآخرة وارحمنا وارحم أولادنا ووالدينا وإخواننا ومشايخنا وجميع المسلمين ("]], "pg": [27, 28]}, "516.18": {"x": [[27, "وأما الرسل عليهم الصلاة والسلام فيجب لهم الصدق أي مطابقة كل ما أخبروا به وثواب وعقاب وغيرهما لما في نفس الأمر لأن الله تعالى قد صدقهم بما تنزل من المعجزة التي خصهم الله بها منزلة قوله تعالى \"صدق عبدي في كل مايبلغ عني\") هذا هو الجزء الثاني من جزأي الإيمان لأن الإيمان مركب من جزأين: أحدهما الإيمان بالله تعالى وهو حديث النفس التابع للمعرفة بما يجب له تعالى وما يستحيل وما يجوز.\rالثاني الإيمان بالرسل عليهم الصلاة والسلام وهو أيضا حديث النفس التابع للمعرفة بما يجب لهم وما يستحيل وما يجوز ولما كان الجزء الثاني موقوفا على الجزء الأول إنما يعرف ويحصل بعد معرفته قدّم علماؤنا الكلام على الجزء الأول قبل الكلام على الجزء الثاني، والرسل جمع رسول وهو إنسان بعثه الله سبحانه إلى عبيده بايمانه ليبلغهم عنه أحكامه التكليفية والوضعية وما يتبعهما من وعد ووعيد ونحوهما وهل شرطه أن يكون له شرع جديد أو كتاب مخصوص أو نسخ بشرع من قبله أو لا يشترط فيه شيء من ذلك أقوال ونحن مكلفون بمعرفة الرسل عليهم الصلاة والسلام ولا يتم إيماننا إلا بذلك ولا يحصل لنا إيمان إلا بمعرفة ما يجب لهم وما يستحيل وما يجوز فما يجب لهم عليهم الصلاة والسلام الصدق في كل ما يبلغون عن المولى تبارك وتعالى أي لا يكون خبرهم في ذلك إلا مطابقا لما في نفس الأمر ولا يقع منهم الكذب في شيء من ذلك لا عمدا ولا سهوا عند المحققين وبرهان ذلك أنه لو وقع الكذب في شيء مما بلغه الرسول عن الله تعالى لزم أن يسري ذلك الكذب إلى خبره تعالى لأنه تبارك وتعالى أشار إلى تصديق الرسل بفعل أوجده خارقا للعادة تحدّى به الرسول أي ادعاء قبل وقوعه وطلبه من المولى جل وعلا دليلا على صدقه في كل ما يبلغ عنه فأوجده تبارك وتعالى له على وفق دعواه وأعجز سبحانه وتعالى كل من يقصد تكذيبه ومعارضته أن يأتي بمثل ذلك الخارق فتنزل هذا الفعل من المولى تبارك وتعالى باعتبار الوضع والعادة وقرينة الحال منزلة التصريح بالكلام بصدق رسله عليهم الصلاة والسلام بحيث لا يجد الموفق فرقا بين تصديق الله تعالى لرسوله بهذا الفعل الموصوف بما سبق وبين تصديقهم بكلامه الصريح ألا ترى أن ملكا\r[المواهب اللدنية]\rوسعيا وإلى العبادة مباشرة وجعلا وهذه المسئلة التي بين المعتزلة والمجوس تعين اسم المرادين بالقدرية في الحديث دون ما عليه أهل الحق رضي الله تعالى عنهم وعطف شرك التبعيض لاشتراكهما في العدد وقدم الشرك التقريب على شرك الأسباب لأنه بسيط وذلك مركب وعطف عليه فرعه لئلا يفصل بين الأصل وفرعه وأخر شرك الأعراض لضعفه والله أعلم: الأول من الستة (شرك الاستقلال) يعني الانفراد، استقل برأيه إذا انفرد به حيث أفردوا إلها وللشر إلها (وهو) أي شرك الاستقلال (إثبات إلهين) اثنين (مستقلين) يعني منفردين أحدهما لخلق الخير ويسمى عندهم هرمز والآخر لخلق الشر ويسمى عندهم يزدان واتفقوا على قدم هرمز واختلفوا في قدم يزدان فزعم بعضهم أنه قديم وزعم بعضهم أنه حادث من فكرة رؤية حصلت من هرمز والوصفان متباينان له يمكن اجتماعهما في موصوف واحد فوجب أن يكون موصوفهما اثنين ويلزم على مقتضى هذا النظر الفاسد إثبات إله ثالث ليفعل من الممكنات ما ليس بخير ولا شرك وإن نفوا هذا القسم وحصروها في الخير والشر فهم مباهتون وجاحدون لما قطع بوجوده وايضا يلزمهم في الشاهد أن الفاعل للخير لا يتأنى أن يصدر منه الشر والعكس والعيان يقطع ببطلانه ويلزم أيضا على قولهم حدوث إلهين وافتقارهما إلى إله ثالث يخصص كل واحد بما اختص به من الخير والشر وكذا الثالث يفتقر إلى رابع وهلم جرا فان انتهى العدد لزم الدور وإن لم ينته لزم التسلسل وذلك محال لا يتصور في العقل وجوده فاذا فرض وجوده إله آخر مع الله مستحيل لا يتصور بوجه من الوجوه وأيضا يلزم التمانع بين الإلهين المفروضين عند إرادة أحدهما اختراع الخير في محل وإرادة الآخر اختراع الشر فيه في زمن واحد فما تخيله هؤلاء الكفرة باطل بوجه من الوجوه (و) والثاني من أنواع الشرك (شرك التبعيض) يعني التجزى (وهو) أي شرك التبعيض (تركيب) يعني تأليف (الإله) يعني ذات الإله تعالى الله عن قولهم (من آلهة) ثلاثة يعني أقانيم أي أصول ثلاثة وهو أقنوم الوجود وأقنوم العلم وأقنوم الحياة وحكموا عليها بأنها آلهة ثلاثة مع أنها صفات ثم قالوا بعد ذلك إن مجموع الثلاثة إله واحد فجمعوا بين نقيضين وحدة وكثرة فجعلوا الذات تتركب عندهم لا عندنا من مجرد أحوال"], [28, "من الملوك لو جمع في بعض الأوقات أهل مملكته وقام من المجلس بعض عبيده بمرأى منه ومسمع وقال للناس إن الملك قد بعثني إليكم بكذا وكذا وها هو عالم بمقالتي هذه إليكم سميع بصير قادر على إهلاكي إن كذبت وآية صدقي فيما ادعيته عليه أو أطلب منه أن يصدقني بأن يفعل كذا وكذا مما لم تجر عادته أن يفعله وأن يخصني بذلك ولا يفعله لأحد ممن يقصد معارضتي وتكذيبي ثم طلب من الملك ذلك الفعل ففعله له على وفق ما طلب منه وخصه به دون غيره ممكن يقصد معارضته والقدح في صدقه فيعلم على الضرورة أن الملك نازل في الدلالة على صدق ذلك الدعى منزلة صريح قول الملك إنه صدق فيما بلغ عني لا فرق بينهما أصلا وإذا ثبت ذلك لزم من كذب الرسول كذب الملك الذي قد صدقه لأن تصديق الكاذب كذب ولما كان الكذب على المولى تبارك وتعالى مستحيلا لأن خبره على وفق علمه جل وعلا والعلم لا يحتمل النقيض بوجه من الوجوه فالكلام التابع له كذلك لزم أن يكون الكذب في حق رسله عليهم الصلاة والسلام مستحيلا وذلك ظاهر وبالله تعالى التوفيق.\rالأمانة والتبليغ\r(ويجب لهم الأمانة أي حفظ ظواهرهم وبواطنهم من الوقوع في محرم أو مكروه لأن أتباعهم أمروا بالاقتداء بهم في جميع أقوالهم وأفعالهم وذلك يستلزم عصمتهم فيها من كل منهى عنه) هذا كمال ثان واجب للرسل عليهم الصلاة والسلام وهو كونهم أمناء لا خيانة لهم في شيء من الأشياء والأمين هو الذي يترك كل أمر على الوجه الذي أوصى مالكه أن يترك عليه ولا يجوز أن ينقله بسبب الشهوة من الموضع الذي ينبغي أن يكون فيه بوصية مالكه الذي تجب طاعته فالأمانة في الواجب والمندوب أن يدخلا في شريف صندوق الوجود كما أوصى بذلك فيهما مولانا جل وعلا ولا يخان بنقلهما إلى آفة العدم والأمانة في المحرم والمكروه أن يدخلا في صندوق العدم ولا ينقلا عنه إلى شريف الوجود كما أوصى أيضا بذلك فيهما تبارك وتعالى ولا شك أن الذوات والأفعال كلها ملك مولانا جل ّ وعلا وقد أوصى سبحانه وتعالى فيهما بوصايا وهي أحكامه الشرعية فالأمانة المحافظة على وصاياه جل وعلا وعدم التبديل فيها والتغيير، ولما كان الرسل عليهم الصلاة والسلام أكرم الخلق على الله وأتقاهم وأعرفهم بالله وأشدهم خوفا كانوا أعظم الناس أمانة وأشدهم محافظة على وصاياه تبارك وتعالى ولما أكرمهم سبحانه وتعالى بأعظم أمانة وعصمهم من كل خيانة جعلهم قدوة وأطلق في متابعتهم ولم يجعل فيها تقييدا فلو جوزنا أن يقع في أفعالهم ما هو محرم أو مكروه لزم أن يجتمع في ذلك المحرم والمكروه الإذن في فعلهما\r[المواهب اللدنية]\rلا وجود لها أو وجوه واعتبارات لا توجد إلا في الأذهان وذلك غير معقول لعاقل فان صح ذلك عندهم فمعناه الله ثلاثة وإلا فمعناه الله ثلاث ثلاثة والذي أفاده القرآن تصريحهم بأن الله والمسيح ومريم ثلاثة آلهة وأن المسيح ولد الله من مريم بشهادة قوله تعالى (أَأَنتَ قُلتَ لِلنَّاسِ اتَّخِذُونِي وَأُمِّيَ إِلَهَيْنِ مِن دُونِ اللّهِ) وقوله ((وقالت النصارى المسيح ابن الله)) وقد اشتهر عندهم أنهم قالوا إن ألوهيته من جهة الأب وناسوته من جهة الأم بشهادة قوله ((الْحَقِّ إِنَّمَا الْمَسِيحُ عِيسَى ابْنُ مَرْيَمَ رَسُولُ اللّهِ وَكَلِمَتُهُ أَلْقَاهَا إِلَى مَرْيَمَ)) فأثبت أنه ولدها اتصل بها اتصال الأولاد بأمهاتهم وأما اتصاله به تعالى فإنما هو من حيث إنه رسول وإيجاده بابتداعه جسدا حيا بلا أب يعني اتصاله به اتصال الأبناء بالآباء فهو مما أفاده قوله في الآية رسول الله ثم زعموا أيضا أن أقنوم العلم اتحد بعيسى وتدرع بناسوت جسده بطريق الامتزاج كالخمر بالماء عند الملكانية وبطريق الإشراق كالشمس في كوة بلور عند النسطورية وبطريق الانقلاب لحما ودما بحيث صار الإله هو المسيح عند اليعقوبية وهذه الآراء كلها سابقة ولاحقة هذا يانات فسلوها غنى ّ عن بيانه ((إن هم إلا كالأنعام بل هم أضل سبيلا)) (كشرط النصارى) سموا بذلك لقولهم ((نحن أنصار الله)) وقيل سموا هؤلاء الكفرة بذلك لناصرية قرية ((قاتلهم الله أنى يؤفكون اتخذوا أحبارهم ورهبانهم أربابا من دون الله والمسيح بن مريم وما أمروا إلا ليعبدوا إلها واحدا لا إله إلا هو سبحانه عما يشركون يريدون أن يطفئوا نور الله بأفواههم ويأبى الله إلا أن يتم نوره ولو كره الكافرون هو الذي أرسل رسوله بالهدى ويدن الحق ليظهره على الدين كله ولو كره الكشركون)) اللهم ثبتنا بالقول الثابت في الحياة الدنيا وفي الآخرة وارحمنا وارحم أولادنا ووالدينا وإخواننا ومشايخنا وجميع المسلمين ("]], "pg": [27, 28]}, "516.19": {"x": [[28, "و) الثالث من أنواع الشرك (شرك التقريب) أي التوسل (وهو) أي شرك التقريب (عبادة) يعني خدمة (غير الله تعالى) كالأصنام والملائكة والشمس والقمر والنجوم والنار وغيرها والمقصود من عبادة هذه المذكورات (ليقرب) العابد لما ذكر (إلى الله زلفى) فربى مصدر بمعنى تقريبا (كشرك متقدمي الجاهلية) ولا خفاء في كفرهم وضلالهم وتلاعب الشيطان اللعين بعقولهم نسأل الله السلامة والعافية بمنه وكرمه ولو انتبهوا أدنى تنبيه لعلموا استواء جميع العوالم من عرشها إلى"], [29, "أخذا من قاعدة الترغيب في متابعة الرسل والحض على الاقتداء بهم وعدم الإذن لما فرض فيهما من التحريم والكراهة وذلك جمع بين نقيضين وهذه المتابعة للرسول ومولانا محمد صلى الله عليه وسلم بلا استثناء ولا تردد ولا تأمل إلا فيما خص به قد عرفت ضرورة من حال الصحابة والتابعين لهم باحسان وقد أمرنا مولانا جل وعلا بمتابعته على الاطلاق في آيات من القرآن وجعلها علما على محبته وذلك دليل واضح في غاية على كمال العصمة العامة له وبالله تعالى التوفيق (ويجب لهم أيضا أنهم بلغوا كل ما أمر المولى سبحانه بتبليغه ولم يتركوا شيئا منه لا نسيانا ولا عمدا فلما سبق في الأمانة وأما نسيانا فللاجماع) هذا أيضا كمال ثالث واجب للرسل عليهم الصلاة والسلام وهو وفاؤهم بتبليغ كل ما أرسلهم الله تعالى به وأمرهم أن يبلغوه للناس وأنهم لم يخفوا على الناس شيئا من ذلك لا عمدا ولا نسيانا والتبليغ في ذلك على الوجه الذي أمروا به من عموم الناس أو خصوص لهم وبرهان امتناع إخفائهم شيئا من ذلك على طريق العمد واضح من برهان الأمانة السابق لأن هذا كتمان للحق وخيانة محرمه وهم أمناء معصومون من المحرم أن يدخلوه في دائرة الوجود بعد معرفتهم نهى مولانا جل وعلا عن ذلك وأما إخفاؤهم شيئا من ذلك على طريق النسيان فالمحققون أيضا على منحه ودليله إجماع السلف وقد صرح القرآن بكمال التبليغ في حق نبينا ومولانا محمد صلى الله عليه وسلم في قوله تعالى ((اليوم أكملت لكم دينكم وأتممت عليكم نعمتي)) وصرح بذلك النبي صلى الله عليه وسلم في الحديث ولم يحضرني الآن لفظ الحديث وصرح بذلك الرسل عليهم الصلاة والسلام في القرآن كقوله تعالى ((أبلغتكم رسالات ربي ونصحت لكم ولكن لا تحبون الناصحين)) وقوله تعالى ((لقد أبلغتكم رسالات ربي ونصحت لكم فكيف آسى على قوم كافرين)) وتتبع بذلك في القرآن العظيم كثير وبالله تعالى التوفيق ... (فالواجب الأول يزيد على الأمانة يمنع الكذب سهوا ويزيد على التبليغ بمنع الزيادة على ما أمروا بتبليغه عمدا أو نسيانا وتزيد الأمانة على الصدق بمنع وقوع المخالفة في غير كذب اللسان وتزيد على التبليغ بمنع المخالفة في غير التبليغ ويزيد التبليغ على الصدق بمنع ترك شيء مما أمروا بتبليغه عمدا أو نسيانا مع لزوم الصدق فما بلغوا من ذلك ويزيد على الأمانة بمنع ترك شيء مما أمروا بتبليغه نسيانا) تعرضنا في أصل العقيدة لما بين هذه الواجبات الثلاثة من النسب لئلا يتوهم أن فيها تكرارا أو أن فيها ترادفا أو تساويا أو عموما وخصوصا بالاطلاق بحيث يستغنى بالأخص عن الأعم منهما على أن بينهما عموما وخصوصا من وجه فلا يمكن\r[المواهب اللدنية]\rفرشها في العجز والافتقار الذاتي للخالق لها وهو الله سبحانه وتعالى وبالإعراض ويعز من يشاء ويذل فليس له منها معين ولا وزير ولا وكيل ولا واسطة أصلا ولا يغيب عليه تعالى منها شيء ولا يقدر أحد منها أن يقرب نفسه فكيف بغيره إلى نعمة أو يبعدها عن نقمة إلا أن يتفضل المولى العظيم بذلك على من يشاء بمحض الفضل والكرم من غير غرض ولا وجوب ولا استحقاق وطاعات الطائعين ومعاصي العاصين إنما هي أفعال من أفعاله المخلوقة له في ذوات عبيده لا نفع له منها ولا ضرر فهو الغني على الإطلاق بذاته عما سواه فكل رحمة منه فضل وكل نقمة عدل ((لا يسأل عما يفعل وهم يسألون)) فله الحمد رب السموات ورب الأرض رب العالمين وله الكبرياء في السموات والأرض وهو العزيز الحكيم. وبالجملة فقد أطبقت رسل المولى تبارك وتعالى وأجمعوا كلهم من لدن آدم إلى خاتم النبيين وسيد المرسلين نبينا ومولانا محمد صلى الله عليه وسلم وعليهم أجمعين على أن الله سبحانه كلف عباده بتوحيده وحرم عليهم الشرك في ألوهيته وعبادته وبلغوا عن المولى تبارك وتعالى أن من ابتلى بهذا المحرم وهو شرك الألوهية والعبادة ومات على ذلك فهو محروم من جميع نعم الآخرة نخلد في العذاب العظيم إلى غير نهاية عصمنا الله من ذلك بمنه. فان قلت التوسل إلى الله تعالى بأنبيائه ورسله وملائكته وأوليائه هل يقتضي تلك الشبهة.\rفالجواب لا يقتضي أن علم أن الملك يأذن في ذلك ويحبه وقد جاء الشرع بذلك بشهادة ... ((توسلوا إلى الله بجاهي فان جاهي عند الله عظيم)) فلم تقتض هذه الشبهة الإشراك مع الملك بخرف شبهة الضالين المضلين لآنهم يعبدون الأصنام كما يعبد الاله، والمسلمون لا يعبدون الأصنام فاعرف ذلك (و) الرابع من أنواع الشرك (شرك التقليد) "]], "pg": [28, 29]}, "516.20": {"x": [[28, "ويجب لهم الأمانة أي حفظ ظواهرهم وبواطنهم من الوقوع في محرم أو مكروه لأن أتباعهم أمروا بالاقتداء بهم في جميع أقوالهم وأفعالهم وذلك يستلزم عصمتهم فيها من كل منهى عنه) هذا كمال ثان واجب للرسل عليهم الصلاة والسلام وهو كونهم أمناء لا خيانة لهم في شيء من الأشياء والأمين هو الذي يترك كل أمر على الوجه الذي أوصى مالكه أن يترك عليه ولا يجوز أن ينقله بسبب الشهوة من الموضع الذي ينبغي أن يكون فيه بوصية مالكه الذي تجب طاعته فالأمانة في الواجب والمندوب أن يدخلا في شريف صندوق الوجود كما أوصى بذلك فيهما مولانا جل وعلا ولا يخان بنقلهما إلى آفة العدم والأمانة في المحرم والمكروه أن يدخلا في صندوق العدم ولا ينقلا عنه إلى شريف الوجود كما أوصى أيضا بذلك فيهما تبارك وتعالى ولا شك أن الذوات والأفعال كلها ملك مولانا جل ّ وعلا وقد أوصى سبحانه وتعالى فيهما بوصايا وهي أحكامه الشرعية فالأمانة المحافظة على وصاياه جل وعلا وعدم التبديل فيها والتغيير، ولما كان الرسل عليهم الصلاة والسلام أكرم الخلق على الله وأتقاهم وأعرفهم بالله وأشدهم خوفا كانوا أعظم الناس أمانة وأشدهم محافظة على وصاياه تبارك وتعالى ولما أكرمهم سبحانه وتعالى بأعظم أمانة وعصمهم من كل خيانة جعلهم قدوة وأطلق في متابعتهم ولم يجعل فيها تقييدا فلو جوزنا أن يقع في أفعالهم ما هو محرم أو مكروه لزم أن يجتمع في ذلك المحرم والمكروه الإذن في فعلهما\r[المواهب اللدنية]\rلا وجود لها أو وجوه واعتبارات لا توجد إلا في الأذهان وذلك غير معقول لعاقل فان صح ذلك عندهم فمعناه الله ثلاثة وإلا فمعناه الله ثلاث ثلاثة والذي أفاده القرآن تصريحهم بأن الله والمسيح ومريم ثلاثة آلهة وأن المسيح ولد الله من مريم بشهادة قوله تعالى (أَأَنتَ قُلتَ لِلنَّاسِ اتَّخِذُونِي وَأُمِّيَ إِلَهَيْنِ مِن دُونِ اللّهِ) وقوله ((وقالت النصارى المسيح ابن الله)) وقد اشتهر عندهم أنهم قالوا إن ألوهيته من جهة الأب وناسوته من جهة الأم بشهادة قوله ((الْحَقِّ إِنَّمَا الْمَسِيحُ عِيسَى ابْنُ مَرْيَمَ رَسُولُ اللّهِ وَكَلِمَتُهُ أَلْقَاهَا إِلَى مَرْيَمَ)) فأثبت أنه ولدها اتصل بها اتصال الأولاد بأمهاتهم وأما اتصاله به تعالى فإنما هو من حيث إنه رسول وإيجاده بابتداعه جسدا حيا بلا أب يعني اتصاله به اتصال الأبناء بالآباء فهو مما أفاده قوله في الآية رسول الله ثم زعموا أيضا أن أقنوم العلم اتحد بعيسى وتدرع بناسوت جسده بطريق الامتزاج كالخمر بالماء عند الملكانية وبطريق الإشراق كالشمس في كوة بلور عند النسطورية وبطريق الانقلاب لحما ودما بحيث صار الإله هو المسيح عند اليعقوبية وهذه الآراء كلها سابقة ولاحقة هذا يانات فسلوها غنى ّ عن بيانه ((إن هم إلا كالأنعام بل هم أضل سبيلا)) (كشرط النصارى) سموا بذلك لقولهم ((نحن أنصار الله)) وقيل سموا هؤلاء الكفرة بذلك لناصرية قرية ((قاتلهم الله أنى يؤفكون اتخذوا أحبارهم ورهبانهم أربابا من دون الله والمسيح بن مريم وما أمروا إلا ليعبدوا إلها واحدا لا إله إلا هو سبحانه عما يشركون يريدون أن يطفئوا نور الله بأفواههم ويأبى الله إلا أن يتم نوره ولو كره الكافرون هو الذي أرسل رسوله بالهدى ويدن الحق ليظهره على الدين كله ولو كره الكشركون)) اللهم ثبتنا بالقول الثابت في الحياة الدنيا وفي الآخرة وارحمنا وارحم أولادنا ووالدينا وإخواننا ومشايخنا وجميع المسلمين (و) الثالث من أنواع الشرك (شرك التقريب) أي التوسل (وهو) أي شرك التقريب (عبادة) يعني خدمة (غير الله تعالى) كالأصنام والملائكة والشمس والقمر والنجوم والنار وغيرها والمقصود من عبادة هذه المذكورات (ليقرب) العابد لما ذكر (إلى الله زلفى) فربى مصدر بمعنى تقريبا (كشرك متقدمي الجاهلية) ولا خفاء في كفرهم وضلالهم وتلاعب الشيطان اللعين بعقولهم نسأل الله السلامة والعافية بمنه وكرمه ولو انتبهوا أدنى تنبيه لعلموا استواء جميع العوالم من عرشها إلى"], [29, "أخذا من قاعدة الترغيب في متابعة الرسل والحض على الاقتداء بهم وعدم الإذن لما فرض فيهما من التحريم والكراهة وذلك جمع بين نقيضين وهذه المتابعة للرسول ومولانا محمد صلى الله عليه وسلم بلا استثناء ولا تردد ولا تأمل إلا فيما خص به قد عرفت ضرورة من حال الصحابة والتابعين لهم باحسان وقد أمرنا مولانا جل وعلا بمتابعته على الاطلاق في آيات من القرآن وجعلها علما على محبته وذلك دليل واضح في غاية على كمال العصمة العامة له وبالله تعالى التوفيق (ويجب لهم أيضا أنهم بلغوا كل ما أمر المولى سبحانه بتبليغه ولم يتركوا شيئا منه لا نسيانا ولا عمدا فلما سبق في الأمانة وأما نسيانا فللاجماع) هذا أيضا كمال ثالث واجب للرسل عليهم الصلاة والسلام وهو وفاؤهم بتبليغ كل ما أرسلهم الله تعالى به وأمرهم أن يبلغوه للناس وأنهم لم يخفوا على الناس شيئا من ذلك لا عمدا ولا نسيانا والتبليغ في ذلك على الوجه الذي أمروا به من عموم الناس أو خصوص لهم وبرهان امتناع إخفائهم شيئا من ذلك على طريق العمد واضح من برهان الأمانة السابق لأن هذا كتمان للحق وخيانة محرمه وهم أمناء معصومون من المحرم أن يدخلوه في دائرة الوجود بعد معرفتهم نهى مولانا جل وعلا عن ذلك وأما إخفاؤهم شيئا من ذلك على طريق النسيان فالمحققون أيضا على منحه ودليله إجماع السلف وقد صرح القرآن بكمال التبليغ في حق نبينا ومولانا محمد صلى الله عليه وسلم في قوله تعالى ((اليوم أكملت لكم دينكم وأتممت عليكم نعمتي)) وصرح بذلك النبي صلى الله عليه وسلم في الحديث ولم يحضرني الآن لفظ الحديث وصرح بذلك الرسل عليهم الصلاة والسلام في القرآن كقوله تعالى ((أبلغتكم رسالات ربي ونصحت لكم ولكن لا تحبون الناصحين)) وقوله تعالى ((لقد أبلغتكم رسالات ربي ونصحت لكم فكيف آسى على قوم كافرين)) وتتبع بذلك في القرآن العظيم كثير وبالله تعالى التوفيق ... (فالواجب الأول يزيد على الأمانة يمنع الكذب سهوا ويزيد على التبليغ بمنع الزيادة على ما أمروا بتبليغه عمدا أو نسيانا وتزيد الأمانة على الصدق بمنع وقوع المخالفة في غير كذب اللسان وتزيد على التبليغ بمنع المخالفة في غير التبليغ ويزيد التبليغ على الصدق بمنع ترك شيء مما أمروا بتبليغه عمدا أو نسيانا مع لزوم الصدق فما بلغوا من ذلك ويزيد على الأمانة بمنع ترك شيء مما أمروا بتبليغه نسيانا) تعرضنا في أصل العقيدة لما بين هذه الواجبات الثلاثة من النسب لئلا يتوهم أن فيها تكرارا أو أن فيها ترادفا أو تساويا أو عموما وخصوصا بالاطلاق بحيث يستغنى بالأخص عن الأعم منهما على أن بينهما عموما وخصوصا من وجه فلا يمكن\r[المواهب اللدنية]\rفرشها في العجز والافتقار الذاتي للخالق لها وهو الله سبحانه وتعالى وبالإعراض ويعز من يشاء ويذل فليس له منها معين ولا وزير ولا وكيل ولا واسطة أصلا ولا يغيب عليه تعالى منها شيء ولا يقدر أحد منها أن يقرب نفسه فكيف بغيره إلى نعمة أو يبعدها عن نقمة إلا أن يتفضل المولى العظيم بذلك على من يشاء بمحض الفضل والكرم من غير غرض ولا وجوب ولا استحقاق وطاعات الطائعين ومعاصي العاصين إنما هي أفعال من أفعاله المخلوقة له في ذوات عبيده لا نفع له منها ولا ضرر فهو الغني على الإطلاق بذاته عما سواه فكل رحمة منه فضل وكل نقمة عدل ((لا يسأل عما يفعل وهم يسألون)) فله الحمد رب السموات ورب الأرض رب العالمين وله الكبرياء في السموات والأرض وهو العزيز الحكيم. وبالجملة فقد أطبقت رسل المولى تبارك وتعالى وأجمعوا كلهم من لدن آدم إلى خاتم النبيين وسيد المرسلين نبينا ومولانا محمد صلى الله عليه وسلم وعليهم أجمعين على أن الله سبحانه كلف عباده بتوحيده وحرم عليهم الشرك في ألوهيته وعبادته وبلغوا عن المولى تبارك وتعالى أن من ابتلى بهذا المحرم وهو شرك الألوهية والعبادة ومات على ذلك فهو محروم من جميع نعم الآخرة نخلد في العذاب العظيم إلى غير نهاية عصمنا الله من ذلك بمنه. فان قلت التوسل إلى الله تعالى بأنبيائه ورسله وملائكته وأوليائه هل يقتضي تلك الشبهة.\rفالجواب لا يقتضي أن علم أن الملك يأذن في ذلك ويحبه وقد جاء الشرع بذلك بشهادة ... ((توسلوا إلى الله بجاهي فان جاهي عند الله عظيم)) فلم تقتض هذه الشبهة الإشراك مع الملك بخرف شبهة الضالين المضلين لآنهم يعبدون الأصنام كما يعبد الاله، والمسلمون لا يعبدون الأصنام فاعرف ذلك (و) الرابع من أنواع الشرك (شرك التقليد) "]], "pg": [28, 29]}, "516.21": {"x": [[29, "أي الاتباع للغير (وهو) أي شرك التقليد (عبادة) يعني خدمة (غير الله تعالى) كالأوثان وغيرها ... (تبعا للغير) لأجل الحمية والتعصب بالآباء والأجداد في متابعتهم على الباطل وأسباب الهلاك في العاجل والآجل (كشرك متأخري الجاهلية) القائلين حين جاءهم الرسول ونبههم على سفه عقول آبائهم وكفرهم وضلالهم ((إنا وجدنا آباءنا على أمة وإنا على آثارهم مقتدرون)) ولهذا قال المحققون لا يكفي التقليد في عقائد الإيمان قال بعض المشايخ لا فرق بين مقلد ينقاد وبهيمة تنقاد (و) الخامس من أنواع الشرك"]], "pg": [29, 29]}, "516.22": {"x": [[30, "حينئذ الاستغناء ببعضها عن بعض لأن كل واحد يزيد على صاحبه بزيادة لا تفهم إلا منه وبيان ذلك أن الواجب الأول وهو الصدق يزيد على الأمانة بمنع الكذب سهوا أي هذه النقيصة إنما يفهم امتناعها في حق الرسل عليهم الصلاة والسلام من الواجب الأول الذي هو الصدق لأنه عام في كل قول ولا يفهم امتناعها من الواجب الثاني الذي هو الأمانة لأنها إنما تمنع من وقوع المعصية والمكروه والكذب سهوا ليس بحرام ولا مكروه فلا منافاة بينه وبين الأمانة ويزيد أيضا الصدق على الواجب الثالث الذي هو التبليغ العام بمنع الزيادة على ماأمروا بتبليغه عمدا أو نسيانا أي هذه القيمة لا تفهم من الواجب الثالث لأنها وقعت بعد التبليغ العام فلا تنافيه وتفهم من الواجب الأول الذي هو الصدق لأن هذه الزيادة كذب ووجوب الصدق العام يدفعها وأما الواجب الثاني وهو الأمانة فيزيد على الواجب الأول الذي هو الصدق يمنع وقوع المعصية والمكروه في غير كذب اللسان كالغيبة مثلا والنظر العمد للأجنبية من غير ضرورة فهذه النقيصة إنما يفهم امتناعها من الواجب الثاني الذي هو الأمانة لمنافاتها للمعصية والمكروه ولا يفهم امتناعها من وجوب الصدق لأنها ليست بكذب حتى يدفعها الصدق وتزيد الأمانة أيضا على الواجب الثالث الذي هو التبليغ العام بمنع المعصية التي لا تتعلق بالتبليغ كالسرقة مثلا والخديعة ونحو ذلك وهو ظاهر وأما الواجب الثالث وهو التبليغ العام فيزيد على الواجب الأول وهو الصدق بمنع ترك شيء مما أمروا بتبليغه عمدا أو نسيانا مع التزامهم الصدق فيما بلغوا من ذلك أي هذه النقيصة أيضا إنما يفهم امتناعها في حق الرسل عليهم الصلاة والسلام من الواجب الثالث وهو التبليغ العام لأن النقص عمدا أو نسيانا مناف لوجوب عموم التبليغ وليس بمناف لوجوب الصدق لأنه قد يصدق فيما بلغ ويترك شيئا آخر أجنبيا عنه فترك تبليغه ليس بكذب فيه إذا لم يخبر فيه بشيء ولا فيما بلغ لصدقه ويزيد أيضا وجوب التبليغ العام على الواجب الثاني الذي هو الأمانة يمنع ترك شيء مما أمروا بتبليغه نسيانا أي هذه النقيصة إنما يفهم نفيها عن الرسل عليهم الصلاة والسلام من الواجب الثالث الذي هو التبليغ العام لمنافاتها له لأن السلب الجزئي مناف للثبوت الكلي ولا يفهم نفيها من الواجب الثاني الذي هو الأمانة لما عرفت أن الأمانة إنما تدفع المعصية والمكروه وما يفعل نسيانا لا معصية فيه ولا كراهة وذلك ظاهر وبالله تعالى التوفيق (ولا يخفى عليك بعد هذا ما تشترك فيه الواجبات الثلاثة وما يشترك فيه اثنان منها دون الثالث وما يزيد به كل واحد منهما على مجموع الباقين) يعني أنك إذا حققت\r[المواهب اللدنية]\r(شرك الأسباب) جمع سبب والمراد منه الأسباب العادية الآتي ذكرها إن شاء الله تعالى (وهو) أي شرك الأسباب (إسناد التأثير) يعني إضافة الاختراع (للأسباب العادية) ككون الطعام يشبع والماء يروي وينظف والسكين تقطع والثوب يستر العورة والنار تحرق والشمس تضيء وغير ذلك مما لا ينحسر (كشرك الفلاسفة) جمع فيلسوف أو فيلسوفي ومعناه محب الحكمة والسوف الحكمة والغي: المحب وقد تفلسف وهي الفلسفة مصدر مشتق من اسم جامد وهو فيلسوف وهو في الاصطلاح مركب إضافي بلفظ قيل مضاف وسوف مضاف إليه ومعنى المضاف محب ومعنى المضاف إليه الحكمة (و) شرك (الطبائعين و) شرك (من) أي الذي (تبعهم) أي تبع الفلاسفة والطبائعيين (على ذلك) الاعتقاد الفاسد وهو إسناد التأثير للأسباب العادية من جهلة المؤمنين فرأوا ارتباط الشبع الأكل والري بالماء وستر العورة بلبس الثوب والضوء عند الشمس والاحراق عند النار ونحو ذلك ففهموا من جهلهم أن تلك الشياء هي المؤثرة فيما ارتبط وجوده معها إما بطبعها وإما بقوة وضعها الله تعالى فيها وفي معنى شرك الأسباب العادية شرك القدرية فيما اعتقدوه من تأثير القدرة التي خلق الله تعالى للحيوانات فيما يقارنها من الأفعال (و) السادس من الأنواع الشرك (شرك الأغراض) "]], "pg": [30, 30]}, "516.23": {"x": [[30, "أي الحاجات والبواعث (وهو) أي شرك الأعراض والبواعث (العمل) المأمور به من واجب ومندوب وتجنب محرم ومكروه (غير) امتثال أمر (الله تعالى) بل لمجرد نيل مدح من بعض عبيده أو حب منه له أو رياسة عنده أو ظفر عال من قبله أو صرف مذمة يخافها.\rمنه ونحو ذلك العمل لمجرد الظفر بالحور والقصور ونعيم الجنان والسلامة من النيران والسبب الحامل لذلك نسيان توحيد المولى تبارك وتعالى حتى توهم أن الخلق يقدرون على النفع والضر حتى شركهم في طاعته ولو تيقن بقلبه انفراد المولى تبارك وتعالى بخلق جميع الكائنان بلا واسطة ولا أثر لكل ما سواه على العموم ومن جملة ذلك طاعته لما قصد بطاعته أن وفق لها إلا مجرد الامتثال لأمر الله تعالى ثم يطمع عندها بما وعد به المولى الكريم جل وعلا من الخير معها بمحض الفضل من غير وجوب ولا استحقاق والمراد بالعمل في قوله رضي الله عنه العمل المطلوب شرعا إذ هو الذي يحرم فيه الرياء والله الموفق بمنه.@"], [31, "معاني الواجبات الثلاثة وعرفت ما يزيد به كل واحد منها على صاحبيه سهل عليك فهم هذه المطالب الثلاثة: أحدهما معرفة النقيصة التي تشترك الواجبات الثلاثة في نفيها عن الرسل عليهم الصلاة والسلام وهي تبديل شيء مما أمر الله تعالى بتبليغه وتغيير معناه عمدا لأنه كذب فوجوب الصدق للرسل ينفيه وهو أيضا معصية فوجوب الأمانة أيضا يدفعه وهو أيضا كتمان لما أمر المولى العظيم بتبليغه فوجوب تبليغ الرسل عليهم الصلاة والسلام لكل ما أمرهم المولى العظيم بتبليغه يدفع أيضا هذه النقيصة عنهم فهذه نقيصة تشترك الواجبات الثلاثة في نفيها عن الرسل عليهم الصلاة والسلام، الثاني من المطالب الثلاثة الباقية النقيصة التي يشترك في نفيها عن الرسل عليهم الصلاة والسلام اثنان من الواجبات الثلاثة ويزيدان به على الواجب الثالث فيشترك الواجب الأول والثاني وهما الصدق والأمانة في منع الكذب عمدا في الزائد على المأمور بتبليغه ولا يمنعه الواجب الثالث الذي هو التبليغ العام لأن هذه النقيصة إنما وقعت بعد التبليغ العام ويشترك الواجب الأول والثالث وهما الصدق والتبليغ العام في منع التبديل نسيانا بالبعض المأمور بتبليغه فانه مناف للصدق لأنه كذب ومناف للتبليغ المأمور بتبليغه ولا يمنع هذه النقيصة وجوب الأمانة لأنها تمنع المعصية والمكروه والتبديل نسيانا لا تكليف فيه فليس بمعصية ولا مكروه وتشترك الأمانة والتبليغ العام في منع نقص شيء من المأمور بتبليغه عمدا فانه معصية وترك للتبيلغ العام فكل واحد من هذين الواجبين ينفيه عن الرسل عليهم الصلاة والسلام ولا ينفيه الواجب الأول الذي هو الصدق لأن الترك من غير تبديل ليس بكذب.\rالثالث من المطالب الثلاثة ما يزيد به كل واحد من الواجبات الثلاثة على مجموع الواجبين الباقيين فالواجب الأول وهو الصدق يزيد على مجموع الأمانة والتبليغ العام بمنع الكذب نسيانا في غير المأمور بتبليغه لأنه مناف للصدق وليس منافيا للأمانة ولا للتبليغ العام فلا يفهم نفيه عن الرسل عليهم الصلاة والسلام إلا من الواجب الأول الذي هو الصدق ويزيد الواجب الثاني وهو الأمانة على مجموع الصدق والتبليغ العام بمنع المعصية في غير الكذب ويعد التبليغ العام كالسرقة ويزيد التبليغ العام على مجموع الواجبين الأولين وهما الصدق والأمانة بمنع نقص شيء مما أمروا بتبليغه نسيانا من غير تبديل ولا إخلال فيما بلغ فانه مناف للتبليغ العام فيفهم منه ولا ينافي الواجبين الأولين إذ ليس بكذب ولا خيانة فجميع المطالب في هذه الواجبات الثلاثة خمسة هذه المطالب التي ذكرناها والمطلبان السابقان وهما معرفة معاني الواجبات الثلاثة ومعرفة ما يزيد به كل واحد منها على كل واحد من صاحبيه وبالله تعالى التوفيق.\r[المواهب اللدنية]\r{خاتمة} واعلم أن من مات على حالة من هؤلاء والعياذ بالله يترتب عليه أمور: الأول عدم المغفرة لقوله تعالى ((إِنَّ اللّهَ لاَ يَغْفِرُ أَن يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَن يَشَاء)).\rالثاني عدم دخول الجنة لقوله تعالى ((من يشرك بالله فقد حرم الله عليه الجنة)) الثالث الخلود في النار لقوله تعالى ((والمشركين في نار جهنم خالدين فيها)) ولما فرغ من الكلام على أنواع الشرك شرع يفصل ما يلزم منه الكفر وما لا يلزم فقال (وحكم الأربعة الأول) مراده بالأربعة الأول كفر الاستقلال وكفر التبعيض وكفر التقريب وكفر والأول بضم همزة لام ألف جمع أول (الكفر باجماع) يعني باتفاق وطذا الإجماع على كفر من لم يكفر أحدا من النصارى واليهود وكل من فارق دين المسلمين أو توقف في تكفيرهم أو شك قال القاضي أبو بكر الباقلاني لأن التوقف والشك لا يجوز مع الإجماع على كفرهم فمن توقف في ذلك فقد كذب النص والتوقف والشك فيه لا يقع إلا من كافر اهـ (وحكم السادس) يعني بالسادس شرك الأغراض وهو العمل لغير الله تعالى (المعصية) يعني مخالفة الأمر الشرعي (من غير كفر) يعني شرك (بالإجماع) يتعلق بآخر الكلام وهو غير كفر يعني باتفاق من الأمة. فان قلت لم خالف المصنف في تقديمه السادس على الخامس والقياس والترتيب الطبيعي تقديم الخامس على السادس. قلت إنما جعل ذلك لأنه لما ذكر الأقسام الأربعة الأول التي فيها الكفر باجماع قابلها بالسادس الذي فيه المعصية من غير كفر باجماع ولما كان الخامس فيه تفصيل أخره لذلك والله أعلم. فان قلت هل يكون العمل وباء إذا أخلصه العبد لله تعالى وقصد مع ذلك غرضا دنيويا يستعين به على طاعة الله تعالى. فالجواب لا يكون ذلك رياء وعلى هذا يحمل ما ورد في بعض الطاعات أنها سبب للتوسع في الرزق كحديث ((من يقول بين الفجر والصبح سبحان من يجير ولا يجار سبحان من يبرأ من الحول والقوة إليه سبحان من التسبيح منه منة على من اعتماد عليه سبحان من سبح كل شيء بحمده سبحانك لا إله إلا أنت يامن يسبح له الجميع تدارنكي بعفوك فاني جزوع ثم يستغفر الله مائة فانه لا يأتي عليه أربعون يوما إلا وأتته الدنيا بحذافرها)) مجرب صح من حزب البحر لسيدنا أحمد زروق رحمه الله قال المصنف رحمه الله تعالى وقد يحمل ذلك على التوسعة المعنوية بخلق القناعة"], [32, "(وأما المستحيل في حقهم عليهم الصلاة والسلام فاضداد هذه الثلاثة) لاخفاء أنه إذا علم ما يجب في حق الرسل عليهم الصلاة والسلام علم منه ما يستحيل في حقهم ولما علم وجوب الصدق في حقهم علم استحالة الكذب عليهم وهو الإخبار بما لا يطابق ما في نفس الأمر ولما علم وجوب الأمانة لهم علم منه استحالة الخيانة عليهم وهو التلبس بمنهي عنه نهي تحريم أو كراهة ولما علم وجوب التبليغ العام لهم علم منه استحالة عدم التبليغ للشيء مما أمروا بتبليغه عمدا أو سهوا وذلك ظاهر وبالله تعالى التوفيق (وأما الجائز في حقهم عليهم الصلاة والسلام فالأعراض البشرية التي لا تنافي علو رتبتهم كالمرض ونحوه بدليل مشاهدة ذلك فيهم وفي اتصافهم بها فوائد لا تخفى) مراده بنحو المرض الجوع والفقر من الأعراض الدنيوية مع الغنى عنها بالله تعالى والأكل والشرب والنكاح والنسيان بعد التبليغ أو فيما لم يؤمروا بتبليغه والنوم إلا أنه تنام أعينهم ولاتنام قلوبهم ولا شك أنه قد شوهد جميع ذلك فيهم وقوله وفي اتصافهم بها فوائد لا تخفى يعني ليس نزول هذه الأعراض بهم كنزولها بغيرهم في إمكان عدم اقترانها بالفوائد العرفانية التي تعتبرها قربا وعبادات بل لا تنزل بهم إلا عارية عن حظ النفس ودواعي الهوى محفوظة بالفوائد العرفانية والقرب الشريفة النورانية كتعبدهم لله تعالى في عرض الأكل والشرب بما ندب إليه من آدابهما والصبر والرضا عن الله تعالى عند فقدهما وايثار ذوي الفاقة مع شدة الاحتياج إليهما وتشريع جميع ذلك للمؤمنين بهم والتابعين لهم وكذا حكم مرضهم وجوعهم مع زيادة حصول التسلى عن الدنيا للأمة وتنبهم لخسة قدرها عند الله تعالى إذ لو كان لها موقع عند الله تعالى لأعطاها لهؤلاء السادات الكرام الذين هم أشرف الخلق عنده تبارك وتعالى ولحرصوا عليهم الصلاة والسلام على جمعها والتمتع بها أكثر من غيرهم فلما رأيناهم نافرين عن فضولها منفرين عنها في غاية علمنا أنه لاخير\rفي فضولها وأن الزهد فيها هو الحق الجامع لكل خير ولا يخفى على العاقل استنباط الفوائد الكثيرة من أحوالهم عليهم الصلاة والسلام لأن الله تعالى قد عصمهم واعتنى بكمال هدايتهم وجعلهم قدوة للخلق في أقوالهم وأفعالهم وسكونهم فهي كلها واقعة على أكمل الصفات وأشرف المقاصد وأعلى السمات وكل ما استنبط العلماء من فوائد لأقوالهم وأفعالهم وألفوا وأكثروا نقطة من بحر لا ساحل له، نسأل الله تعالى أن يزيدهم شرفا إلى مالا نهاية له وأن يدخل جميعا بلا محنة في شفاعة سيد الخلق وأكرمهم على الله تعالى سيدنا ومولانا محمد صلى اله عليه وسلم وعلى آله (فقولنا الأعراض احتراز من مذهب النصارى في وصفهم عيسى عليه السلام بالصفة القديمة وقولنا البشرية احتراز من اعتقادا الجاهلية أن البشرية تنافي\r[المواهب اللدنية]\rفي القلب والزهد الغنى بالمولى تبارك وتعالى عن كل سواه وهذا هو الغنى الأكبر والتوسعة الحقيقية (وحكم الخامس) يعني بالخامس شرك الأسباب العادية (التفصيل) أي التقسيم (فمن قال) أي اعتقد (بالأسباب العادية) المتقدم ذكرها (إنها) أي الأسباب العادية (تؤثر بطبعها) يعني بذاتها وحقيقتها كما ذهب إليه الفلاسفة والطبائعيون ومن في معناهم (فقد حكى) ابن دهاق وغيره في الإرشاد (الإجماع) أي الاتفاق (على كفره) وعدم إيمانه (ومن قال) أي اعتقد أنها لا تؤثر بطبعها وحقيقتها بل تؤثر (بقوة) أو خاصية كحجر المغناطيس مثلا (أودعها) يعني جعلها ووضعها (الله) تبارك وتعالى (فيها) يعني في هذه الأسباب العادية المقارنة والمصاحبة بعضها في بعض وأن نزعها منها لم تؤثر (فهو) أي المعتقد أنها تؤثر بقوة (فاسق) أي عاص خارج عن الحق والطاعة (مبتدع) أي أحدث في الدين ما ليس فيه لم يختلف في تفسيقه وتبديعه وإنما الخلاف في تكفيره وعدم إيمانه وإلى ذلك أشار بقوله (وفي كفره قولان) والحاصل أن الناس في اعتقادهم لهذه الأسباب على أربعة أقسام منهم من يعتقد أنها تؤثر بطبعها وحقيقتها ومنهم من يعتقد أنها لا تؤثر بطبعها ولا بحقيقتها بل لقوة أو خاصية أودعها الله فيها وقد تقدم الكلام عليهما ومنهم من يعتقد أنها لا تؤثر لا بطبعها ولا بقوتها وإنما يعتقد ملازمتها لما قارنها وأنه لا يصح فيها التخلف فهذا الاعتقاد يثول بصاحبه إلى الكفر لأنه يؤدي إلى إنكار معجزة الأنبياء عليهم الصلاة والسلام وإنكار ما أخبروا به من أحوال الموت والقبر والآخرة لأن ذلك كله من باب خرق الموائد الذي تتخلف فيه الأسباب العادية عما يقارنها ومنهم من يعتقد أنها لا تؤثر بطبعها ولا بحقيقتها ولا بقوة أودعت فيها وإنما المولى تبارك وتعالى أجرى العادة أن يخلق عند تلك الأسباب لا بها أو بها عادة فهؤلاء المؤمنون حقا الناجون من مهالك الدنيا والآخرة. ولما فرغ من الكلام على أنواع الشرك الستة وما يلزم منها الكفر ومالا يلزم شرع الآن في الكلام على أصول الكفر والبدع فذكر أنها سبعة فقال (وأصول الكفر) عطف هذه المقدمة على مقدمة الشرك لأن بينها عموما وخصوصا من وجه يشتركان في جلها وينفرد الشرك في السادس وينفرد الشرك في الإيجاب الذاتي وأصول جمع أصل وهو ما يبنى عليه غيره ويقابله الفرع وهو ما ييبنى على غيره، والكفر لغة الستر والتغطية، واصطلاحا عدم الإيمان والتقابل بين الإيمان والكفر"], [33, "الرسالة وقولنا التي لا تنافي علوّ رتبتهم احتراز من اعتقاد اليهود وكثير من جهلة المؤرخين والمفسرين اتصاف الأنبياء عليهم الصلاة والسلام بنقيصة المعصية والمكروه ونحوهما) لاشك أن الناس باعتبار تعظيمهم للرسل عليهم الصلاة والسلام ثلاثة أقسام: مفرط ومفرّط وهما هالكان ومتوسط وهو الناجي بفضل الله تعالى وعن القسمين الأوّلين احترزنا بالقيود التي ذكرناها في تفسير الجائز على الرسل عليهم الصلاة والسلام واحترزنا وهي الصفات الحادثة المتجددة من الصفات القديمة التي هي صفات الإله جل وعلا فلا يصح أن يتصف بها غير مولانا جل وعلا وقد كفرت النصارى بمخالفتهم هذا القيد وإفراطهم في حق عيسى عليه الصلاة والسلام فجعلوا صفة العلم القديم قائمة بجسد عيسى عليه الصلاة والسلام فجعلوه إلها لذلك على خبط شديد وتخليط عظيم لا يفوه به عاقل تعالى الله عن قولهم علوا كبيرا واحترزنا بقيد البشرية كالأكل والشرب والمرض ونحوها من صفات الملائكة عليهم الصلاة والسلام وهي غناهم عن هذه الأمراض التي وضعها الله تعالى في البشر فلا يشترط ذلك في الرسل عليهم الصلاة والسلام لعدم توقف الرسالة عليها وليس غنى الملائكة عليهم الصلاة والسلام عنها لذواتهم بل يجعل الله تعالى لهم ذلك وقد كفرت الجاهلية بمخالفتهم هذا القيد وإفراطهم أيضا بزعمهم أن هذه الصفات البشرية ناقصة لا تليق بمرتبة الرسالة وإنما تليق بها صفات الملائكة فكفروا وكذبوا بسبب ذلك الرسل عليهم الصلاة والسلام وقالوا فيما أخبر الله تعالى عنهم ((أبشر يهدوننا، إن أنتم إلا بشر مثلنا وقالوا مال هذا الرسول يأكل الطعام ويمشي في الأسواق)) ولو انكشف الحجاب عن قلوبهم لعرفوا أن في وقوع هذه الأعراض البشرية بالرسل عليهم الصلاة والسلام كمالات لهم في أنفسهم وتكميلات متكاثرة لأممهم بحيث يغتبطها الملائكة الكرام ويتمنون وجود مثلها لهم لما فيها من الآداب الرقيقة والعبادات الدقيقة التي لم يجدوا مثلها في عبادتهم هذا مع ما فيها من تأنس الأمم ودفع الوحشة عنهم بمخالطة من هو من جنسهم ومتصف بحسب الظاهر بصفاتهم وأمكنهم لأجل الجنسية والمخالطة أن يعرفوا أمانته وصدقه ونصيحته والتلقي منه ولو كان ملكا لتعذر ذلك كله منه قال تعالى ((وَلَوْ جَعَلْنَاهُ مَلَكًا لَّجَعَلْنَاهُ رَجُلاً وَلَلَبَسْنَا عَلَيْهِم مَّا يَلْبِسُون) فعامل سبحانه الخلق بمقتضى الفضل العظيم والرحمة واالطف بأن بعث إليهم رسلا من أنفسهم ظاهرهم بشرى من جنس المبعوث إليهم وباطنهم ملكي بل أعلى ولهذا اتسعت قلوبهم عليهم الصلاة والسلام لمخالطة الفريقين ومراعاة الجانبين وأما قولنا التي لا تنافي\r[المواهب اللدنية]\rتقابل العدم والملكة (و) اصول (البدع) وأطلق عليها أصولا لقوة الكفر والاهتمام به والله أعلم (سبعة) الأول منها (الإيجاب الذاتي) وهو أصل كفر الفلاسفة حيث جعلوا الذات العلية فاعلة بمقتضى الإيجاب (وهو) أي الإيجاب (الذاتي إسناد الكائنات) يعني الممكنات (إلى الله تعالى على سبيل) يعني طريق (التعليل) يعني بأن يكون ذاته العلية علة أي سببا عقليا لوجود شيء من الممكنات أو عدمه من غير إرادتها فيلزم من ذلك الوجوب اقتران العلة بمعلولها كتحريك الخاتم مع تحريك الأصبع من غير قصد المتحرك مثلا (أو) على سبيل أي طريق (الطبع) بأن تكون ذاته العلية مؤثرة في شيء من الممكنات بالطبع (من غير اختيار) يعني من غير إرادة بيان التعليل والطبع والفرق عندهم بين العلة والطبيعة أن العلة لا يتوقف تأثيرها على شيء كحركة الأصبع بالنسبة إلى حركة الخاتم المجعولة علة فيه بخلاف الطبيعة كتأثير النار في الإحراق فانه يتوقف على وجود شرط وهو مماسة النار للشيء المحروق وانتقاء المانع وهو عدم البلل مثلا. فان قلت ما الدليل على استحالة كونه تعالى علة أو طبيعة. فالجواب أنه لو كان كذلك لزم قدم العالم لوجوب اقتران العلة بمعلولها والطبيعة بمطبوعها فان قلت لا نسلم قدم العالم لأن العالم لا يخلو إما أن تقولوا إنه صحيح الوجود في الأزل أولا فان كان الأول لم يكن قدم العالم محالا فنحن نلتزمه وإن كان الثاني لم يلزم من قدم مؤثرة قدمه لأن صدور الأثر عن المؤثر كما يعتبر فيه وجود المؤثر يعتبر فيه إمكان مطلق الأثر ونزيد تقريرا فنقول القادر عندكم هو الذي يصح منه الإيجاد والله قادر في الأزل فاذا لم يلزم من أزلية قدرته صحة الإيجاد أزلا فلم يلزم من وجود المؤثر أزلا وجود العالم في الأزل.\rفالجواب أن وقوع العالم بالقدرة والاختيار في الأزل محال فلم يصح قولكم إن العالم إنما لم يوجد في الأزل لاستحالة وجوده أزلا ولا يكون مانعا عن صدور العالم عن العلة والطبيعة فان قلت ندعي أن صانع العالم طبيعة وإنما يوجد معها لقيام مانع من وجوده أزلا. فالجواب أن المانع إذا كان قديما يستحيل عدمه فلا يوجد العالم بذاته مع أنه موجود هذا خلف. فان قلت تدعى أنه حادث ليصح عليه العدم فالجواب يلزم أن يكون العالم قديما لتجرد الطبيعة في الأزل عن المانع. فان قلت تدعى أن العالم إنما يوجد معها لتوقف وجوده على شرط يوجد في الأزل. فالجواب أن الكلام في حدوث ذلك الشرط وتأخيره عن الأزل كالكلام في العالم فيحتاج هو أيضا"], [34, "علو ّرتبتهم فاحترزنا به من الغفلة عن جانبهم الرفيع والتفريط بسبب مشاهدة ظواهرهم البشرية في مراعاة قدرهم العلي ّ وملاحظة اعتناء المولى بهم ورفع مقامهم الأكمل فوق جميع الخلق وقد ضلت اليهود أدام الله ذلهم فأساءوا الأدب ووصفوا أنبياء الله تعالى ورسله عليهم الصلاة والسلام بمساو لايليق أن يوصف بها من هو أدنى منهم في غاية وربما أدخل بعض جهلة المؤرخين والمفسرين بعض ذلك في كتبهم وافتتنوا بذلك وفتنوا به من يطالعه نسأل الله تعالى العافية من زلات من يقتدى به فانه يضل بسبب زلته وفتنته عالم كثير ولا حول إلا بالله العلي العظيم وربما يفترون بذلك لقلة تحصيلهم وعدم تحقيقهم بظواهر من الكتاب والسنة سنشير إن شاء الله بعد هذا إلى جملة منها ليعرف منها غيرها، ونظير الاغترار بهذه الظواهر اغترار المجسمة القائلين بالجهة وبتأثير مقدرة الحادثة وتحليل الأفعال والأحكام ونحو ذلك بظواهر من الكتاب والسنة توهم ذلك ولم يحيطوا بعلمها لعدم تضلعهم من العقليات والنقليات وفقدهم الأنوار الربانية والعصمة الإلهية ولهذا قيل إن التمسك في معرفة الله ومعرفة الرسل عليهم الصلاة والسلام بمجرد ظواهر الكتاب والسنة أصل من أصول الكفر قلت وكذلك تلقي هذا العلم من مجرد الكتب والمشايخ المصحفين والمنتفقهين بلا تحقيق نسأل الله تعالى السلامة من فتنة المحيا والممات والتأييد بالتوفيق والعصمة من جميع الآفات بجاه أشرف الخلق سيدنا ومولانا محمد صلى الله عليه وسلم ...\rكل ما أوهم في حقهم عليهم الصلاة والسلام وجب بتأويله\r("]], "pg": [30, 34]}, "516.24": {"x": [[34, "وبهذا تعرف أن كل ما أوهم في حقهم أو حق الملائكة نقصا من الكتاب أو السنة وجب تأويله) أشار بهذا الكلام إلى وجوب تأويل ما اغتر ّ به بعض من أجاز على الأنبياء والملائكة على جميعهم الصلاة والسلام الصغائر واحتجوا في ذلك بظواهر كثيرة من القرآن والحديث قال القاضي عياض في الشفاء إن التزموا ظواهرها أفضت بهم إلى تجويز الكبائر وخرق الإجماع وما لا يقول به مسلم فكيف وكل ما احتجوا به مما اختلف المفسرون في معناه وتقابلت الاحتمالات في مقتضاه وجاءت فيها للسلف بخلاف ما التزموه من ذلك فاذا لم يكن مذهبهم إجماعا وكان الخلاف فيما احتجوا به قديما وقامت الأدلة على خطأ قولهم وصحة غيره وجب تركه والمصير إلى ما صح فمن الظواهر الموهمة للنقص والذنب قوله تعالى لنبينا ومولانا محمد صلى الله عليه وسلم ((ليغفر لك الله ما تقدم من ذنبك وما تأخر)) وقوله جل وعلا ((واستغفر لذنبك وللمؤمنين والمؤمنات)) وقوله تعالى ((ووضعنا عنك وزرك الذي أنقض ظهرك)) وقوله ((عفا الله عنك لم َ أذنت لهم)) وقوله ((لَّوْلاَ كِتَابٌ مِّنَ اللّهِ سَبَقَ لَمَسَّكُمْ فِيمَا أَخَذْتُمْ عَذَابٌ عَظِيم)) وقوله\r[المواهب اللدنية]\rإلى مانع أزلي فيلزم أن لا يوجد شرط العالم أبدا فلا يوجد مشروطه أبدا وتقدير شرط آخر حادث فتنقل الكلام إليه فيلزم فيه مالزم في الأول وذلك يؤدي إلى تسلسل شروط لا نهاية لها تعالى من حيث وجبت له القدرة والإرادة عن أن يكون علة أو طبيعة (و) الثاني من أصول الكفر (التحسين العقلي) هو أصل كفر البراهمة من الفلاسفة حيث نفوا النبوة (وهو) أي التحسين العقلي (كون أفعال الله تعالى) كالثواب والعقاب وغيرهما (وأحكامه) كالواجب والمندوب والمحرم والمكروه والمباح وغيرها من خطاب الوضع (موقوفة) أي مرتبطة (عقلا) بأن تكون من باب الأدلة العقلية التي الربط فيها بين الدليل والمدلول عقلي لا يتوقف على جعل جاعل كدلالة حدوث العالم على وجوده تعالى (على الأغراض) يعني البواعث والحاجات والعلل (وهو) أي كون أفعال الله الخ (جلب المصالح) كالعدل والإحسان وغير ذلك (ودرء الفاسد) كالظلم والجور على مفسدة ولا مصلحة فإباحة وبالجملة فافعاله تعالى أن يفعل ما يشاء ويحكم في خلقه بما يريد فلو توقفت أفعاله سبحانه وأحكامه على الأغراض لزم احتياجه تعالى إلى الأفعال ليحصل بها غرضه وذلك ينافي جلاله وعظمته ووجوب غناه جل وعلا عما سواه كيف وهو العظيم السلطان الغني بذاته وصفاته عن كل ما سواه المفتقر إليه كل ما عداه ونشأ عن هذا الأصل الفاسد بدعة المعتزلة في إيجابهم مراعاة الصلاح والأصلح في العباد في حقه تعالى وكون الأحكام الشرعية تابعة لتحسن العقل وتقبيحه وهذه المسئلة هي المعبر عنها بالتحسين والتقبيح والحسن والقبح فليس الحسن شرعا عند أهل الحق إلا ما قال الشرع افعلوه وليس شرعا إلا ما قيل فيه لا تفعلوه وتخصيص كل واحد منهما بما اختص به من الأفعال لا علة له ولا باعث ولا حاجة وما يوجد من التعليل ذلك في كلام أهل الشرع فمؤول بالثمرات ونحوها مما يصح ووجه تسميتهم براهمة كونهم لا يصدقون إلا إبراهيم عليه السلام واستشكله سيدي أحمد المنجور في حواشيه قائلا شبهتهم تقتضي خلاف هذا وأنهم يكذبون جميع الرسل وما قاله واضح ثم قال في التجريد لأبي بكر المرادي البراهمة ينسبون إلى إبراهيم رجل كان من المجوس فيما ذكره المؤرخون فرجع إلى هذا اهـ (والثالث) من أصول الكفر (التقليد الردئ) هو أصل كفر عبدة الأوثان وغيرهم واحترز بالتقليد الردئ من التقليد الحسن كتقليد عامة المؤمنين لعلمائهم في الفروع واختلف في تقليد"], [35, "عزّجل من قائل ((عبس وتولى أن جاءه الأعمى)) ومن ذلك أيضا ما قص من قصص الأنبياء غير سيدنا ومولانا محمد صلى الله عليه وسلم وعليهم أجمعين كقوله تعالى ((وعصى آدم ربه فغوى)) وقوله ((فلما آتاهما صالحا جعلاله شركاء)) الآية وقوله إخبارا عن آدم عليه السلام ((ربنا ظلمنا أنفسنا)) الآية وقوله سبحانه إخبارا عن يونس عليه السلام ((سبحانك إني كنت من الظالمين)) وما ذكر من قصته وقصة داود عليهما السلام وقوله فيه ((فَاسْتَغْفَرَ رَبَّهُ وَخَرَّ رَاكِعًا وَأَنَاب فَغَفَرْنَا لَهُ ذَلِكَ وَإِنَّ لَهُ عِندَنَا لَزُلْفَى وَحُسْنَ مَآب)) وقصة نبينا ومولانا محمد صلى الله عليه وسلم مع زيد ومولاه وزينب وقوله تعالى (وَتُخْفِي فِي نَفْسِكَ مَا اللَّهُ مُبْدِيهِ وَتَخْشَى النَّاسَ وَاللَّهُ أَحَقُّ أَن تَخْشَاهُ)) وقوله تعالى في قصة يوسف عليه الصلاة والسلام ((ولقد همت به وهم بها)) وما قص من قصته مع إخوته وقوله تعالى عن موسى عليه الصلاة والسلام ((فَوَكَزَهُ مُوسَى فَقَضَى عَلَيْهِ قَالَ هَذَا مِنْ عَمَلِ الشَّيْطَانِ)) وقول النبي صلى الله عليه وسلم في دعائه ((اللهم اغفر لي ما قدمت وما أخرت وما أسررت وما أعلنت)) ونحوه وذكر الأنبياء عليهم الصلاة والسلام في الموقف ذنوبهم عند ما تطلب منهم الشفاعة وقوله عليه الصلاة والسلام ((إنه ليغان على قلبي فأستغفر)) الله وفي حديث أبي هريرة ((إني لأستغفر الله وأتوب إليه في اليوم أكثر من سبعين مرة)) وقوله ((وَإِلاَّ تَغْفِرْ لِي وَتَرْحَمْنِي أَكُن مِّنَ الْخَاسِرِين) وقد كان قال له الله تعالى ((وَلاَ تُخَاطِبْنِي فِي الَّذِينَ ظَلَمُوا إِنَّهُم مُّغْرَقُون)) وقال تعالى عن إبراهيم عليه السلام ((وَالَّذِي أَطْمَعُ أَن يَغْفِرَ لِي خَطِيئَتِي يَوْمَ الدِّين)) وقوله تعالى عن موسى عليه السلام ((تبت إليك)) وقوله جل وعلا ((ولقد فتنا سليمان وألقينا على كرسيه جسدا ثم أناب)) وقوله جل وعلا ((فَلَمَّا جَنَّ عَلَيْهِ اللَّيْلُ رَأَى كَوْكَبًا قَالَ هَذَا رَبِّي)) وقوله تعالى ((فأوجس في نفسه خيفة موسى)) وما أشبه ذلك من الظواهر الكثيرة ولنشر إلى شيء مما يتأول به كل واحد من هذه الظواهر باختصار ومن أراد استيفاء ذلك فعليه بالمطولات من كتب التفسير وشروح الأحاديث أما قوله تعالى في سورة الفتح ((لِيَغْفِرَ لَكَ اللَّهُ مَا تَقَدَّمَ مِن ذَنبِكَ وَمَا تَأَخَّرَ)) فأقرب ما يتأول به أن تكون الآية من باب الأخذ بالأطراف للدلالة على الإحاطة كقوله ((قرأت القرآن)) أوله وآخره فتحمل المغفرة في الآية على المغفرة اللغوية وهي الستر وتكون من بمعنى عن والذي يتقدم عن الذنب أسبابه من الشهوة فيه والهواجس والخواطر وحديث النفس والهم والعزم والذي يتأخر عنه آثاره من الران والقساوة والتثاقل عن الخير وغير ذلك من العقوبات الدنيوية والأخروية فأخبر المولى الكريم أنه فتح لنبينا ومولانا محمد صلى الله عليه وسلم من أبواب المواهب الربانية والأنوار اللدنية العرفانية والعصم\r[المواهب اللدنية]\rعامة المؤمنين لعلماء أهل السنة في أصول الدين هل يكفي ذلك أم لا وكثير من المحققين قالوا إن ذلك كاف إذا وقع منهم التصميم على الحق لاسيما في حق من يعسر عليه فهم الأدلة (وهو) أي التقليد الردئ (متابعة الغير) كمتابعة وتقليد الجاهلية آباءهم في الشرك وعبادة الأصنام (لأجل الحمية والتعصب) للأجداد والآباء رتبتهم والتعصب عطف تفسير على الحمية (من غير طلب للحق) بشهادة ((إنا وجدّنا آباءناعلى أمةوإنا آثارهم مقتدون)) ومن غير طلب للحق بيان للحمية والتعصب وكذا تقليد عامة اليهود وعامة النصارى لأحبارهم في إنكارهم نبوة الصادق المصدوق نبينا وومولانا محمد صلى الله عليه وسلم ونحو ذلك من كل تقليد فيه كفر صراح ونشأ عنه بدعة مختلف في كفر صاحبها كتقليد عامة المعتزلة والمرجئة والمجسمة لقدمائهم فيما كانوا به من هذه البدع (و) الرابع من أصول من أصول الكفر (الرابط العادي) هو أصل كفر الطبائعيين ومن تبعهم من جهلة المؤمنين (وهو) أي الربط العادي (إثبات التلازم) أي الربط (بين أمر) وجودي (وأمر) وجودي (وجودا) في الوجود (وعدما) في العدم (على سبيل) أي طريق (التأثير) والاختراع فرأوا ارتباط الشبع بالأكل والري بالماء وستر العورة بلبس الثوب والضوء عند الشمس ونحو ذلك مما لا ينحصر ففهموا من جهلهم أن تلك الأشياء هي المؤثرة فيما ارتبط وجوده معها بطبعها وحقيقتها ومن اعتقادهم الفاسد أيضا قدم الأفلاك العلوية وتأثيرها في العوالم الأرضية ومما ينخرط في هذا السلك كفر الجاهلية المنكرين البعث وأحوال بسبب الاغترار للربط العادي ونشأ عنه بدعة مختلف في كفر صاحبها كبدعة من اعتقد حدوث الأسباب العادية وتأثيرها بجعل الله فيها لذلك ولو شاء لم يؤثر وقد سبق ما في ذلك من الخلاف (و) الخامس من أصول الكفر (الجهل المركب) هو مما ابتلى به كثير (وهو) أي الجهل المركب (أن يجهل الحق) للطابق للواقع (وبجهل جهله به) أي بالحق كاعتقاد الفلاسفة التأثير واعتقادهم قدمها تأثير الآلة بطريق التعليل ونحو ذلك من كفرياتهم وهذه جهالة عظيمة ثم هم جاهلون بهذا الجهل منهم ولهذا سمى جهلا مركبا وحسبوا أنهم على شيء ألا هم الكاذبون ونشأ عنه بدعة أن كانت تلك البدعة هي التي وقع الجهل باعتقادهم كجهل القدرية باعتقادههم لاستقلال الحيوانات بايجادها أفعالها الاختيارية واعتقادهم مراعاة الصلاح والأصلح في حق الله تعالى ونحو ذلك من سائر البدع الاعتقادية. فان قلت لم كان الجهل المركب"], [36, "الكاملة والهمم القدسية العلية ما استأصل به شأفة كل ذنب وستر بسببه المولى الكريم عنه سوابق كل ذنب ولواحقه، ونكتة العدول عن تعريف الذنب بالألف واللام إلى تعريفه بالإضافة إليه عليه الصلاة والسلام وجهان: أحدهما تقرير النعمة عليه بأن هذا الذنب الذي عصم منه هو ذنب له بحسب الإمكان العقلي والقبول البشري والعادي وفي العصمة من ذلك القبول من المنة عليه واللطف العظيم ما لا يخفى.\rالثاني يحتمل أن تكون الإضافة للتنبيه بالخفي على الجلي وبالأدنى على الأعلى أي سترنا عنك الذنب الذي يتوهم وصوله إليك ويعد ذنبا بالنسبة إليك وإن كان حسنة بالنسبة إلى غيرك كالأنس مثلا بالطاعة والقصد بفعلها نيل ما يلائم النفس في الجنان من المشتهيات ونحو ذلك مما هو كثير لائق بمقام أهل الحجاب من الزهاد والمتعبدين وإذا ستر عنه هذا الذنب واستؤصلت سوابقه ولواحقه وإن كان ليس ذنبا حقيقيا بل هو كمال في حق العموم فأحرى سائر الذنوب التي هي ذنوب حقيقة في حق العام والخاص كالزنا وشرب الخمر والغيبة ونحوها وأما قوله تعالى ((واستفغر لذنبك)) فقيل أنه خطاب له والمراد به أمنه ويحتمل أن يكون أمر بذلك على سبيل التعبد المحض زيادة في رفع الدرجات وتذكيرا لنعمة العصمة بطلب دوامها وإشارة إلى أنها محض فضل بلا وجوب ولا استحقاق ونكتة إضافة الذنب إليه هنا ماسبق في آية سورة في آية الفتح وهذا الوجه أقرب والله تعالى أعلم، وأما قوله له تعالى ((ووضعنا عنك وزرك)) ففيه أقوال كثيرة والأظهر أن حمل الوزر على الذنب أن وضعه حينئذ بمعنى الحفظ منه ومن سوابقه ولواحقه حتى لا يحمل مؤنة من مؤنته وإضافة الوزر إليه نكتته أيضا ما سبق وأما قوله تعالى ((عفا الله عنك لم أذنت لهم)) فلا معاتبة فيه بوجه من الوجوه بل فيه تكرمة وتعظيم كما يقال في استفتاح الكلام مع العظماء أصلحك الله وأعزك الله وأما قوله تعالى (لَّوْلاَ كِتَابٌ مِّنَ اللّهِ سَبَقَ لَمَسَّكُمْ فِيمَا أَخَذْتُمْ عَذَابٌ عَظِيم)) فالأظهر أن معناه لولا كتاب من الله سبق باحلال الغنائم لكم وتخصيصكم بهذه الفضيلة دون من قبلكم لكان كذا وكذا ولهذا قال تعالى ((فكلوا مما غنتم حلالا طيبا)) فليس في الآية إلزام ذنب ولا معاتبة بل فيها ذكر ما خص به نبيننا وسيدنا ومولانا محمد صلى الله عليه وسلم وفضل به من دون سائر الأنبياء والرسل على جميعهم الصلاة والسلام فكأنه تعالى قال ما كان هذا ما كان هذا لنبي غيرك كما قال عليه الصلاة والسلام ((أحلت لي النائم ولم تحل لنبي قبلي)) والخطاب في قوله تعالى ((تريدون عرض الدنيا)) إنما هو لمن أراد ذلك من الناس ويجرو عرضه لعرض الدنيا وحده والاستكثار منها وليس المراد به النبي صلى الله عليه وسلم ولا أصحابه\r[المواهب اللدنية]\rأصلا من أصول الكفر والبدع. فالجواب لأجل عدم شعور صاحبه به واعتقاده الصواب والحق في فعله ولو اتفق أن يجيء من يرده إلى الحق في نفس الأمر فيمتنع من ذلك بخلاف الجهل البسيط وهو عدم إدراك أمر من الأمور فان صاحبه يطلب العلم بما جهله وإن جاء من ينبهه ويعلمه فانه يجيب ويقبل. فان قلت ما سبب الجهل المركب. فالجواب وثوق النفس من العقليات بما ليس برهانيا من الأدلة لا سيما عند من تظهر لها الإضافة للحق في بعض أمور ويكون أيضا هذا الجهل المركب في الشرعيات كما يكون في العقليات ويكون من المقلدين كما يكون من الناظرين (و) السادس من أصول الكفر (التمسك) أي الأخذ (في عقائد الإيمان) جمع عقيدة فعلية بمعنى مفعولة أي معقودة من العقد بين العبد وربه (بمجرد) بمطلق (ظواهر الكتاب) أي القرآن العظيم (و) بمجرد ظواهر السنة المحققة عن النبي المرسل (من غير): ملق بظواهر (تفصيل) تبيين ويميز (بين ما يستحيل) يعني يمتنع (ظواهرها) يعني ظواهر عقائد الإيمان (ومنها و) بين (ما يستحيل) أي لا يمنع ظاهرها منها أما كونه أصلا من أصول الكفر والبدعة فلا شك ولا خفاء في ذلك أما الكفر فكأخذ الثنوية القائلين بألوهية النور والظلمة ويعنون بالنور الله وبالظلمة الشيطان من قوله تعالى ((الله نور السموات والأرض)) ولم ينظروا إلى استحالة كون النور إلها لآنه متغير حادث يوجد وينعدم والإله تبارك وتعالى يستحيل عليه التغير ويجب له القدم والبقاء وإذا كان كذلك وجب حمل الآية الكريمة على خلاف ظاهرها كآية ((على العرش استوى، ويد الله فوق أيديهم، كل شيء هالك إلا وجهه، وما فرطت في جنب الله، وتجري بأعيننا، ويخافون ربهم من فوقهم)) ومن السنة قوله صلى الله عليه وسلم ((ينزل ربنا إلى سماء الدنيا إذا كان الثلث الأخير من الليل)) وقوله صلى الله عليه وسلم ((إن قلوب بني آدم بين أصبعين من أصابع الرحمن يقلبها كيف يشاء)) ومشكلات الكتاب والسنة كثيرة جدا ولذا اختلف العلماء في هذه المشكلات على ثلاثة مذاهب: الأول وجوب تفويض معنى ذلك إلى الله تعالى بعد القطع بالتنزيه عن الظاهر المستحيل وهو مذهب السلف وهذا القول هو أحسن الأقوال وأسهلها. الثاني حمل تلك المشكلات على إثبات صفات الله تعالى غير الثمانية تليق بحاله وجلاله وسلطانه لا تعرف كنه ذاته العلية مذهب شيخ أهل السنة أبي الحسن الأشعري رحمه الله تعالى ورضي عنه، والثالث جواز"], [37, "رضي الله تعالى عن جميعهم وأما قوله جل من قائل ((عبس وتولى) الآية فقال عياض في الشفاء ليس فيها إثبات ذنب له عليه الصلاة والسلام بل إعلام من الله تعالى أن ذلك المتصدي له ممكن لا يتزكى وأن الصواب والأولى أن لو كشف لك حال الرجلين لاخترت الإقبال على الأعمى وفعل النبي صلى الله عليه وسلم لما فعل وتصديه لذلك الكافر كان طاعة الله تعالى وتبليغا له كما شرعه الله تعالى له لا معصية ولا مخالفة له وما قصه الله عليه من ذلك إعلام بحال الرجلين وتوهين أمر الكافر عنده والإشارة إلى الإعراض عنه قوله تعالى ((وما عليك أن لا يزكى)) وقيل أراد بعبس وتولى الكافر الذي كان مع النبي صلى الله عليه وسلم قاله أبو ثمامة وأما قوله تعالى ((وعصى آدم ربه فغوى)) فالتحقيق أن المراد بالمعصية والغواية اللغويتان وهما وقوع صورة المخالفة والغواية التي هي ترك المراشد سواء وقعا عمدا أو نسيانا أو تأويلا لا الشرعيتان وهما المخالفة عمدا مع العلم بالتحريم فان المخالفة على هذه الصفة لم تقع من آدم عليه السلام وإنما وقعت منه نسيانا أو بالتأويل وذلك مبسوط في الشفاء وكتب التفسير ويرحم الله الإمام العالم ابن العربي حيث قال يجب تنزيه الأنبياء عليهم الصلاة والسلام عما نسب إليهم الجهال ولكن البارى سبحانه بحكمه النافذ وقضائه السابق أسلم إلى الأكل من الشجرة متعمدا للأكل ناسيا للعهد فقال في تعمده ((وعصى آدم ربه فغوى)) وقال في بيان عذره ((عهدنا إلى آدم من قبل فنسي)) فمتعلق العمد غير متعلق النسيان وجاز للمولى تبارك وتعالى أن يقول في عبده لحقه عصى تثريبا ويعود عليه بفضله فيقول نسي تقريبا ولا يجوز لأحد منا أن يطلق ذلك على آدم أو يذكره إلا في تلاوة القرآن أو قول النبي صلى الله عليه وسلم وأما قوله تعالى ((فَلَمَّا آتَاهُمَا صَالِحاً جَعَلاَ لَهُ شُرَكَاء فِيمَا آتَاهُمَا)) فقال الواحدي في تفسيره إن إبليس أتى حواء في غير صورته التي تعرفه بها فقال لها ما الذي في بطنك فقالت لا أدري فقال إني أخاف أن يكون بهيمة أو كلبا أو خنزيرا فذكرت ذلك لآدم فلم يزالا في من ذلك ثم أتاها وقال إن سألت الله تعالى أن يجعله بشرا سويا مثلك أتسميه عبد الحارث وكان اسم إبليس في الملائكة فلم يزل بها حتى غرها فلما ولدت ولدا بشرا سويا سمته عبد الحارث سمته عبد الحارث برضا آدم عليه السلام وذلك قوله تعالى ((فلما آتاهما صالحا)) أي ولد بشرا سويا ... ((جعلا له شركاء)) يعني إبليس فأوقع الجمع الواحد آتاهما من الولد إذ سمياه عبد الحارث ولا ينبغي أن يكون عبدا إلا الله تعالى ولم تعرف حواء أنه إبليس ولم يكن هذا شركا بالله تعالى لأنهما لم يذهبا إلى أن الحارث ربهما لكنهما قصدا إلى أنه كان سبب نجاته وتم الكلام\r[المواهب اللدنية]\rتعيين التأويل للمشكل بما يصح بدلالة سياق أو بكثرة استعمال العرب اللفظ المشكل فيه فيحمل النور من قوله تعالى ((الله نور السموات والأرض)) على أنه به تعالى ظهرت أنوارها الحسية من شمس وقمر وسراج وأنوارها المعنوية كعلوم الملائكة وعلوم الأنبياء والرسل والأقطاب والأولياء الصالحين والعلماء وأحوالهم السنية التابعة لتلك العلوم والمعارف، فالمعنى أن تلك القلوب والجوارح إنما استنارت بتلك العلوم والأحوال والأعمال بإنارة المولى العظيم لها بذلك لا بحولها وقوتها فهو الله تعالى الذي نورها ومثل هذا المجاز والتشبيه مألوف اليوم في عرف الناس يقولون فيمن توقفت عليه أمور البلد وتصرفات أهلها بطريق السداد والعافية فلان نوّر هذه البلدة أي استنارت وظهر محاسنها والله تعالى أعلم بمراده ويحمل الاستواء على القهر والغلبة وتحمل اليد على القدرة ويحمل الوجه على الذات ويحمل الجنب على الحق وتحمل العين على البصر أو الحفظ أو العلم ويحمل الفوق على البطش والغلبة ويحمل النزول في الحديث على الأمر والسلطنة والرحمة وتحمل الأصابع على تعلق القدرة وهو مذهب إمام الحرمين وجماعة كثيرة من العلماء وهذا القول أعلم أي أحوج للعلم، وأما البدعة الناشئة عن تقليد ظواهر الكتاب والسنة فكثيرة جدا فأخذا الحشوية الجهة في حق الله تعالى من ظواهر قوله تعالى ((على العرش استوى، أأمنتم من في السماء)) ونحو ذلك وقال تعالى ((هو الذي أنزل عليك الكتاب منه آيات محكمات هنّ أم الكتاب وأخر متشابهات فأما الذين في قلوبهم زيغ فيتبعون ما تشابه منه ابتغاء الفتنة وابتغاء تأويله)) اللهم اكتبنا في زمرة أولئك الناجين من كل فتنة دنيا وأخرى يا أرحم الراحمين واغفر لنا ولأولادنا ولوالدينا ولاخواننا ولمشايخنا ولجميع المؤمنين (و) السابع من أصول الكفر (الجهل) يعني عدم العلم (بالقواعد) جمع قاعدة وهي قضية كلية تعرف منها أحكام جزئياتها (العقلية) أي\rالمنسوبة إلى العقل (التي هي العلم) يعني الإدراك (بوجوب الواجبات) كالعلم بأن الواجب العقلي لا يتصور في العقل عدمه قديما كان كواجب الوجود والقدم والبقاء أو حادثا كالتحيز للجرم مثلا أو كون الواحد نصف الاثنين (و) العلم (بجواز الجائزات) كالعلم بأن الجائز العقلي ما يصح في العقل وجوده وعدمه كوجود العالم من العرش إلى الفرش (و) العلم (استحالة المستحيلات) كالعلم بأن المستحيل ما يتصور في العقل وجوده كالشريك والتركيب في ذات الإله وكاجتماع الضدين فلا شك أن الجهل بذلك قد يجر إلى الكفر كفهم بعضهم مذهب"], [38, "عند قوله تعالى ((آتاهما)) ثم ذكر كفار مكة فقال ((فتعالى الله عما يشركون)) اهـ. قلت قال ابن العربي في الأحكام في توهين هذا القول وتزييفه وهذا القول ونحوه مذكور في ضعيف الحديث والترمذي وغيره وفي الإسرائيليات التي ليس لها ثبات ولا يعوّل عليها من له قلب والقول الأشبه بالحق أن المراد بهذا جنس الآدميين وأما قول آدم عليه الصلاة والسلام ((ربنا ظلمنا أنفسنا)) فقول صدر منه على سبيل الاستكانة والتعظيم لجانب أوامر الله تعالى ونواهيه بحيث يحق على العبيد أن لو كان الأمر بأيديهم أن لا تقع منهم مخالفة بوجه من الوجوه لا عمدا ولا نسيانا ولا بانتهاك ولا بتأويل وأشار عليه الصلاة والسلام بذلك إلى أنه لا حجة للعبد على سيده ومولاه ولا يعتذر لنفسه فيما خالف من أمره تعالى ونهيه ولا حق له على المولى العظيم أن يعذره بنسيان أو تأويل بل الحجة للمولى تبارك وتعالى على كل حال وحكمه على عبده بأنه معذور في بعض الأحوال محض فضل منه جل وعلا وله أن يعذب من يشاء ويرحم من يشاء وهو المحمود المنزه عن النقص والظلم على كل حال وأما قصة يونس عليه الصلاة والسلام فليس فيها نص على ذنب وإنما فيها أبق وذهب مغاضبا وهما راجعان إلى قومه أي هرب منهم وذهب مغاضبا لهم لكفرهم ومجانية أهل الكفر وهجران أوطانهم من أكبر الطاعات لو صدرا من غيره إلا أن الله سبحانه نبه نبيه يونس عليه السلام بذلك التأديب أنه ليس كغيره في هذا لأنه من خواص حضرته المبعوث لهداية الخلق من عنده ولا يحصل المقصود من هدايتهم على التمام إلا بصبره على جفائهم ومشاهدة ضلالهم فلا ينصرف هو إذا إلا بالإذن الخاص لا بالإذن العام كغيره فذلك التأديب تعليم وتربيص للمستقبل لا عقوبة عن ذنب كما يعتقده من جهل وباطن ذلك التأديب يدل على الاعتناء العظيم بيونس عليه السلام والتشريف له بتولي المولى العظيم لتربيته وترييضه بلطيف تدبيره ولم يكله في ذلك لنفسه ولا لأحد من عبيده وأما قوله عليه الصلاة والسلام ((لاإله إلا أنت سبحانك إني كنت من الظالمين)) فالجواب عنه ما سبق في قول آدم عليه السلام ((ربنا ظلمنا أنفسنا)) وأما قوله تعالى ((فظن أن لن نقدر عليه)) فمعناه أن لن نضيق عليه فيما فعل من الخروج عن قومه لأنه عليه الصلاة والسلام لم يتعمد في ذلك معصية ولا قصد مخالفة ويدل على ذلك ما أخبر الله تعالى به عنه هما من ظنه أن لا يضيق عليه لأن ذلك مستلزم قطعا لعدم قصده عليه الصلاة والسلام المعصية إذ من قصد معصية خاف تضييق الله تعالى بالعذاب ضرورة وإن كان من أدنى المؤمنين فكيف بأعلاهم وهم رسل الله تبارك وتعالى وأما قصة داود عليه السلام فقال عياض في الشفاء لا يجوز\r[المواهب اللدنية]\rالنصارى بتركيب الإله وكون عيسى عليه السلام جزءا منه من قوله تعالى ((وروح منه)) فجعل من التبعيض ولا شك أن معه جهلين أحدهما بالقواعد إذ لو عرف أن هذا المعنى يستلزم حدوث الإله للزوم مشابهته للحوادث في التغيير والافتقار إلى المخصص بمقدار مخصوص من المقادير المركبة ويستلزم انعدام حقيقة الألوهية بالكلية لأنه كان عيسى عليه السلام حل فيه جزء من الإله وجزء الإله ليس باله فقد انعدم إذا بالكلية والثاني جهلهم باللغة العربية حيث حصروا معنى من في التبعيض ويلزمهم أن يفهموا أيضا التبعيض منها في قوله تعالى (سَخَّرَ لَكُم مَّا فِي السَّمَاوَاتِ وَمَا فِي الأَرْضِ)) كما فهموه من قوله تعالى وروح منه ولو كانوا عارفين باللغة العربية لفهموا أن من في قوله وروح منه ليست للتبعيض وإنما هي لابتداء الغاية أي روح جاء منه تعالى خلقا واختراعا كما أن معناها ذلك في قوله تعالى ((وسخر لكم ما في السموات وما في الأرض جميعا منه)) وإلى هذا أشار بقوله (و) الجهل (باللسان العربي الذي هو علم اللغة و) علم (البيان) ومن الجهل بعلم البيان اعتقاد صدور حوادث من غير المولى تبارك وتعالى كاعتقاد زيادة الإيمان من سماع القرآن أخذا من قوله تعالى ((وإذا تليت عليهم آياته زادتهم إيمانا)) وستر العورة من اللباس أخذا من قوله تعالى ((يابني آدم قد أنزلنا عليكم لباسا يواري سوآتكم)) وإثارة الرياح للسحاب ونشرها أخذا من قوله تعالى ((الله الذي يرسل الرياح فثير سحابا)) ومن خالط علم البيان عرف أن الاسناد في جميع ذلك من باب الاسناد المجازي العقلي وهو إسناد الفعلي أو ما في معناه إلى غير ما هو له في الظاهر عند المتكلم وإذا عرفت أن الجهل بهذه العلوم يوقع صاحبه في كفر أو بدعة تعين على من له قابلية لفهمها أن يجتهد في تحصيلها ومن ليست له قابلية لفهمها وجب عليه أن يتعلم ما هو فرض عيني عليه من علم التوحيد ومن سمع في الكتاب والسنة ما يقضي ظاهره بخلاف ما عرف في علم التوحيد قطع بأن ذلك الظاهر المستحيل غير مراد الله تعالى ولا رسوله صلى الله عليه وسلم وأن ذلك الكلام معنى صحيحا مليحا ويؤمن على سبيل القطع بأن كلام الله تعالى وكلام رسوله صلى الله عليه وسلم حق لا تناقض فيه ولا حيد عن الصواب ولا يغيره بعد ذلك الجهل بالمراد لأن القلب محشو باعتقاد تنزيه المولى تبارك وتعالى ورسله عليهم الصلاة والسلام عند كل نقص وفساد وبالله التوفيق. ولما فرغ من مقدمة أصول الكفر شرع في مقدمات الموجودات فقال"], [39, "أن يلتفت إلى ما سكره فيها الإخباريون من أهل الكتاب الذين بذلوا وغيروا ونقله بعض المفسرين ولم ينص الله تعالى على شيء من ذلك ولا ورد في حديث صحيح، والذي نص الله تعالى عليه قوله (وَظَنَّ دَاوُودُ أَنَّمَا فَتَنَّاهُ فَاسْتَغْفَرَ رَبَّهُ وَخَرَّ رَاكِعًا وَأَنَاب)) وقوله فيه أواب، فمعنى فتناه اختبرناه وأواب قال قتادة مطيع، ثم حكى عن السمرقندى أن ذنبه الذي استغفر منه هو قوله لأحد الخصمين لقد ظلمك فظلمه بقول خصمه وإلى نفي ما أضيف في الأخبار إلى داود عليه السلام من ذلك ذهب أحمد بن نصر وأبو ثمامة وغيرهما من المحققين قال الداودي ليس في قصة داود عليه السلام وأوربا خبر يثبت ولا يظن بنبي محبة قتل مسلم وقيل إن الخصمين اللذين اختصما إليه في نتاج غنم على ظاهر الآية اهـ.\rقلت ولا شك أن في كتب بني اسرائيل في هذه القصة تخليطا لا يليق أن يلتفت إليه وقد قال على ابن أبي طالب رضي الله عنه: من حدث بما قال هؤلاء القصاصون من أمر داود جلدته حدين لما ارتكب من هتك حرمة من رفع الله قدره، وأما استغفاره صلى الله عليه وسلم وبكاؤه وتضرعه فجار على العهود من حال الأنبياء عليهم الصلاة والسلام في إجلالهم المولى الكريم وخوفهم وهيبتهم له على قدر معرفتهم به وأما قصة نبينا ومولانا محمد صلى الله عليه وسلم مع زيد مولاه وزينب رضي الله عنهما فلا يصح فيها إلا ما ذكره مولانا جل وعز في كتابه العزيز من كونه تعالى زوّج لنبينا عليه الصلاة والسلام زينب بعد فراق زيد لها وشرع بذلك إباحة حلائل الأدعياء وأنهن لا يلحقن في التحريم بحلائل أبناء النسب والرضاع فقال جل من قائل ((فَلَمَّا قَضَى زَيْدٌ مِّنْهَا وَطَرًا زَوَّجْنَاكَهَا)) إلى قوله وطرا وقد أوحى الله سبحانه إلى نبينا محمد صلى الله عليه وسلم بما أراده من تزويج زينب له قبل أن يطلقها زيد فلما ألقى في قلب زيد حب فراقها ومنع من التمتع بها لما قرب أو ان حرمة أمومتها لجميع المؤمنين وهيبة قربها من سيد ولد آدم وأشرف خلق الله أجمعين جاء يشكو تعاظمها عليه للنبي صلى الله عليه وسلم وأنه يريد فراقها فامرها عليه الصلاة والسلام بإمساكها وتقوى الله تعالى في شأنها عملا بالظاهر الذي أمر أن يحكم به وأخفى عليه الصلاة والسلام عن زيد وعن غيره ما في نفسه الطاهرة المطهرة من وحي الله تعالى له بأن زيدا يفارقها وهي زوجة له بعده حياء منه عليه الصلاة والسلام أن يظهر ذلك وزينب بعد في عصمة زيد ولأن ذلك أيضا من العلم الذي لم يؤمر بإظهاره للناس في ذلك الوقت فلما فارقها زيد رضي الله عنه وزوّجها المولى تبارك وتعالى منه عليه الصلاة والسلام قبل وانقاد ودخل إذن ولا مؤامرة مبالغة منه عليه الصلاة\r[المواهب اللدنية]\r(والموجودات) الألف واللام فيها للاستغراق يعني سواء كانت قديمة أو حادثة وأنى بمقدمة الموجودات أثر أصول الكفر شبه البرهان بعد الدعوة لأنه لما ختم الأصول بالجهل بالقواعد العقلية وهو متضمن لمذهب النصارى في جعلهم الإله صفة تعالى الله عن قول الكفرة أتى بالموجودات ردا عليهم والله أعلم، والموجودات (بالنسبة إلى المحل) مراده بالمحل الذات التي تقوم بها الصفات لا المكان الذي تجاوره الأجسام (و) إلى (المخصص) بكسر الصاد ومعناه الفاعل المختار الذي يخصص الممكن بجائز أراده دون جائز لم يرده (أربعة أقسام) وأما بالنسبة إلى القدم والحدوث فقسمان وذلك لأن الموجود إما قديم وهو الله تبارك وتعالى وصفاته الوجودية وإما حادث وهو ذوات الكائنات وصفتها (قسم غني عن المحل) وهو الذات (و) غنى عن (المخصص) وهو الفاعل ومعنى استغنائه عن المحل أن يكون في نفسه ذاتا موصوفة بصفات لاصفة ومعنى استغنائه عن المخصص أن لا يفتقر إلى فاعل مرجح لوجوب قدمه وبقائه تبارك وتعالى إذ لا مرجح سواه (وهو) أي القسم الغني عن المحل والمخصص (ذات الله تعالى) وأصل ذات ذوو فحذفت العين لكراهة الواوين ثم قلبت اللام ألفا وألحقت بها التاء المجاورة والله أعلم والدليل على استغنائه تعالى عن المحل أنه لو احتاج إليه لكان صفة ضرورة أنه لا يفتقر إلى المحل سوى الصفات لكن كونه تعالى صفة محال لأنه لو كان صفة لما صح اتصافه بالمعاني ويلزم منه عدم اتصافه بالصفات المعنوية لأن الصفة لا تقوم بها الصفة إذ لو قبلت أن تقوم لزم أن لا تعري صفة عما تقبله من الصفات كالذات إذ القبول نفسي لا يتخلف وذلك يستلزم دخول مالا نهاية له في الوجود لأن الصفة القائم بها هي القابلة للاتصاف بالصفات، ثم تنقل الكلام إلى تلك الصفات القائمة بها فيلزم مالزم فيما قبلها وهلم جرا ودخول ما لا نهاية له في الوجود محال فاتصاف الصفة بالصفة محال والإله يجب اتصافه بالصفات فثبت أنه ذات لاصفة قطعا على استغنائه عن المخصص أن الاحتياج إلى المخصص يستلزم الحدوث لأن أثر المخصص لا يكون إلا حادثا لكن حدوثه محال بوجوب القدم والبقاء فاحتياجه إلى مخصص محال فيجب استغناؤه عنه وهو المطلوب (وقسم مفتقر) يعني محتاج (إلى المحل) وهو الذات ومعنى افتقار الشيء إلى المحل ووجوده فيه اتصاف ذلك المحل به (و) مفتقر إلى (المخصص) وهو الفاعل المختار ومعنى افتقار الشيء إلى المخصص أن يكون حادثا إلى فاعل يخصصه بالوجود بدلا من العدم الذي كان"], [40, "والسلام في إظهار الرضا بعطية المولى تبارك وتعالى وأنساه حينئذ التعظيم لجانب المولى تبارك وتعالى والحياء منه الالتفات إلى مقالة الناس والحياء من زيد وغيره واتصف في ذلك بما وصف الله تعالى به إخوانه من المرسلين عليه الصلاة والسلام في قوله جل وعلا ... ((الَّذِينَ يُبَلِّغُونَ رِسَالاَتِ اللَّهِ وَيَخْشَوْنَهُ وَلاَ يَخْشَوْنَ أَحَدًا إِلاَّ اللَّهَ وَكَفَى بِاللَّهِ حَسِيبًا)) وحينئذ باح عليه الصلاة والسلام بما أوحى الله تعالى إليه في شأن زيد وزينب ولم يخش أحدا من الخلق ومن هذا التقرير تفهم معنى قوله تعالى ((وَإِذْ تَقُولُ لِلَّذِي أَنْعَمَ اللَّهُ عَلَيْهِ وَأَنْعَمْتَ عَلَيْهِ أَمْسِكْ عَلَيْكَ زَوْجَكَ وَاتَّقِ اللَّهَ وَتُخْفِي فِي نَفْسِكَ مَا اللَّهُ مُبْدِيهِ وَتَخْشَى النَّاسَ وَاللَّهُ أَحَقُّ أَن تَخْشَاهُ)) أي وتخفي في نفسك ما أوحى الله إليك به من مفارقة زيد لها وتزويجك إياها بعده وهذا هو الذي أبداه الله أي أظهره بعد ذلك وليس معنى الآية ما يعتقده بعض الجهلة أن الذي أخفاه النبي صلى الله عليه وسلم في نفسه هو الشغف بحب زينب وحب فراق زيد لها ليتزوجها بعده ومع ذلك أمره بإمساكها حياء منه وخشية من مقالة الناس وهذا الفهم الركيك لا يرضى به عاقل ولا يرتكبه إلا غبي سيء الخلق والأدب سخيف العقل جاهل ويكذب فهمه من الآية نفسها أن الله سبحانه وتعالى أخبره أنه يبدي ما أخفاه النبي صلى الله عليه وسلم في نفسه ولم يبد سبحانه بعد ذلك إلا مفارقة زيد لزينب وتزويجها بعده من النبي صلى الله عليه وسلم لئلا يكون للناس حرج في أزواج أدعيائهم ولم يبد سبحانه أن النبي صلى الله عليه وسلم كان قد شغف بحب زينب وأنه كان يحب فراق زيد لها ليتزوجها بعده فهذه الآية بنفسها تكذب هذا الفهم السيء نعوذ بالله تعالى منه وكيف يشغف أشرف الخلق بحب شيء من متعة الدنيا لا سيما بعد أن حصلت في حوز غيره ومولانا جل وعز يقول له ((ولا تمدن عينيك إلى ما متعنا به أزواجا منهم)) وقال تعالى ((ولقد آتيناك إلى قوله أزواجا منهم)) وقال عليه الصلاة والسلام ((لو كنت متخذا من الناس خليلا لاتخذت أبا بكر خليلا ولكن صاحبكم خليل الرحمن)) وقال عليه الصلاة والسلام ((مالي والدنيا)) الحديث وقال ((الدنيا جيفة قذرة)) وأما قوله تعالى ((وتخشى الناس والله أحق أن تخشاه)) فليس فيه عتب عليه كما يعتقده من لا خلاق له ولا أدب ولا فهم ولا دين وإنما هو مدح له عليه الصلاة والسلام بالخلق الجميل والطبع الكامل وهي الخشية من الناس أي الحياء منهم أن يقابلهم بما يسوءهم قم أمره سبحانه أن يرجح خشيته والحياء منه عند ورود أمره على الحياء من الناس وهكذا كان عليه الصلاة والسلام في هذه القضية وغيرها لا يبالي بشيء إذا حضره حق الله تعالى وأما قصة يوسف عليه السلام وإخوته فليس فيها على يوسف عليه السلام\r[المواهب اللدنية]\rعليه (وهو) أي القسم المفتقر إلى المحل والمخصص (الأعراض) أي الصفات القائمة بالأجرام من ألوان وطعوم وروائح وحركات وسكنات وغيرها وما ذكره من افتقار هذا القسم وهو الأعراض إلى المحل والمخصص ظاهر لأنها لما كانت صفات استحال أن تقوم بنفسها بل لا يمكن أن تكون موجودة إلا في محل أي ذات تقوم بها ولما كانت حادثة وجب افتقارها إلى المخصص أي الموجد لها (وقسم مفتقر) أي محتاج (إلى المخصص) أي الفاعل المختار ومعنى افتقار الشيء إلى المخصص أن يكون حادثا محتاجا إلى فاعل يخصصه بالوجود بدلا من العدم الذي كان عليه (دون المحل) أي الذات (وهو) أي القسم المفتقر إلى المخصص دون المحل (الأجرام) جمع جرم وهو الشاغل للفراغ بحيث يسكن فيه أو يتحرك وكذا حكم الجوهر الفرد إلا أنه أخص من الجرم فكل جوهر جرم وليس كل جرم جوهرا فيشتركان في الجرمية وبنفرد الجرم بالبسائط وما ذكره من افتقار هذا القسم وهو الأجرام إلى المخصص دون المحل فلأنها لما كانت حادثة بدليل لزومها الأعراض الحادثة من حركة وسكون وغيرهما لزم افتقارهما إلى مخصص موجد لها ابتغاء وممد ّ سبق لها بموالاة خلق أعراضها وأما افتقارها إلى مولانا تبارك وتعالى فلا يمكن أن تعرى منه ابتداء ولا دواما وأما وجوب غناها عن المحل فلأنها ليست صفات بل هي ذوات موصوفة بالصفات فلو قام جرم منها بجرم آخر أن يتحد حيزهما وذلك يستلزم أن يكون الجرمان جرما واحدا وذلك لا يعقل (وقسم موجود) يعني ثابت (وفي المحل) يعني في الذات العلية قائم عتب بها قيام الصفة بالموصوف (ولا يفتقر) يعني لا يحتاج (إلى المخصص) يعني إلى الفاعل المرجح المختار (وهو) أي القسم الموجود في المحل ولا يفتقر إلى المخصص (صفات الله تعالى) جمع صفة وهي المعنى القائم وما ذكره في هذا القسم الرابع وهو صفات الله تعالى من وجوب قيامه بذاته العلية ووجوب غناها عن المخصص فلأن كونها صفات يوجب استحالة قيامها بأنفسها لما يلزم عليه من قلب الحقائق إذ حقيقة الصفة يستلزم موصوفا يتصف بها فلو قامت بنفسها لم تكن صفة لكن مفارقة الصفة لحقيقتها التي هي الصفة للموصوف محال فقيامها إذا بنفسها الذي استلزم مفارقتها لحقيقة نفسها محال. فان قلت لماذا لم يطلق المصنف رحمه الله تعالى لفظ الافتقار على الصفة للذات العلية. فالجواب إنما لم يطلق لفظ الافتقار لما فيه من إبهام معنى لا يليق وقد أطلق الإمام الفخر"], [41, "عتب وأما إخوته فقال القاضي عياض رحمه الله تعالى لم تثبت ثبوتهم حتى يلزم الكلام على أفعالهم وذكر الأسباط وعدّهم في القرآن عند ذكر الأنبياء قال بعض المفسرين يريد من تنبأ من أنباء الأسباط وقد قيل إنهم حين فعلوا بيوسف ما فعلوا كانوا صغار الأسنان ولهذا لم يميزوا بيوسف عليه السلام حين رأوه ولهذا قالوا أرسله معنا غدا يرتع ويلعب وإن ثبتت لهم نبوة فبعد هذا وأما قوله تعالى ولقد همت به وهم ّ بها لولا أن رأى برهان ربه فالأقرب أن الوقف على قوله تعالى ولقد همت به ويستأنف قوله تعالى وهم ّ بها لولا أن رأى برهان ربه على التقديم والتأخير أي لولا أن رأى برهان ربه لهمّ بها وقد علم أن لولا تقتضي امتناع جوابها لوجود شرطها فيكون هم ّ يوسف عليه الصلاة والسلام بها منتفيا لرؤيته برهان ربه ويدل على حفظه عليه الصلاة والسلام من كل سوء هما كان أو غيره قوله تعالى كذلك انصرف عنه السوء والفحشاء إنه من عبادنا المخلصين وقال تعالى ولقد راودته عن نفسه فاستعصم وقال جل من قائل وغلقت الأبواب وقالت هيت لك قال معاذ الله إنه ربي أحسن مثواي إنه لا يفلح الظالمون قيل في ربي إنه الله وقد قيل إن معنى هم ّ بها أي بزجرها ووعظها وقيل بضربها ودفعها وقيل بها أي غمها امتناعه عنها ويحتمل أن يكون المراد هم ّ بسببها أي أصابه هم بسبب هذه المحنة التي وقعت فيها من معصية المولى تبارك وتعالى وما كابدته من المشاق ّ والشغف بحبه عليه الصلاة والسلام على سبيل الرحمة لها أن لا تكون وقعت في شيء من ذلك من أجله لكنه عليه الصلاة والسلام لما رأى ببصيرته برهان المولى العظيم وعدله تبارك وتعالى في جميع أفعاله وأحكامه سلم ورضى وزال فيها فيكون المعنى على هذا لولا أن رأى برهان ربه لدام همه أو يكون المعنى لولا أن رأى برهان ربه لسعى فيما يخلصها من هذه المحنة ويسكن عليها بعض لوعة الاشتياق إليه ولو بوعد منه لها في المساعدة على ما أحبت منه أو نحو ذلك.\rمما يترخص به في الظاهر على سبيل التورية لضرورة الدفع عن نفسه وعنها لكن منعه من الالتفات إلى شيء من ذلك رؤيته عليه الصلاة والسلام لبرهان ربه الدال على كمال ملكيته للعبيد وأنه المنفرد بالتدبير والحكم ونفوذ المشيئة والاقتدار ولا معارض له في حكمه فلا يليق بالعبد الفقير المضطر العاجز الجاهل إلا السمع والطاعة والانقياد لأمره ونهيه والرضا والتسليم ظاهر\r[المواهب اللدنية]\rذلك. ولما فرغ من ّمقدمات شرع في مقدمات الممكنات فقال (والممكنات) مراده بالممكنات الجائزات وهي ما يصح في العقل وجوده وعدمه (المتقابلات) أي المتنافرات التي يقبل الجرم كل واحد منها قبولا مساويا لقبول منافره (سنة) يؤخذ من عده الممكنات أنها محصورة فيما ذكر مع أن المعرفة والنكرة والمبتدأ والخبر والفاعل والمفعول ونحو ذلك داخلة في الممكنات. ويجلب عنهم والله أعلم بأنها داخلة في الصفات وعطف هذه المقدمة على الموجودات لما بينهما من الاشتراك فيشتركان في الأجرام وأعراضها وينفرد الموجودات بذات الحق سبحانه وينفرد الممكنات بالجائز المعدوم. ولما ذكر أن الممكنات ستة أشار إلى تفصيلها فقال (الوجود والعدم) هما بالنسبة إلى العالم سواء وإليه ذهب كثير من المحققين وذهب آخرون إلى أن العدم به أولى لأصالته فيه وعدم افتقاره إلى سبب وأيا ما كان فالترجيح بلا مرجح محال لأنه إذا استحال ترجيح أحد المتساويين على الآخر فاستحالة ترجيح المرجوح أحرى وأولى. فان قلت لم قدم الوجود على غيره فالجواب لأن الوجود هو الأصل لأن باعتبار الوجود تبين ما عداه ثم عطف عليهما مما يقابله الأول فالأول باعتبار ما يظهر ابتداء والله أعلم فاذا تبين هذا وتعين لك إذا على سبيل القطع واليقين الضروري بعد هذا التأمل افتقار كل جرم إلى مخصص فاعل يخصصه بالوجود أو العدم على ما سبق (والمقادير) أي ويخصصه أيضا بالمقدار المخصوص في الطول والقصر والتوسط بينهما بدلا عن سائر المقادير التي يقبل الجرم جميعها على السواء (والصفات) أي ويخصصه أيضا بصفة معينة من حركة أو ضدها أو بياض أو ضده أو علم أو ضده إلى غير ذلك من سائر الصفات ونحوها (والأزمنة) أي ويخصصه أيضا بالوجود في زمن معين بدلا عن مقابله من زمن متقدم أو متأخر (والأمكنة) أي ويخصصه أيضا بمكان مخصوص بدلا عن سائر ما يقابله من الأمكنة (والجهات) أي ويخصصه أيضا بجهة مخصوصة من يمين أو شمال أو مغرب أو مشرق بدلا عن مقابله من سائر الجهات وبهذا يتضح لك أن العالم من عرشه إلى فرشه حادث مفتقر إلى الله تعالى افتقارا ضروريا لازما يشهد بوجوب حدوثه ووجوب افتقاره إلى الله تعالى اختصاصه بالوجود بدلا عن العدم الذي يقابله ومقداره المخصوص ووصفه المخصوص وزمنه المخصوص وجهته المخصوصة وكذلك مكان أجرامه المخصوصة فكل جرم من أجرام العالم ينادي نظيره بلسان الحال الذي هو أفصح وأصدق من لسان المقال كل ما وقع عليه بصرك أو جال فيه فكرك من أحوالي ليس مقابله بأولى من العدم منه ولولا الفاعل المخصص لوجوده فيما شاء من الأزمان على ما شاء من المقادير والصفات لكان يجب أن يبقى على ما كان عليه من العدم"], [42, "وباطنا لقضائه وقدره من غير ترخص ولا تأويل ولا شفقة ونفس غيره كما قال تعالى ولا تأخذكم بهما رأفة في دين الله إن كنتم تؤمنون بالله واليوم الآخر وقال جل من قائل إن يكن غنيا أو فقيرا فالله أولى بهما فعلى العبد أن يمضي في طاعة مولاه أصم أبكم أعمى عن كل ماسوى طاعته تبارك وتعالى وهذا هو الذي فعل الصدّيق عليه الصلاة والسلام في هذه القضية ومضى مسرعا في طاعة المولى تبارك وتعالى في ظاهره وباطنه مسلما لحكمه غير ملتفت لملك زليخا له ولا لشغفها بحبه ولا لجمالها الفائق ومنظرها ولا لوعدها إن ساعدها على ما تحب ولا لوعيدها في ابايته عنها واستسهل في طلب رضا المولى تبارك وتعالى المنفرد بالحكم والملك كل صعب ولم يبال بعداوة جميع العوالم له وغضبهم عليه إذا فاز برضا المولى الكريم عنهم تبارك وتعالى كما قال بعض الموفقين رضي الله عنهم في مثل هذا:\rفليتك تحلو والحياة مريرة وليتك ترضى والأنام غضاب\rفياليت ما بيني وبينك عامر وبيني وبين العالمين خراب\rفان صح منك الود فالكل هين وكل الذي فوق التراب تراب\rوكل هذا إنما حصل الصديق عليه الصلاة والسلام بتوفيق المولى تبارك وتعالى وعصمته كما قال جل من قائل كذلك لنصرف عنه السوء والفحشاء إنه من عبادنا المخلصين. وأما خبر موسى عليه السلام مع قتيله الذي وكزه فقط نص الله تعالى على أن القتيل من عدوه وإنما قصد عليه السلام إغاثة الملهوف الإسرائيلي فوكز العدو ّ القاهر له بنية دفعه عمن استولى عليه فصادف موته من غير عمد وقوله عليه السلام هذا من عمل الشيطان حسن أدب منه في نسبة الفعل المحبوب للشيطان إليه ولم يحبه الشيطان هنا لايقاعه الكليم بل معصية لأنه معصوم منها بل لتوهم الشيطان ذلك توهما أخطأ فيه وخاب فيه ظنه وقوله عليه السلام ظلمت نفسي فاغفر لي جرى على المألوف من خوف الأنبياء والرسل عليهم الصلاة والسلام من الله تعالى خوف هيبة وتعظيم وإن علموا عدم المؤاخذة من المولى تبارك وتعالى ولهذا اعتذروا في الموقف، علموا عدم المؤاخذة به وعلى هذا يحمل استغفار الأنبياء عليهم الصلاة والسلام وخوفهم وأما قوله تعالى ولقد فتنا سليمان فمعناه ابتليناه شق إنسان حين نسي أن يقول\r[المواهب اللدنية]\rأبد الآباد. فان قلت هل العالم في مكان أو في جهة فالجواب العالم في جهة كالطير في الهواء لا في مكان لاستلوامه التسلسل وذلك لأن المكان هو استقرار جوهر على آخر فلو استقر العالم في مكان لزم أن يكون ذلك المكان مستقرا على مكان آخر وهلم جرا إلى مالا نهاية له ويلزم التسلسل وهو محال فاعرفه فانه نفيس قل ّ من ينبه عليه. ولما فرغ من مقدمات الممكنات شرع في ذكر مقدمة الصفات الأزلية وهو المقصود الأهم وحاصلها أنها تنقسم إلى سبعة أقسام: وهي التي لا يعقل الموصوف بدونها كالوجود وسلبية وهي سلب أمر لا يليق أن يتصف به سبحانه وتعالى وهي خمس صفات القدم وهو سلب العدم السابق عن الوجود والبقاء وهو سلب العدم اللاحق للوجود والمخالفة وهي سلب الجرمية والعرضية ولوازمها والقيام بالنفس وهو سلب الافتقار إلى المحل والمخصص والوحدانية وهي سلب الاثنينية في الذات والصفات والأفعال، ومعاني وهي كل صفة موجودة في نفسها أوجبت له حكما سواء كانت قديمة كالقدرة والإرادة أو حادثة كبياض الجرم وسواده وهي سبع صفات القدرة والإرادة والعلم والحياة والسمع والبصر والكلام. ومعنوية وهي كل صفة ثبوتية لا توصف بالوجود كالمعاني ولا بالعدم كالسلبية ملازمة للسبع الأول وهي كونه تعالى قادرا ومريدا وعالما وحيا وسميعا وبصيرا ومتكلما، وفعلية وهي عبارة عن اتساق التنجيزي للقدرة والإرادة كخلقه ورزقه وهي على قسمين فعلية وجودية كما مثل وسلبية كعفوه عمن شاء فانه عبارة عن ترك العقوبة وهذا بناء على أن الترك سلب فعل يكون من الثاني وعلى أنه فعل يكون من الأول وجامعة لسائر الصفات كالجلال والكبرياء والعظمة والألوهية وسمعية وهي عبارة عن معاني ورد السمع بها والمعنى به الكتاب والسنة المتواترة وكذا خبر الآحاد بشرط إعطاء الدليل العقلي كالاستواء واليد والعين والوجه والجنب والأصبع والتنزه والفوق وقد تقدم الكلام عليها مستوفي فانظره إن شئت والحمد لله وإنما تعرض في هذه المقدمة لبيان قسم واحد وهو صفات المعاني اعتناء بثبوتها واشار إلى وجوب وجودها ردا على المعتزلة الذين قالوا بنفيها فقال (والقدرة الأزلية) قدم القدرة على غيرها بل هي متوقفة على الإرادة لأن لها مدخلا تاما في التأثير فكانها بمنزلة الذات ولهذا وصفت بأنها مؤثرة على سبيل المجاز وذكم الإرادة بأثرها لأنها كالوصف لها من حيث تخصيص أحد المقدورين وإن كان تأثير القدرة متوقفا على تأثير الإرادة ولتوقف تأثيرها أيضا على العلم، وذكر العلم أثر الإرادة تأثيرها على العلم إذا القصد إلى إيجاد شيء مع الجهل محال، وذكر الحياة بعد هذه الصفات لكونها شرطا فيها لتوقف الفعل عليها وفي الثلاث صفات."], [43, "إن شاء الله بعد قوله لأطوفن الليلة على مائة امرأة أو تسع وتسعين كلهن يأتين بفارس يجاهد في سبيل الله وليس ذلك عقوبة بل تنبيها من المولى تبارك وتعالى لخاصته على كمال التحرز في المستقبل وسرفهم جل وعلا بأن تولى رياضتهم بنفسه ولم يكلهم إلى غيره من الأسباب العادية وألقى ذلك الشق على كرسيه لكمال الاعتبار والاعتناء برؤية ما نبهه به المولى العظيم عيانا، وإياك يا أخي أن تصغي بأذنك لما يذكره هنا جهلة المؤرخين والمفسرين من العظائم التي لا يرضى أن يلتفت إليها المؤمن.\rواما قوله جل وعلا في حق إبراهيم عليه السلام فلما جن عليه الليل رأى كوكبا قال هذا ربي الخ فهو إقامة منه عليه الصلاة والسلام الدلالة لقومه على حدوث هذه العلويات التي عبدها قومه وادعوا لها الألوهية ولذلك قال جل من قائل وتلك حجتنا آتيناها إبراهيم على قومه الآية لا أنه عليه الصلاة والسلام كان يعتقد ربوبيتها أو يشك فيها وعند إقامة هذا الدليل زال عنه ذلك الاعتقاد أو الشك كما توهمه كثير ممن لا خلاق له ممن يدّعي التصوف وغيره لأن الأنبياء عليهم الصلاة والسلام معصومون من الكفر قبل النبوّة وبعدها في صغرهم وكبرهم بل هم معصومون من جميع المعاصي صغيرها وكبيرها عموما على ما سبق تحقيقه فمعنى قوله عليه الصلاة والسلام هذا ربي أهذا ربي على ما تزعمون بحذف حرف الاستفهام أو من باب ذكر دعوى الخصم لإقامة البرهان على إبطالها وطلوع هذه الكواكب بعد أن لم تكن هو في الاستدلال به على حدوثها كالأفول إلا أنه عليه الصلاة والسلام إنما أخر الاستدلال على حدوثها إلى رؤية أفولها لما في الأفول من التغير بالنقصان فدلالته على حدوث تلك الكواكب وعدم صلاحيتها للربوبية واضح للذكي والغبي أما طلوعها وإن كان دليلا على حدوثها من ناحية تجدده بعد أن لم يكن فلأنه لما كان فيه كمال لها لما صاحبه من تلك الأنوار التي توجب لذة النفس والامتداد إليها بالأبصار فقد يسكن عقل الغبي الشهواني المقلد أو المعاند فلا يتأمل في وجه دلالته على الحدوث ولا يصغي لسماعها وأما قوله تعالى في حق موسى عليه السلام مع السحرة فأوجس في نفسه خيفة موسى فخوفه عليه الصلاة والسلام إنما كان لأجل الله وغيرة على توحيده خاف أن لا تتضح للحاضرين دلالة معجزته مع خارقهم وقد قيل إن سبب خوفه عليه الصلاة والسلاة أنه سمع جبريل عليه السلام يقول للسحرة عند إلقائهم حبالهم وعصيهم ألقوا ياأولياء الله فخاف من\r[المواهب اللدنية]\rولما كان الحي لا يخلو عن السمع والبصر والكلام بعد الحياة وقدم السمع والبصر على الكلام لكثرة الكلام مع المعتزلة في صفة الكلام حتى قيل سمى علم الكلام لكثرة الكلام فيه بين أهل السنة رضي الله عنهم والمعتزلة وقدّم السمع على البصر لتقديمه في القرآن والسنة قال الله العظيم إنني معكما أسمع وأرى وهو السميع والبصير وقال تعالى لم تعبد مالا يسمع ولا يبصر وقال صلى الله عليه وسلم إنما تدعون سميعا بصيرا متكلما وهذا من منح العلم وترتيب حسن والله أعلم.\rفان قلت ما المراد بالتوقف المذكور فالجواب هو توقف معية وهو فهم الشيئين بالآخر لا توقف تقدم لاستلزم الثاني الحدوث لهذه الصفات وحدوثها يستلزم حدوث موصوفها {تنبيه} تعاريف المصنف رحمه الله تعالى لهذه الصفات الأزلية هي رسوم وليست بحدود حقيقية فلو كانت حدودا حقيقية لزم منه معرفة كنه الإله وذلك محال إذ لا يعرف الله إلا الله وإطلاق الحقيقة عليها مجاز فاعرفه فانه نفيس وخرج بقوله الأزلية القدرة الحادثة فلا يقال فيما تتعلى به تأثير وإنما يقال فيه كسب بخلاف القدرة الأزلية وهي (عبارة عن صفة) كالجنس في التعريف شامل لجميع الصفات المتعلقة كالمعاني (يتأنى بها) أي يتيسر بالقدرة فصل يخرج سائر الصفات ما عدا الإرادة لأن الإرادة يتأنى بها وإنما قال بها ولم يقل لها لأن نسبة التأثير إلى القدرة مجاز والذات حقيقية ومن أسنده إلى القدرة حقيقة فقد أشرك مع الله والإشراك كفر فاعرفه (إيجاد) فصل ثان يخرج به الإرادة لأن تعلقها تخصيص لا إيجاد ويبقى الحد لحدود والإيجاد إخراج الممكن من العدم إلى الوجود ... (كل ممكن) كليا كان أو جزئيا جوهرا كان أو جسما أو عرضا تعلق علم الله بعدم وقوعه كإيمان أبوي جهل ولهب أو بوقوعه كوجود العالم ويتناول أفعالنا الأختيارية كحركاتنا وسكناتنا وبتناول ما لا سبب كوجود الإحراق عند النار والشبع عند الأكل وما لا سبب له كخلق السموات والأرض (وإعدامه) أي إعدام الممكن، والإعدام أن يصير الشيء لا شيء كما كان أولا وهذا القيد إنما يتأتى على مذهب الجمهور والذين يروون أن إعدام الجوهر إنما هو بقدرته تعالى وهو المختار أما على مذهب إمام الحرمين الذي يرى إن اعدامها بكف الأعراض عنها فلا إلا إذا بنينا على أبعد قول الأصوليين أن الكف فعل فحينئذ ينطبق الحد عليها وأما عدم الأعراض فهذا الحد أيضا إنما يتأنى على مذهب القاضي والرازي وأما على مذهب إمام الحرمين الذي يرى استحالة بقاء الأعراض وإنما هي بنفس وجودها تنعدم فعدمها واجب والواجب ليس بممكن فلا تتعلق به القدرة (على وفق الإرادة) يعني أن الله تعالى لا يخلق ويوجد بقدرته إلا ما أراده"], [44, "قوله لهم يا أولياء الله أن يكون ذلك علامة لظهور خارقهم للحاضرين فيتمادوا على الضلالة والله تعالى أعلم وبالله تعالى التوفيق وقس على هذا كل ما يرد عليك من الظواهر ويمثل هذه التأويلات يجب أن يتأول ما يوهم ظاهره نقصا في حق الملائكة عليهم الصلاة والسلام كقصة هاروت وماروت وجعلهما ملكين يعلمان الناس السحر ويزيد فيها كذبة المؤرخين من أنهما عوقبا ومسخا وذلك كله كذب وزور لا يحل اعتقاده ولا سماعه بل الذي يجب اعتقاده في حق جميع الملائكة ما وصفهم به المولى العظيم تبارك وتعالى بأنهم عباد مكرومون لا يعصون الله ما أمرهم ويفعلون ما يؤمرون وأنهم لا يستكبرون عن عبادته ولا يستحسرون يسبحون الليل والنهار لا يفترون وإنما الذي يجب اعتقاده في قصة هاروت وماروت أنهما إن لم يكونا ملكين فواضح وإن كانا من الملائكة فتعليمهما السحر لم يكن لأجل العمل به بل للتحرز منه بتعريف حقيقته وبيان شره وعقوبته ولهذا أخبرا الله عنهما أنهما قالا إنما نحن فتنة فلا تكفر وهذا كتعليم حقيقة الزنا وأنواع الربا والمحرمات ليتحرز المكلف منها لأن التحرز من الشر موقوف على معرفته زلهذا قال حذيفة رضي الله عنه كان الناس يسألون النبي صلى الله عليه وسلم عن الخير وكنت أسأله عن الشر مخافة أن أقع فيه وأما قول الملائكة عليهم الصلاة والسلام خطابا لمولانا جل وعلا حين أخبر أنه جاعل في الأرض خليفة أتجعل فيها من يفسد فيها ويسفك الدماء ونحن نسبح بحمدك ونقدس لك فهو استفهام لمجرد الاستعلام لا للأنكار والاعتراض الوجبين لكفر من صدر منه ولهذا أتوا عليهم الصلاة والسلام بجملتي ونحن نسبح بحمدك ونقدس لك احترازا عما يوهمه الاستفهام من الإنكار والاعتراض فقالوا عليهم الصلاة والسلام ما معناه لم يسأل إنكارا ولا اعتراضا ونحن نسبح أي ننزه يا مولانا ذاتك وصفاتك عن النقص والتمثيل وننزه أفعالك كيفما تصرفت وأحكامك كيفما توجهت عن الجور والباطل وقبول الإنكار والاعتراض وقولهم بحمدك يعنون ننزهه في حال كوننا حامدين لك أي مادحين لك بكل كمال على كل حال فتكون الباء المصاحبة أو نزه بسبب نعمة توفيقك الذي يوجب حمدك وشكرك لا بحول منا ولا قوة فالباء على هذا سببية ويكون من باب التعبير بالمسبب عن السبب لأن الحمد بمعنى الشكر مسبب عن النعم ويحتمل أن يكون المعنى تنزه بنفس حمدك أي مدحك بكل كمال لأن المدح\r[المواهب اللدنية]\rأي إلا ما خصصه بإرادته وفيه إشارة إلى أن فعله للكائنات إنما هو بطريق الاختيار لا بطريق اللزوم كفعل العلة والطبيعة عند الفلاسفة والطبائعيين (و) الثاني من المعاني (اإلإرادة) الأزلية (صفة) كالجنس في الحد شامل لجميع الصفات المتعلقة (بتأثيرها) فصل يخرج به الصفات ما عدا القدرة لأن القدرة يتأنى بها أيضا (تخصيص الممكن) أي ترجيحه فصل يخرج به القدرة وبقي الحد لمحدوده (ببعض ما يجوز عليه) أي على الممكن والذي يجوز متقابلات ستة وهي الوجود والعدم والمقادير والصفات والأزمنة والأمكنة والجهات فالممكن يجوز عليه الوجود والعدم فيخصصه بالوجود دون العدم تخصيص الإرادة فيه وإيجاده هو تأثير القدرة (على وفق العلم) يعني أن الإرادة الأزلية تابعة في تعلقها للعلم فكل ما علم أنه يكون من الممكنات أولا يكون فذلك مراده جل وعلا وفيه رد على المعتزلة حيث ذهبوا إلى التلازم بين الأمر والإرادة وذلك باطل لأنه يلزم عليه أن يقع في ملك مولانا مالا يريد تعالى الله عن ذلك فعلا ملازمة بين الأمر والإرادة على مذهب أهل الحق بل بينهما عموم وخصوص من وجه فقد يأمر ويريد كإيمان الأنبياء والملائكة عليهم الصلاة والسلام وسائر المؤمنين وقد لا يأمر ولا يريد كالكفر في حقهم وقد يأمر ولا يريد كإيمان من سبق في علم الله أنه لا يؤمن كأبي جهل وأضرابه فانه مأمور بالإيمان ولم يرده منه وقد يريد ولا يأمر كالكفر والمحرمات والمكروهات والمباحات فانه أرادها وقوعها ولا يأمر بها فاعرفه واحترز بالممكن في التعريفين من الواجب الذاتي ومن المستحيل الذاتي فان القدرة والإرادة لا يتعلقان بهما ولو تعلقنا بالواجب لزم تحصيل أو انقلاب حقيقته إن قدر تعلقهما بعدمه ولو تعلقنا بالمستحيل لزم فيه ما ذكرناه على العكس وشمل الممكن ما يصدر عن الفاعل الظاهري إذ هو سبحانه الخالق له وإن كسبه الفاعل كما شمل الإعدام والتروك غير الأزلية على نزاع الأصج منه تعلقها بها على ما اعتمده المصنف رحمه الله تعالى ونفعنا به في شرحه وبالغ في الاحتجاج عليه من أن العدم مقدور لله سبحانه طارئا أو سابقا أما الأول فظاهر وأما الثاني فبناء على أن علة الاحتياج الإمكان فقط وليس الحدوث جزءا من العلة ولا شرطا. فان قلت ما معنى القدرة على العدم السابق فالجواب معناه احتياجه في استمراره فيما لا يزال والفاعل المختار سبحانه أن يجعل مكانه الوجود وكذلك الوجود وكذلك الأصح أيضا أن التروك مقدورة القادر كالإعدام غير الأزلية لأن الترك هو الكف والإمساك عن الفعل وهو أمر وجودي وأما العدم السابق في الأزل فالأصح"], [45, "بالكمال تنزيه عن ضده فتكون الباء للآله والله تعالى أعلم وقولهم ونقدس لك يعنون والله تعالى أعلم نقدس أنفسنا أي نطهرها من كل خاطر رديء لك أي لأجل رضاك والغنية بك عن كل ما سواك ويحتمل أن يكون المعنى نطهر قلوبنا لأجل خدمتك وعبادتك إذ لا يصح الخدمة والعبادة إلا مع قلب نقي من جميع الأدران وأما جوابه جل وعلا لهم بقوله إني أعلم ما لا تعلمون فمعناه والله تعالى أعلم إني وإن جعلت في الأرض من يفسد فيها ويسفك الدماء فإني أعلم ما في ذلك من الحكم والمصالح التي تقع بمحض الاختيار لا باللزوم والإيجاب ما لا تقدرون على الإحاطة بعلمه وبقية ما في الآية من المعاني محله التفسير وبالله تعالى التوفيق.\rأفضلية سيدنا محمد صلى الله عليه وسلم على جميع الأنبياء والمرسلين\r("]], "pg": [34, 45]}, "516.25": {"x": [[45, "وأفضلهم سيدنا محمد صلى الله عليه وسلم وعلى آله عدد ما ذكره الذاكرون وغفل عن ذكره الغافلون ورضي الله تعالى عن أصحاب رسول الله أجمعين وسلام على جميع الأنبياء والمرسلين والحمد لله رب العالمين) لا ريب ولا خفاء لكل مؤمن أن سيدنا ومولانا محمدا صلى الله عليه وسلم رسول الله تعالى أرسله جل وعلا بالهدى ودين الحق لكافة الإنس والجن وجعل سبحانه شريعته السمحاء ناسخة لجميع الشرائح باقية إلى أن تقوم الساعة ولم يخالف في ثبوت رسالته عليه الصلاة والسلام من أهل فعل والأديان إلا البعض من اليهود والنصارى والحجة عليهم أنه عليه الصلاة والسلام ادعى النبوة والرسالة وأظهر المعجزة وكل من كان كذلك فهو نبي رسول أما دعواه عليه الصلاة والسلام الرسالة إلى الخلق فأمر معلوم بالضرورة وأما إظهاره للمعجزة فلأنه أتى بالقرآن وأخبر بالمغيبات وأظهر أفعالا كثيرة تخرج عن الحصر على خلاف المعتاد بلغت جملتها حد التواتر واستيفاء ذلك مما لا تفي به الأسفار الكبيرة ولا التعاربق الطوبلة وكل ذلك زيادة على النصوص الدالة على نبوته وعظيم شرفه الوارد على كتب الأنبياء المتقدمين عليهم الصلاة والسلام المنقولة إلى القرى المشهورة فيما بين أممهم وهي نصوص كثيرة جدا في معرفة نبوته عليه الصلاة والسلام. منها ما جاء في السفر الخامس من التوراة جاء الله من طور سيناء واشرق من ما هير واستعلن من جبل فاران وذلك كناية عن إنزال الله تعالى التوراة على موسى عليه السلام بطور سيناء والإنجيل على عيسى عليه السلام بساعير وهو جبل من جبال الشام وإنزال الفرقان على نبينا ومولانا محمد صلى الله عليه وسلم فاران وفاران هي مكة بإجماع، ومعنى جاء الله أي جاء شرعه ودينه\r[المواهب اللدنية]\rتعلقه به على ما قاله الشيخ تجوز وللقدرة تعلقان أزلي وغير أزلي وكذا الإرادة سواء بسواء فالأولى للقدرة تابع للأزلي للأرادة فاعرفه والتعلقات عند أهل الحق مرتبة تعلق القدرة وتعلق الإرادة وتعلق الإرادة وتعلق العلم فالأول مرتب على الثاني والثاني مرتب على الثالث فالترتيب في نفس التعلق لافي الصفات فاعرفه.\rفان قلت هل التأثير في المقدور وقع بصفات المعاني لا المعنوية أو بهما معا فالجواب وقع بهما معا وذلك أن المعنوية لما كانت صفات ثبوتية لا تعقل على خيالها إلا بواسطة المعاني فكذلك تعلقاتها لا تعقل على حيالها وإنما تعقل بواسطة تعلقات المعاني ولا مانع من اتحاد المتعلق كما في صفة العلم والكلام فاعرفه فانه نفيس قل من ينبه عليه (و) الثالث من المعاني (العلم) الأزلي (صفة) كالجنس يشمل جميع الصفات المتعلقة (ينكشف بها) يعني يتضح فصل يخرج به جميع الصفات ما عدا السمع والبصر والادراك على القول به والتعبير بالمضارع يقتضي دوام الانكشاف واستمراره وقيل بها ولم يقل لها لأن نسبة الانكشاف للذات حقيقية وللعلم مجاز كما تقدم والقدرة (للعلوم) فصل ثان يخرج به السمع والبصر والادراك لأن هذه تتعلق بالموجود مطلقا واجبا كان أو ممكنا دون المعلوم الصادق بالمستحيل والممكن المعدوم فانها لا تتعلق بهما وبمقابلهما والمعلوم ما شأنه أن يعلم وهو كل واجب وكل جائز وكل مستحيل (على ما هو به) أكيد وتصريح اخراج الجهل المركب لأنه لا ينكشف به المعلوم على ما هو به (انكشاف) أي اتصافا لإخفاء معه (لا يحتمل) العلم (النقيض) يخرج به اعتقاد غير الجازم لأنه يحتمل النقيض بتشكيك مشكك إن كان على غير ضرورة أو برهان أو بالسلب والعياذ بالله إن كان عنهما وفي بعض النسخ (بوجه من الوجوه) أشار به والله أعلم إلى ما قرره المصنف رحمه الله في بعض تآليفه من أن العلم تلزم فيه ثلاثة أمور الجزء والثبات والطباق فلا يحتمل النقيض بحسب الذهن للجزم ولا بحسب الخارج للمطابقة للواقع ولا بحسب تشكيك مشكك لأجل الثبات هذا معنى كلامه والله أعلم. واعترض على هذا الحد بأنه يلزم فيه الدور وذلك أن المحدود يتوقف على الحد والحد يتوقف على المحدود وهو عين بالدور.\rويجاب بأن الحد المذكور لفظي وقد صرحوا بأن الدود اللفظية لا يرد عليها الدور وللعلم تعلق واحد أزلي وهو صريح كلام المصنف رحمه الله ونفعنا به آمين في الكبرى في فصل وجوب الوحدة للصفات وقيل له تعلقان أزلي وغير أزلي وهو ظاهر كلام ابن أبي شريف في حواشي العقائد على ما نقل الشيخ يس منه حيث قال وقد صرح ابن أبي شريف في حواشي العقائد بأن تعلق العلم أزلي وفي بعض حواشيه عند قوله صفة أزلية تنكشف بها المعلومات عند تعلقها بها تمتاز المدركات عند تعلق تلك القدرة امتياز قديما إذا كان"], [46, "الحق من هذه المواضع على أيدي هؤلاء الرسل عليهم الصلاة والسلام وانظر كيف عبر في التوراة عن ظهور نبينا ومولانا محمد صلى الله عليه وسلم بالاستعلان الذي يقتضي كمال الوضوح والظهور إشارة إلى كثرة معجزات نبينا ومولانا محمد صلى اله عليه وسلم وإظهار دينه على جميع الأديان وانتشار موبقائه إلى أن تقوم الساعة، ومنها ما جاء في السفر الخامس من التوراة أنه تعالى قال لموسى عليه السلام إني مقيم لبني إسرائيل نبيا من بني إخوانهم مثلك وأجري قولي فيه ويقول لهم ما آمره به والرجل الذي لا يقبل قول النبي يتكلم باسمي فأنا أنتقم منه ولا شك أن المراد ببني أخوه بني إسرائيل بنو إسمعيل إذ إسرائيل هو يعقوب من ولد إسمعيل عليهم السلام ولم يبعث من ولد إسمعيل بعد موسى عليه السلام غير سيدنا ومولانا محمد صلى الله عليه وسلم ومنها ما جاء في السفر الأول من التوراة أنه تعالى قال لإبراهيم عليه الصلاة والسلام إن هاجر تلد ولدا ويكون من ولدها من تكون يده فوق الجميع ويد الجميع مبسوطة إليه بالخشوع ولإخفاء أنه لم يكن من ولد هاجر من يده فوق الجميع غير سيدنا محمد صلى الله عليه وسلم فانه بعث إلى أهل الأرض كأفه وأظهر الله تعالى دينه على جميع الأديان كلها وأذعن له جميع أهل الأرض وبسطوا إليه أيديهم بالذلة والخشوع، ومنها ما جاء في المصحف الرابع عشر من الإنجيل أنا أطلب لكم إلى أبي حتى يمنحكم ويعطيكم بارقليط ليكون معكم إلى الأبد والبار قليط روح الحق واليقين، وفي الخامس عشر من الإنجيل فأما بار قليط روح القدس الذي يرسله أبي باسمي هو يعلمكم ويمنحكم جميع الأشياء وهو يذكركم ما قلت لكم ثم قال وإني أخبركم بهذا قبل أن يكون حتى إذا كان ذلك تؤمنون به وقوله أبي معناه ربي وإلهي وقوله باسمي يعني بالنبوة مثلي ومعنى البار قليط النبي كاشف الخفيات ومعنى كونه الحق واليقين والقسط الذي هو العدل أن هذه الأشياء قبل مبعث نبينا ومولانا محمد صلى الله عليه وسلم كالميتة لا حراك لها ولا انتعاش ونبينا ومولانا محمد صلى الله عليه وسلم إذا بعث هو كالروح لها فترجع حينئذ قائمة في الأرض ولا خفاء أنه عليه الصلاة والسلام هو الذي أحيا الله تعالى به بعد عيسى عليه السلام الحق واليقين والعدل بعد ما خمدت وماتت وانتشر الباطل وقوي أمره وهو عليه الصلاة والسلام الذي يبقي شرعه إلى الأبد، وفي المصحف السادس عشر من الإنجيل\r[المواهب اللدنية]\rذلك التعلق قديما وهو التعلق بالنسبة إلى الأزليات والمتجددات باعتبار أنها ستحدث وحادثا إن كان حادثا وهو التعلق بالنسبة إلى المتجددات باعتبار وجودها الآن أو في الزمان الماضي فلا شك إشكال في توقيت الانكشاف بالتعلق اهـ (و) الرابع من المعاني (الحياة) الأزلية (صفة) كالجنس في الحد يشمل جميع الصفات (تصحح) أي توجب (لمن قامت) الحياة (به أن يتصف بالإدراك) أزلا وأبدا. فان قلت لم قال في الحد أن يتصف الادراك ولم يقل أن يدرك فالجواب لأن الذي من لوازم الحياة صحة أن يدرك دون العلم نفسه والتعبير بالادراك إنما يحسن على القول بأن الباري سبحانه وتعالى يجوز وصفه به فلو قال أن يتصف العلم كان أولى والله أعلم وشمل الادراك السمع والبصر والادراك نحو اللمس والشم والذوق على القول به ولم يشمل نحو القدرة والإرادة والعلم والكلام مع أنها مصححة لمن قامت به ذلك ولهذا صرح المصنف رحمه الله تعالى في صغرى الصغرى باستحالة وجود الصفات السابقة وهي القدرة والإرادة والعلم والسمع والبصر والكلام بدونها. وأورد على قوله إن الصفات السابقة تستحيل بدون الحياة حنين الجذع وكلامه بعض الجمادات وأجب بأنه يجوز أن يخلق فيها الحياة فليس المراد الاستحالة العقلية على وجه بعيد فتدبر والحياة ليست من الصفات المتعلقة فلذلك لا تطلب أمرا زائدا سوى ذات الحي بخلاف غيرها من الصفات التي تقتضي زائدا على القيام بالذات كالعلم مثلا فانه بعد قيامه بالذات يطلب أمرا يعلم به وكذا باقي هذه السبع. والحاصل أن جميع صفات المعاني متعلقة أي طالبة لزائد على القيام بمحلها سوى الحياة وهذا التعلق نفسي أي ذاتي لتلك الصفات كما أن قيامها بالذات نفسي لها أيضا. فان قلت جعلهم التعلق صفة البلوى هل ذلك على سبيل الحقيقة أو التجوز فالجواب جعل ذلك على وجه التجوز لا على سبيل الحقيقة لأنه وصف للصفة ولكن الصفة لا قيام لها بنفسها بل تقوم بالذات فتكون صفتها صفة للذات من حيث إن تعلق القدرة مثلا كون الذات متعلق قدرته بكذا وقس على ذلك (و) الصفة الخامسة من المعاني المتعلقة (السمع) الأزلي (صفة) كالجنس في الحد يشمل جميع الصفات ما عدا العلم والبصر والادراك لأنه (ينكشف بها) أيضا (كل موجود) يعني قديما كان أو حادثا كان أو حادثا فصل يخرج به العلم لأنه يتعلق بما هو أعم من الموجود وهو المعلوم الشامل للمستحيل والممكن المعدوم والسمع والبصر لا يتعلقان بهما (على ما هو به انكشافا) زيادة إيضاح وبيان (يباين سواه ضرورة) فصل ثالث يخرج به البصر والادراك لأن هذه الصفات لما كانت غير متحدة الحقيقة فكذلك تعلقاتها غير متحدة الحقيقة"], [47, "أقول لكم الآن حقا يقينا إن انطلاقي عنكم خير لكم فان لم أنطلق عنكم إلى أبي لم يأتكم البار قليط وإن انطلقت أرسلت به إليكم فاذا به إليكم ما جاء هو يفيد أهل الأرض العلم ويدينهم ويوبخهم ويوقفهم على الخطيئة والبر ثم قال إذا جاء روح الحق واليقين يرشدكم ويذكركم بجميع الخلق لآنه ليس يتكلم ببدعة من تلقاء نفسه ومعنى اطلاق عيسى عليه السلام إلى أبيه أي ربه عز وجل اطلاقه إلى محل رفضه وكرامته والاستراحة من الناس والتوجه بكلية القلب إلى المولى تبارك وتعالى وكونه يرسل نبينا ومولانا محمدا صلى الله عليه وسلم يحتمل أن يكون معناه أنه يتسبب في ذلك برغبته إلى الله تعالى ويحتمل ان يكون معناه لما علم عليه الصلاة والسلام أن بعث سيدنا ومولانا محمد صلى اله عليه وسلم إنما يكون بعد رفعها وتغيبه عن الناس وأن رفعه من أمارات بعثه صلى الله عليه وسلم فأسند إرساله إلى نفسه بهذا المعنى على سبيل المجاز والله تعالى أعلم، ومنها ما جاء في الزبور من قوله تعالى خطابا لنبينا ومولانا محمد صلى الله عليه وسلم تقلد أيها الجبار السيف فان ناموسك وشرائعك مقرونة بهيبة يمينك وسهامك مسنونة والأمم يخرون تحتك أي يذلون لك حتى يدخلوا في الإسلام طوعا أو كرها أو يعطوا الجزية عن يد وهم صاغرون، وفي الزبور أيضا يقول الله تعالى لداود عليه السلام سيولد لك ولد أدعى له أبا ويدعى لي ابنا فقال داود عليه السلام اللهم ما بعث جاعل السنة كي يعلم الناس أنه بشر وهذا الولد الذي ولد لداود عليه السلام بهذه الصفة المذكورة هو عيسى عليه السلام ولم يبعث الله تعالى بعده جاعلا للسنة وخامدا للبدعة وكاشفا للغمة إلا نبينا ومولانا محمدا صلى الله عليه وسلم فأعلم الناس عليه السلام عبد الله ورسوله وأنه لم يستنكف المسيح أن يكون عبد الله ولا الملائكة المقربون وأنه ما كان لله أن يتخذ من ولد وما ينبغي للرحمن أن يتخذ ولدا إن كل من في السموات والأرض إلا آتي الرحمن عبدا وأن مولانا جل وعز أحد صمد لم يلد ولم يولد ولم يكن له كفوا أحد وقال أشعياء النبي عليه السلام حاكيا عن الله تعالى عبدي الذي سرت به نفسي أنزل عليه وحي فيظهر في الأمم عدلي يوصي الأمم بالوصايا ولا يضحك ولا يسمع صوته في الأسواق يفتح العيون العور ويسمع الآذان الصم ويحي القلوب الغلف وما أعطيه لا أعطيه غيره أحمد يحمد الله حمدا كثيرا ثم أشار إلى بلده مكة فقال تفرح البرية العطشا وسكانها يهللون الله\r[المواهب اللدنية]\rفلا يلزم من اجتماعها في متعلق واحدالاتحاد لأن كل صفة من هذه الصفات تعلقا يخصها ليس هو عين الآخر فاعرفه (و) الصفة السادسة من صفات المعاني (البصر) الأزلي ... (مثله) يعني مثل السمع في جميع ما تقدم في تعريفه وهو وجوب تعلقه بكل موجود قديما كان أو حادثا. وأورد على هذين التعريفين المذكورين لزوم الدور لتوقف معرفة كل واحد منهما على معرفة الآخر , ويجاب بما أجيب به في صفة العلم بأن هذين التعريفين المذكورين لفظيان وقد صرحوا بأنه لا يرد عليهما الدور فاعرفه وللسمع والبصر تعلقان أزلي وغير أزلي فالأزلي تعلقه بذاته وصفاته الوجودية في الأزل وغير الأزلي تعلقه بذوات الحوادث الكائنات كلها وجميع صفاتها الوجودية فيما لا يزال. فان قلت إذا وجب تعلق السمع والبصر بالموجودات والعلم قد تعلق بها يلزم إما تحصيل الحاصل أو اجتماع المثلين المتلازمين إن كان ما تعلق به السمع والبصر تعلق به العلم وأما خفاء بعض المعلومات عن العلم إن لم يكن كذلك وكلاهما محال فالجواب إنما نختار الأول ولا يلزم من ذلك الالتزامان ضرورة أنهما غير متحدي الحقيقة سواء قلنا إنهما أنواع العلم أولا فتعلقاتها كذلك كل تعلق له حقيقة من الانكشاف مخصه. فان قلت قد جعلتم التعلق وصفا نفسيا للصفة وهو مالا تعقل بدونه والسمع والصبر موجودان في الأزل من غير تعلق لهما بذواتنا إذ هي معدومة في الأزل فالجواب أنهما تعلقا في الأزل بما كان موجودا وهو الذات الأزلية وصفاتها الوجودية فلم يكن السمع والبصر غير متعلقين ولا يلزم جميع المتعلقات (و) الصفة السابعة من المعاني (الإدراك) يعني إدراك المشمومات وإدراك الملموسات ثابتة على العلم من غير جارحة ولا اتصال ولا حدوث وهذا القول لإمام الحرمين وإلى هذا القول أشار المصنف نفعنا الله تعالى به بقوله (على القول به) أي بتبوته له تعالى (مثلهما) يعني مثل السمع والبصر في تعريفه وفي وجوب تعلقه بكل موجود وأنه لا يختص بما اختص به في الشاهد وفيه ثلاثة أقوال: القول بالثبوت كما ذهب إليه إمام الحرمين والقول بالنفي كما ذهب إليه بعضهم لما رآه ملزوم الاتصال بالأجسام، يعني ويدخل في العلم والقول الثالث وهو المختار عند المحققين بالوقف فيه إثباتا أو نفيا (و) الصفة الثامنة من المعاني المتعلقة (الكلام الأزلي) أي القديم (وهو المعنى) كالجنس في الحد يشمل جميع المعاني المتقدمة (القائم بالذات) العلية فيه رد على المعتزلة القائلين بأنه لا يقوم بذاته تعالى وإنما يخلقه في حرم من الأجرام تعالى الله عن قولهم (المعبر عنه) عن الكلام الأزلي (بأنواع العبارات المختلفات) فاذا عبر عنها بالعربية فالقرآن والسريانية فالإنجيل وبالعبرانية والمسمى واحد وإن اختلفت العبارات هذا معنى كلامه سيجزئه فيه رد ّ على"], [48, "تعالى على كل شرف ويكبرونه على كل رابية ولا يضعف ولا يغلب ولا يميل إلى الهوى ولا يسمع في الأسواق صوته ولا يذل الصالحين اللذين هم كالقصعة الضعيفة بل يقوّي الصالحين وهو ركن المتواضعين وهو نور الله الذي لا يطفأ ولا يخصم حتى تثبت في الأرض حجتي وينقطع به العذر وإلى توراته ينقاد الخلق، فانظر رحمك الله إلى هذا التصريح العظيم بنبينا ومولانا محمد صلى الله عليه وسلم من غير ما وجه كقوله يوصي الأمم فانه يقتضي البعث ولم يثبت ذلك إلا لنبينا ومولانا محمد عليه الصلاة والسلام وقوله أحمد يحمد الله فهذا تصريح باسمه وقوله تفرح البرية العطشا وسكانها إلى آخره فانه لاخفاء أن هذه أوصاف مكة، وفي صحف أشعياء عليهم السلام اتفرح أهل البادية العطشا ولتبتهج البراري والفلوات لأنها ستعطي بأحمد محاسن لبنان وكمثل حسن العساكر والرياض فانظر أيضا إلى هذا ال تصريح الواضح باسمه عليه الصلاة والسلام بما أكرم الله تعالى به بلده مكة بسبب بركة وجوده ونشأته فيها وبعثه منها ومعنى كونها عطشاء أي من الرسل والأنبياء عليهم الصلاة والسلام فان بلد معظمهم الشام فأعطى الله سبحانه لمكة يبعث أشرف الخلق منها صلى الله عليه وسلم محاسن لبنان أي الشام لأن لبنان من جباله، وفي صحف أشعياء أيضا عليه السلام أتت أيام الكمال ثم قال لتعطوا يا بني إسرائيل الجاهلين أن النبي الذي تسمونه ضالا هو صاحب النبوة تفترون ذلك على كثرة ذنوبكم وعظيم فجوركم وفي صحت حزقيائيل النبي عليه السلام يقول عن الله عزوجل بعد ما ذكر معاصي بني إسرائيل وشبهم بكرمة وهي شجرة العنب فقال لم تلبس تلك الكرمة أن قلعت بالسخط ورمى بها على الأرض وأحرقت السمائم ثمارها فعند ذلك غرس غرس في البادية وفي الأرض المهملة العطشا وخرجت من أغصانها الفاضلة نار أكلت تلك الكرمة حتى لم يوجد فيها غصن ولا قضيب، فاعتبر رحمك الله بهذا التصريح العظيم به عليه الصلاة والسلام وبصفة بلده مكة والتصريح بما وقع له صلى الله عليه وسلم مع اليهود بني إسرائيل من تمكينه تعالى له عليه الصلاة والسلام منهم بالقتل الذريع والسبي والإذلال لهم بضرب الجزية في جميع بلاد الإسلام وقال دانيال النبي عليه السلام وقد سأله الملك بختنصر عن منامة رآها وطلبه أن يخبره بها وبتفسيرها فقال له دانيال عليه السلام أيها الملك رأيت صنما بارع الجمال أعلاه من ذهب ووسطه من فضة وأسفله من نحاس\r[المواهب اللدنية]\rالحشوية القائلين إن كلامه حروف وأصوات قائمة بذاته ومع كونه حروفا وأصواتا زعموا أنه قديم بل وزعموا أن المداد حادث فاذا كتب به بالقرآن صار بعينه قديما وهذا المذهب واضح الفساد إذ لا تعقل إلا حادثة لتجددها فالعدم يكتنفها سابقا ولاحقا والقديم لا يقبل العدم لا سابقا ولا لاحقا (المنزه) أي المقدس المطهر (عن البعض والكل) هما من أوصاف الكلام الحادث وكلام الله قديم والقديم لا يوصف بأوصاف الحوادث وكيفيته مجهولة لأنا كما لا نحيط بذاته لا نحيط بجميع صفاته والحروف إنما هي عبارة عنه والعبارة غير المعبر عنه فلذلك اختلفت باختلاف الألسنة ولم يختلف هو فحروف القرآن حادثة والمعبر عنه بها هو المعنى القائم بذات الله قديم فالتلاوة والقراءة والكتابة حادثة وللمقروء والمتلو والمكتوب قديم أي مادلت عليه هذه القراءة والكتابة والتلاوة وكذلك ذكر الله تعالى فان الذكر حادث والمذكور وهو رب العباد قديم وهو رب العزة فافهم (والتقديم والتأخير) الظاهر أنهما مثلا زمان وجمع بينهما مبالغة في التنزيه عن الصفات الحوادث (والسكوت والتجدد) التجدد هو معاودة الكلام بعد السكوت والسكوت هو كما قال الحد ترك الكلام مع القدرة عليه (و ... والاعراب) فيه رد كما لا يخفى (وسائر أنواع التغيرات) أي وجميع أنواع التغيرات كالحرس و المحبة والآلة وما أشبه ذلك لأنه قديم وما ثبت قدمه استحال عدمه وبهذا يعلم أن ليس معنى كلم الله موسى تكليما أنه ابتدأ الكلام له بعد أن كان ساكنا ولا أنه بعد أن كله انقطع كلامه وسكت وإنما المعنى أنه أزال بفضله المانع عن موسى عليه السلام وخلق له سمعا وقواه حتى أدرك كلامه القديم ثم منعه بعد ورده إلى ما كان قبل سماعه كلامه (المتعلق) أي الدال لأن تعلق الكلام دلالة وله تعلقان أزلي وغير أزلي (بما يتعلق به العلم) الأزلي (من المتعلقات) وهي الواجبات والجائزات والمستحيلات ولابد من بيان الجمع حتى يصح اشتراكهما في التعلق وينتج عليه الفرق وبيان أن من علم أمرا يصح أن يتكلم به والموالى عالم بما كان ومايكون ومالا يكون فصح أن يتكلم بها وبيان التفرقة أن يقال إن متعلق الكلام كدلالة آية تدل على الواجب كقوله تعالى قل هو الله أحد وآية تدل على المستحيل كقوله تعالى لم يلد ولو يولد وآية تدل على الجائز كقوله تعالى والله خلقكم وما تعملون فان قلت مقتضى أن جميع ما تعلق به العلم يتعلق به الكلام أن الله في أزله قد علم عدم إيمان الكافر وقد أمره بالإيمان فالكلام إذا إنما يتعلق بالأمر بالإيمان ولم يتعلق بعدمه والعلم قد تعلق بعدمه وبالأمر به كصفا واتضاحا فهو إذا أتم تعلقا فالجواب أن متعلقات الكلام غير منحصرة في الأمر كما تقدم هب أنه لم يتعلق بترك"], [49, "وساقاه من حديد ورجلاه من فخار فبينما أنت تنظر إليه قد أعجبك حسنه إذ نزل حجر من السماء فكسره وضرب رأس الصنم فطحنه حتى اختلط ذهبه وفضته ونحاسه وحديده وفخاره ثم إن الحجر ربا وعظم حتى ملأ الأرض كلها فقال له الملك بختنصر صدقت فأخبرني بتأويلها فقال له دانيال عليه السلام أما الصنم فأمم مختلفة في أول الزمان وفي وسطه وفي آخره فالرأس من الذهب أنت أيها الملك والفضة ابنك بعدك والنحاس الروم والحديد الفرس والفخار أمتان ضعيفتان تملكهما امرأتان باليمن والشام والحجر النازل من السماء دين نبي وملك أمته أبدي يكون في آخر الزمان يغلب الأمم كلها ثم يعظم حتى يملأ الأرض كلها كما ملأها هذا لحجر، فانظر هذا التصريح الجلي ّ المطابق لسيدنا ونبينا ومولانا محمد صلى الله عليه وسلم فانه هو الذي بعث في آخر الزمان وهو الذي نبوته وملك أمته أبدي إلى يوم القيامة إذ لا نبي بعده صلى الله عليه وسلم ولا نسخ لشرعه الشريف ما بقيت الدنيا وهو الذي بعث إلى جميع الأمم وظهر عليها كلها وخلط بين أجناسها وجعلها على اختلاف أديانها ولغتها دينا واحدا وعلى لغة واحدة إذ كلهم يقرءون القرآن بلغة العرب وبها يصلون إلى غير ذلك وكلهم يدينون بدين واحد وهو دين محمد صلى الله عليه وسلم وهو دين الإسلام وبالجملة فنصوص الكتب السابقة على ثبوت نبوة سيدنا محمد صلى الله عليه وسلم وتعظيم شأنه وإيصاء الأنبياء الماضين عليه وإشادتهم ذكره وتبشيرات الأحبار به لاتكاد تنحصر وثبوت رسالته وشرفه على كل ما خلق مولانا تبارك وتعالى أجلى من الشمس وقد ثبت الإجماع على أفضليته صلى الله عليه وسلم على جميع الخلق وشواهد ذلك من الكتاب والسنة لاتكاد تنحصر ولا يلتفت إلى من ابتدع وحاول غير ذلك ويكفيك في معرفة شرفه وعلو ّ منزلته عند الله تعالى على جميع المخلوقات عموما بلا استثناء ما أجمع عليه من التقدم للشفاعة الكبرى في مواطن الآخرة وتنويه الله تعالى هناك بقدره والرفع لمنزلته\r[المواهب اللدنية]\rالإيمان في المثال بطريق الأمر فقد تعلق بطريق الخبر بعدم الوقوع وبطريق الوعيد فصح إذا قول أهل السنة إن جميع ما يتعلق به العلم يتعلق به الكلام {خاتمة} ونسأل الله حسنها. اعلم أن هذه الصفات ينحصر الكلام فيها في ستة فصول في دليل ثبوتها له تعالى وفي قدمها وفي قيامها به وفي حدوثها وفي وجوب وجودها وفي تعلقاتها بكل ما تعلق به فالجوامع الأربعة جمع بالعلة وجمع بالحقيقة وجمع بالشرط وجمع بالدليل، فأولها العلة وهي كون العالم عالما في الشاهد معلل بالعلم ومهما ثبت كون حكم معلومة لعلة شاهدا أو غائبا حتى يتلازما، وثانيها الحقيقة فمهما تقرر شاهد الحقيقة في محقق اطراد في مثله غائبا وذلك نحو حكمنا بأن حقيقة العالم من قام به العلم، وثالثها الشرط فمهما ثبت كون حكم مشروط بشرط شاهدا ثم ثبت مثل ذلك غائبا وجب القضاء لكونه مشروط بذلك الشرط اعتبارا بالشاهد وذلك نحو حكمنا بأن كون العالم عالما بشرط كونه حيا، ورابعها الدليل فمهما دل دليل على مدلول عقلا لم يوجد الدليل شاهدا أو غائبا بدونه كدلالة أفراد المشتق على الشيء على ثبوت مأخذ الاشتقاق له وكدلالة الأحداث على الحدوث ولاشك أن هذه الأربعة دالة كلها على ثبوت صفات المعاني لله تعالى، وأما قدمها فلأنه لو كانت أضدادها قديمة فلا تنعدم أبدا لأن القديم لا يقبل العدم فيلزم أن لا يقدر وكذا في غيرها فلا يوجد العالم مع أنه موجود هذا خلف.\rوأيضا لو كانت حادثة لاحتاجت في إحداثها إلى أمثالها تتعلق بها فلزم التسلسل والدور ويلزم من قدمها بقاؤها وأما قيامها به تعالى فلأنها لو لم تقم به لكان نسبتها إليه وإلى غيره سواء فكان تلزم أن لا توجد له حكما لأن إجابة الحكم حينئذ له دون غيره ترجيح بلا مرجح فلما أوجبت الحكم له دون غيره علمنا بالقطعي أنها قائمة به، وأما وحدتها فلأنه لو تعددت لم يخل إما أن تعدد إلى غير نهاية فيلزم ما لا نهاية له عددا في الوجود وهو محال أو إلى نهاية فيلزم الحدوث والاحتياج إلى المخصص إذ ليس لبعض الأعداد ترجيح على بعض، وأما وجوب وجودها فلم تختلف العلماء رضي الله تعالى عنهم في ذلك الخلاف في كونها هل هي واجبة الوجود لذاتها أو لموضوعها، فذهب الأقدمون إلى القول الأول وبه استمرت نصوص المغاربة من المتأخرين كالمصنف وغيره، وذهب إلى القول الثاني بعض المشارقة كالامام الفخر والبيضاوي والأولى ترك الاشتغال بهذه الأشياء، وأما تعليقاتها بكل ما تتعلق به فلأنها لو تعلقت ببعضها دون بعض للزم العجز والافتقار إلى المخصص وذلك محال هذا مذهب أهل الحق في إثبات صفات المعاني وأما المعتزلة فقد اتفقت ومن تابعهم من أهل الأهواء على نفسها ووقفوا على اتصافه تعالى بأحكامها المعنوية وقالوا يجب أن يكون قادرا بنفسه مريدا بنفسه وهكذا إلى آخرها وقصدوا بهذا التنزيه للمولى تبارك وتعالى فاذا هم وقعوا في تشويه فروا من القطر جاءوا تحت الميزاب واحتجوا بهذيانات وخرائف هي أوهن من بيت العنكبوت والقوم بانت عوارهم وما قل وكفى خير مما كثر وألهى، وقد انتهت بحمد الله وحسن عونه صفات المعاني وحاصلها أنها تنقسم إلى أربعة أقسام قسم لا يتعلق بشيء وهي الحياة وقسم يتعلق بالممكنات تاثيرا وهي القدرة والإرادة وقسم يتعلق بجميع الموجودات"], [50, "والإكرام له حيث اجتمع الأولون والآخرون وجميع الأنبياء والمرسلين والملائكة كلهم والمقربين وعم الخطب واشتد الهول وكل مشغول بنفسه خائف هائب لجلال المولى العظيم جاث على ركبتيه لما يرى في ذلك اليوم من الخطر والهول الجسيم ولا يتجاسر أحد في ذلك اليوم الهائل على مخاطبة المولى تبارك وتعالى في رفع شيء مما نزل سوى عبده وخاتم رسله وعروس مملكته وسرها وإكسيرها وسيد كل ما خلق الله تعالى صلى الله عليه وسلم فيقول عندما تنتهي الناس إليه في طلب الشفاعة إلى المولى تبارك وتعالى أنا لها ولا يخاف ولا يهمه أمر نفسه ولا يتعتع ويذهب حتى يسجد تحت ساق العرش فيقول المولى جل وعلا ارفع رأسك يا محمد وقل يسمع لك واسأل تعط واشفع تشفع فانظر رحمك الله إلى هذا الخطاب العزيز الشريف اللطيف له عليه الصلاة والسلام من مولانا تبارك وتعالى في ذلك اليوم الهائل الذي غضب فيه سبحانه غضبا عظيما لم يغضب قبله مثله ولا يغضب بعده مثله كيف وهو صريح في المعنى بلا نزاع ولا ريب ولا احتمال ولا خفاء أنه لا أكرم من نبينا وسيدنا ومولانا محمد صلى الله عليه وسلم على الله تبارك وتعالى وفي الحديث أنه صلى الله عليه وسلم أول من يقرع باب الجنة فيقول رضوان خازنها من أنت فيقول محمد فيقول رضوان عليه السلام بك أمرت لا أفتح لأحد قبلك أو كما قال وروي ما معناه أن النار عندما تسوقها الملائكة الموكلون بها بالسلاسل لتحيط بالخلق في المحشر فاذا قربت منهم بنحو خمسمائة عام تشهق عليهم شهيقا منكرا وتنفلت منها الأعناق إلى المحشر طول العنق منها خمسمائة سنة له فم وأسنان من نار فيصل العنق إلى المحشر ويزفر عليهم ويشهق عليهم شهيقا منكرا لا يستطاع سماعه ويملأ عليهم الجو ّ ظلمة ونارا زيادة على ما هم فيه من الأهوال الجسيمة ويلتقط النق الناس من الموقف ويبتلعهم ذلك العنق الطويل إلى جوفه وحينئذ تجثو على الركب الملائكة المقربون\rوالأنبياء والمرسلون على جميعهم الصلاة والسلام\r[المواهب اللدنية]\rانكشافا وهو السمع والبصر وقسم يتعلق بجميع أقسام الحكم العقلي انكشافا ودلالة وهو العلم والكلام وأعم الصفات في التعلق العلم والكلام فبين متعلق القدرة والإرادة ومتعلق السمع والبصر عموم وخصوص من وجه يجتمعان في الممكن الموجود وتنفرد القدرة والإرادة بالممكن المعدوم وبنفرد السمع والبصر بالموجود الواجب وبين متعلق القدرة والإرادة والعلم والكلام عموم وخصوص من مطلق فالعلم والكلام يشتركان مع القدرة والإرادة في الممكن مطلقا وينفردان بالواجب والمستحيل وبين متعلق السمع والبصر والعلم والكلام عموم وخصوص مطلق يشترك الجميع في الواجب والجائز الموجود وينفرد العلم والكلام بالممكن المعدوم والمستحيل وبين متعلق القدرة والإرادة والسمع والبصر ومتعلقي العلم والكلام عموم وخصوص مطلق العلم والكلام يشار كان القدرة والإرادة في الممكن ويشاركهما السمع والبصر في الموجود الواجب والجائز ويزيدان على القدرة بالواجب والمستحيل ويزيادن على السمع والبصر بالمستحيل والممكن المعدوم، وبالجملة أن مسألة الكلام ذات تشعب كثير وبحث مع المبتدعة منتشر شهير حتى قيل إنما سمى أصول الدين بعلم الكلام لأجله وقد قال بعض المحققين أن التطول في مسئلة الكلام بل وفي جميع صفاته تعالى بعد ما يستبين الحق لك قليل الجدوى لأن كنه ذاته تعالى وكنه صفاته محجوب عن العقل وعلى تقدير التوصل إلى شيء من معرفة الذات فهو ذوقي لا يمكن التعبير عنه والله أعلم.\r(والكلام) من حيث هو كلام (ينقسم) يعني يتنوع (إلى قسمين) أي نوعين (خبر وإنشاء) ووجه تقسيمه إلى هذين فقط أن الشيء إما أن يتبع مدلوله أو يتبعه مدلوله فان كان تابعا كان خبرا وإن كان متبوعا كان إنشاء قال معناه سعد الدين (فالخبر) من حيث هو خبر تعريفه (ما) أي الذي كالجنس شامل له وللأنشاء (يحتمل) يعني يقبل (الصدق) فحينئذ وهو مطابقة الخبر للواقع (و) يقبل (الكذب) وهو عدم مطابقة الخبر للواقع فصل يخرج به الإنشاء كالأمر نحو قم والنهي نحو لا تقم والنداء نحو يازيد والتمني نحو ليت لي مالا فأحج منه ويدخل في الخبر بسبب تقييد احتمال الصدق والكذب (لذاته) ثلاثة أقسام الأول ما يحتمل الصدق والكذب مطلقا أي بالنظر إلى ذلك الكلام وبالنظر لزائد عليه وهو المخبر والمعنى المخبر به مثاله قول قائل غير معصوم من الكذب فلان من أهل الجنة وفلان من أهل النار فهذا الخبر محتمل للصدق والكذب مطلقا سواء نظرنا إلى صورة نسبته أو إلى مادته ومعناه أو إلى المتكلم به والثاني ما يحتمل الصدق والكذب بالنظر إلى صورة نسبته فقط مع قطع النظر الزائد على ذلك أما إذا نظرنا إلى زائد على صورة نسبته فانه ينتفي عنه الاحتمال ويتحتم له الصدق بلا شك ومثاله أخبار مولانا تعالى وأخبار رسله عليهم الصلاة والسلام كقوله تعالى إن المتقين في جنات ونهر ومثله قوله صلى الله عليه وسلم لا نبي بعدي فان نظرنا إلى نفي هذا الخبر بقطع النظر عن زائد لذلك وجدناه يقبل الصدق والكذب وإن نظرنا إلى زائد عن الخبر وهو كون المخبر به الله تبارك وتعالى ورسوله المعصوم من الكذب عقلا ونقلا صلى الله عليه وسلم فانه يرتفع حينئذ عن هذا الخبر"], [51, "فحينئذ ينهض إلى النار نبينا ومولانا محمد صلى اله عليه وسلم فيزجرها عن الناس ويأمرها بالتأخر عنهم فتسمع النار حينئذ نداء من قبل الله تعالى اسمعي وأطيعي وقد روى عنه عليه الصلاة والسلام أنه قال أنا سيد ولد آدم ولا فخر وأنا سيد الناس وآدم فمن دونه تحت لوائي يوم القيامة ولو كان موسى وعيسى حيين ما وسعهما إلا اتباعي وبالجملة فثبوت شرفه وأفضليته على جميع المخلوقات يكاد أن يكون معلوما من الدين ضرورة بحيث لا يحتاج إلى سرد دليل:\rوليس يصح في الأذهان شيء إذا احتاج النهار إلى دليل\r{تنبيهان: الأول} قال التفتازاني في شرح المقاصد الدينية له بعد ذكر الإجماع على أنه صلى الله عليه وسلم أفضل الأنبياء والرسل عليهم الصلاة والسلام ثم اختلفوا في الأفضل بعده فقيل آدم عليه السلام لكونه أبا البشر وقيل نوح عليه السلام لطول عبادته ومجاهدته وقيل إبراهيم عليه السلام لزيادة توكله واصطفائه وقيل موسى عليه السلام لكونه كليم الله تعالى ونجيه وقيل عيسى عليه السلام لكونه روح الله وصفيه {الثاني} قال الشيخ العارف بالله المحقق السالك المربي قدوة المقتدين: وعلم المهتدين حجة الله تعالى أبو عبد الله محمد بن عباد رحمه الله تعالى ورضي عنه في رسائله في معنى الأفضلية التي ثبتت بين الأنبياء والرسل ومن في معناهم من الملائكة على جميعهم الصلاة والسلام قال إنما وقعت الأفضلية بينهم بحكم الله تعالى بأفضلية بعضهم على بعض لا من أجل علة موجبة لذلك وجدت في الفاضل وفقدت من المفضول وللسيد أن فضل بعض عبيده على بعض وإن كل واحد منهم كاملا في نفسه بالغا من ذلك الغاية التي تليق به من غير أن يحمله على ذلك وصف يكون فهم وذلك مما يجب له بحق سيادته والتمثيل بالسيد أمر تقربي إذ يخلو من البواعث والأغراض والله تعالى منزه عن جميع ذلك ثم إن الله تعالى أعلم بما يقتضيه هذا الحكم بالأفضلية فهذا هو الذي يظهر لي في سبب وجود الأفضلية بين الأنبياء عليهم\r[المواهب اللدنية]\rالعظيم احتمال الصدق والكذب ويتحتم له الصدق لا غير ومن أمثلة هذا القسم ما يخبر به من الأمور الضرورية ابتداء كالواحد نصف الاثنين أو انتهاء كقول أهل الحق العالم من عرشه لفرشه حادث وصانعه وهو الله القديم والثالث ما يحتمل الصدق والكذب بالنظر إلى ذاته وصورته فقط وإذا نظرنا إلى زائد على ذلك تحتم كذبه وارتفع عنه احتمال الصدق ومثاله قول المعتزلة الإرادة الأزلية لا تتعلق بالكفر ولا بالمعاصي وإنما تتعلق بالخير فقط والعبد يخلق أفعاله الاختيارية بالقدرة التي خلق الله فيه ونحو ذلك من عقائدهم الفاسدة فان نظرنا إلى نفس هذا الخبر فانه يحتمل الصدق والكذب وأما إذا نظرنا إلى برهان عموم تعلق الإرادة الأزلية وعموم تعلق القدرة السرمدية فانه يتعين الكذب لا غير ومثل هذا الخبر بخلاف المعلوم ضرورة نحو الواحد تعرف الأربعة وما أشبه ذلك فقد ظهر لك بهذا فائد زيادة لفظ لذاته في التعريف المذكور لأنه لو أسقط لما تناول التعريف إلا القسم الأول وهو ما يحتمل الصدق والكذب مطلقا ويكون حينئذ هو خادم لخروج القسمين الآخرين منه ويخرج أيضا بهذا التقييد الإنشاء الذي جعل الصدق والكذب لا من حيث ذاته بل من لوازمه الخبرية فلولا هذا التقييد لكان التعريف غير مانع.\rولما فرغ من الخبر شرع في الإنشاء فقال (والإنشاء) من حيث هو إنشاء تعريفه (ما) كالجنس شامل له ولغيره أي الكلام الذي (لا يحتمل) يعني لا يقبل (صدقا و) لا يقبل (كذا) فصل يخرج به الخبر لأنه يحتمل الصدق والكذب بخلاف النظر (لذاته) أي لصورته وحقيقته، ومثاله الأمر نحو قم وافعل والنهي نحو لا تقم ولا تفعل والاستفهام نحو هل قام زيد والتمني نحو ليت الحبيب قادم والنداء نحو يالله ارحمنا ويارسول الله أغثنا فان هذه الأمثلة كلها لا تحتمل صدقا ولا كذبا لأنها لم تحكم بوقوع شيء في الخارج ولا بعدم وقوعه ولهذا لا يحسن أن يقال لقائلها صدقت ولا كذبت وإنما زاد أيضا في تعريف الإنشاء التقييد بقوله لذلته ليخرج منه القسمان الأخيران من أقسام الخبر الثلاثة التي تقدمت في الخبر فان كل واحد منهما لا يحتمل الصدق والكذب بل يتحتم في الأول منهما الصدق لا غير وفي الثاني الكذب لا غير فلوا اقتصر في تعريف الإنشاء على قوله ما لا يحتمل صدقا ولا كذبا لدخل فيه القسمان من أقسام الخبر ويكون التعريف حينئذ غير مانع فبزيادة تقييد نفي احتمال الصدق والكذب بالذات خرج منه القسمان لأنهما يحتملان الصدق والكذب بالنظر إلى ذاتهما فهما إذا خبر لا إنشاء ويدخل في الإنشاء بهذا التقيد الأمر لشخص يأكل الطعام مثلا إذا كان الأمر يتمحل أي لا يريد من المأمور أكلا وليس عنده ما يأكله أصلا وإنما حصل له جرد ريا ونحوه فان هذا الأمر يحتمل الصدق والكذب باعتبار ما دل عليه العرف من الإخبار بالأكل والحب فيه وأما من حيث ذاته فلا يحتمل صدقا ولا كذبا فلولا التقييد بالذات في تعريف الإنشاء لخرج هذا الأمر ونحوه من الإنشاء لمحمل الصدق والكذب باعتبار لوزم الخبرويكون التعريف حينئذ غير جامع فقد أصاحت هذه الزيادة طرد التعريف وعكسه في الإنشاء والخبر وبالله التوفيق ولما فرغ من الكلام على الخبر والإنشاء وأن الخبر ما يحتمل الصدق والكذب شرع في تعريف الصدق فقال (والصدق) عند أهل السنة"], [52, "الصلاة والسلام ولا يتصور عندي إنكار ذلك وأما أن يعتقد في سبب وجود الأفضلية اتصاف الفاضل بصفات هي مفقودة من المفضول أو أن صفات الفاضل: قصة وصفات الأفضل كاملة عندي تكلف وتعسف ولا يسلم من الوقوع في سوء الأدب ومازلت قط أستثقل ما تواطأ عليه الجم ّ الغفير من العلماء المحققين حيث يقولون إن فلانا من الأنبياء حاله كذا وحال نبينا كذا وشتان ما بين الحالتين أو يقولون إن كان اختص بكذا فعند نبينا ما هو أعظم من ذلك كما قالوا في انفجار الماء من الحجر لموسى عليه السلام وانفجار الماء من بين أصابع نبينا ومولانا محمد صلى الله عليه وسلم ولم يفرقوا بينهما سوى أن الحجر مألوف منه انفجار الماء والأصابع لم يؤلف منها ذلك حتى إن بعض أهل العصر الذي يلي عصرنا نظم قصيدة طويلة مليحة استنبط فيها من أحوال نبينا ومولانا محمد صلى الله عليه وسلم ومعجزاته ما وازن جميع معجزات الأنبياء عليهم الصلاة والسلام وشريف أحوالهم وسلك ما ذكرناه من التباين بين قدر نبينا ومولانا محمد صلى الله عليه وسلم وغيره من الأنبياء عليهم الصلاة والسلام ولقد أحسن في ذلك وأساء أحسن من حيث ذلك الاستنباط وأساء لما يفهم منه من النقص والانحطاط فان قالوا إن ذلك مما تقتضيه أفضلية نبينا ومولانا محمد صلى الله عليه وسلم قلنا لهم من أين لكم ذلك والذي تقتضيه أفضليته لا نعرفه من تلقاء أنفسنا جملها ولا تفاصيلها وإنما نعرف ذلك من قبله عليه الصلاة والسلام ثم إنا لم نعرف من قبله إلا أمورا جملية لا يعلم حقائقها إلا من فضله وأمورا تفصيلية ربما نعلمها كقوله أعطيت كذا وفضلت بكذا أو ما معناه هذا فاذا اعتقدنا أفضليته باخباره إيانا بذلك ووقفنا على ما أخبرنا به من بعض البعض مما يقتضيه حكم الله له بالأفضلية ومن أين لنا بالاطلاع على كنه ما يقتضيه ذلك الحكم منه ثم إن اقتصرنا على ذلك ولم نتجاوز إلى أن نتعرض لالتماس ما يوجب وجود االأفضلية من قبل نظرنا إلى ما أعطى من الآيات وما طبع عليه من محامد الصفات وما اتصف به من محاسن الحالات وما فقده غيره\r[المواهب اللدنية]\rهو (عبارة عن مطابقة) يعني موافقة (الخبر) الذي عرفته فيما سبق في نفس الأمر قال السيد في حاشية المطاع فأما نفس الأمر فهو نفس الشيء والأمر هو الشيء ومعنى كون الشيء موجودا في نفس الأمر أنه موجود في حد ذاته أي ليس وجوده وتحققه وثبوته متعلقا بفرض فارض ولا اعتبار معتبر اهـ قال سيدي قدار الراشدي وهذا حقيقة الصدق من حيث هو وأما الصدق الواجب للرسل عليهم الصلاة والسلام فلا بد أن يكون مطابقا لما نفس الأمر ومطابقا إذ يستحيل أن يكون ذلك اهـ وسواء (وافق) المطابق (الاعتقاد) كقول السني الله تبارك وتعالى لأفعال العباد ولا أثر لقدرة العبد (أم لا) يكون موافقا بل كان مخالفا لاعتقاه كأن يصدر ذلك القول من المعتزلي بحضرة أهل السنة على سبيل التخفي لبدعة. فان قلت يرد على الحد لزوم الدور بأخذهم الصدق في تعريف الخبر حيث قالوا الخبر ما يحتمل الصدق والكذب لذاته فالجواب أن التعريفين المذكورين لفظيان وقد صرحوا بانه لا يرد عليهما الدور أصلا ولعدم اشتراط المطابقة للاعتقاد في حقيقة الصدق اوّل أهل السنة قوله تعالى إذا جاءك المنافقون قالوا نشهد إنك لرسول الله والله يعلم إنك لرسوله والله يشهد إن المنافقين لكاذبون مع أن ما قالوه صدق ولا يضر عدم الموافقة للاعتقاد على أصلهم فلذا صرفوا التكذيب فيها إلى غير المشهود مما تضمنته الشهادة من الخبر بمابقة ألسنتهم فيما أخبروا به من الرسالة ولا شك أن هذا الخبر الذي تضمنته الشهادة غير مطابق للواقع فصح تكذيبهم فيه، وذهب النظام من المعتزلة إلى أن الصدق عبارة عن مطابقة الخبر للاعتقاد وافق ما في نفس الأمر أولا، وذهب الجاحظ إلى أن الصدق عبارة عن مطابقة الخبر للواقع مع الاعتقاد لذلك. ولما فرغ من تعريف الصدق شرع في تعريف الكذب فقال (والكذب عمد مطابقة) يعني موافقة (الخبر) الذي عرفته فيما سبق (لما في نفس الأمر) أي الواقع (خالف الاعتقاد) كقول المعتزلي العبد يخلق أفعاله الاختيارية بالقدرة التي خلق الله فيه (أولا) يكون مخالفا للاعتقاد كان يصدر ذلك القول من السي بحضرة المعتزلة على سبيل التخفي منهم وارتكابه هذا الكذب المباح لدعوى الضرورة إليه ومن ذلك من يكره على النطق بكلمة الكفر وقلبه مطمئن بالإيمان. فان قلت التنافي بين الصدق والكذب من أي باب هو قلت من باب المساوي للنقيض لأن الصدق مطابقة الخبر والكذب عدم مطابقة وكذا التنافي الحاصل بين الأمانة والخيانة من باب المساوي للنقيض لأنه قال والخيانة عدم حفظها من ذلك فجعلها عدمية وأما على ما فسر المصنف في الصغرى فهي من باب تنافي الضدين لأنه فسر الخيانة بفعل شيء والفعل وجودي. واعلم أن تفسير أهل الحق للصدق والكذب ليحصل الوثوق بإخبار الرسول عليه الصلاة والسلام في أحكامه ووعده ووعيده وأحوال الآخرة جملة وتفصيلا ونعلم بالبرهان القطعي صدقه أي مطابقة أخباره لما في نفس الأمر لا لاعتقاده فقط مع جواز مخالفتها لما في نفس الأمر والله الموفق. ولما أن عرفت فيما سبق الصدق ليعرف منه الصدق الواجب في حق الرسل عليهم الصلاة والسلام"], [53, "من الأنبياء عليهم الصلاة والسلام من بعض هذه الأشياء كنا في ذلك مصيبين سالمين من سوء الأدب مع خواصه وأحبابه وإلا فان سوء الأدب والوقوع في النشب لازم لنا لزوما ضروريا لا محيص عنه كما فعل أئمتنا رضي الله عنهم ولا أقول إنهم في ذلك بمنزلة من هدم قصرا وبنى مصرا أو بنى قصرا وهدم مصرا وكنه بمنزلة من هدمهما لأن الأفضل لا يجب أن يفضل بشيء لم يجعله مولاه سببا في وجود أفضليته ولا يجب أيضا أن يحط الفاضل عن مرتبته كما قال عليه الصلاة والسلام لاتفضلوا بين الأنبياء ولا تخيروني على موسى ولا يقولن أحدكم أنا خير من يونس بن متى وللفضول أيضا لا يحب أن يجعل لمفضوليته علة لم يجعلها مولاه سببا وهو فقده ما اتصف به الأفضل ولا يجب أيضا أن يفرق بينه وبين الأفضل وهم جميعا رسل الله عز وجل وعدم محبة كل واحد منهم لهذا كله إنما هو لحق الله تعالى لالهم فقد آل سوء الأدب معهم إلى سوء الأدب مع الله تعالى وهذا أمر عظيم فهذا كلام جر إليه ما كنا بصدده من بيان الأسماء التي سمى الله تعالى بها نبيه محمدا صلى الله عليه وسلم أو واحدا من أنبيائه ورسله عليهم الصلاة والسلام لا يقال في بعضها إنه أشرف من بعض من حيث تسمية الله تعالى له بذلك وأما من حيث تسمية غيره كما إذا سمى ذلك الشخص نفسه فلا ينبغي له أن يسمي نفسه إلا باسم العبد ولا يختار إلا ذلك كما قال صلى الله عليه وسلم خيرت بين أن أكون نبيا ملكا أو نبيا عبدا فاخترت أن أكون نبيا عبدا ولو وجد صلى الله عليه وسلم اسما يتضمن من التلاشي والعدم أشد مما يتضمنه اسم العبد لتسمى به واختاره ويكون اسم العبد من هذه اليثية أشرف أسمائه كما قال الشاعر:\rلا تدعني إلا بيا عبدها .... فانه أشرف أسمائي\rقال ولا معنى عندي لقول من قال في قوله صلى الله عليه وسلم أنا سيد ولد آدم ولا فخر أي لا فخر لي\r[المواهب اللدنية]\rبدلالة المعجزة النازلة من مولانا سبحانه منزلة قوله صدق عبدي في كل ما يبلغ عني عرف هنا الأمانة ليعرف منه أيضا الأمانة الواجبة في حق الرسل عليهم الصلاة والسلام فقال (والأمانة) هي المقدمة الثامنة وهي ختامها وعطفها على الصدق لما بينهما من الاشتراك والتلازم (حفظ) أي صون (جميع) أي كل (الجوارح) جمع جارحة وهي الكواسب والأعضاء (الظاهرة) للأعيان والمشاهدة وهي سبع السمع يحفظه من سماع ما لا يليق كالغناء والقذف وغير ذلك والبصر يحفظه من النظر إلى المحرمات كالنظر إلى محارم المسلمين واللسان يحفظه من الكذب والغيبة والنميمة وشهادة الزور والكلام القبيح وأيمان الطلاق وغير ذلك واليدان يحفظهما من لمس مالا يجوز لمسه والسرقة والخيانة وضرب مالا يجوز ضربه ولو حيوانا والرجلان يحفظهما من االسعي إلى الحرام كالمشي للمعاصي ولأبواب الظلام إلا لحاجة يقضيها له أو لإخوانه المسلمين والبطن يحفظه من أكل الحرام إلا عند الضرورة والفرج يحفظه من الزنا واللواط وإتيان الزوجات والإماء في وقت الحيض والنفاس (و) حفظ الجوارح (الباطنة) كالقلب والعقل والصدر والفؤاد ويحتمل إطلاق الجمع الباطن تعظيما له كما في قوله تعالى رب ارجعون وإلا فالباطنة هو عضو واحد وهو القلب وسمي بذلك لتقلبه ومذهب أهل السنة أنه محل العقل (من التلبس) أي من الاشتغال يتعلق بحفظ (تنهى) نهى الله تعالى عنه أو رسوله الصادق الأمين وما آتاكم الرسول فخذوه وما نهاكم عنه فانتهوا (نهي تحريم) كأكل أموال الناس بالباطل والأكل بالشفاعة أو بالدين أو التجسس على المسلمين (أو) نهي (كراهة) كالنفل بعد فرض العصر وبعد الصبح وكقراءة القرآن في الركوع والسجود مثلا وسمى صاحبها أمينا للأمن في جهته من المخالفة لا حد له وأوحي به (والخيانة) ضد الأمانة (عدم حفظها) أي عدم حفظ الجوارح الظاهرة والباطنة المتقدم ذكرها (ومن ذلك) يعني من المحرم والمكروه،\rوبالجملة لاشك أن إطلاق المولى جل وعلا الأمر بالاقتداء بهم من غير تأمل ولا بحث دليل قطعي على أنهم معصومون من كل مخالفة وعيب في الأقوال والأفعال والظاهر والباطن وقد ثبت إجماع أهل الحق على أمانة الأنبياء والرسل عليهم الصلاة والسلام وأنهم منزهون من جميع العيوب والآثام وأن أفضلهم وسيدهم بل هو أفضل جميع الخلائق سيدنا ونبينا وشفيعنا محمد صلى الله عليه وسلم وعلى آله وصحبه صلاة وسلاما نرجو بهما فضلا من المولى الكريم تبارك وتعالى وإكراما من كل هول وفتنة في حياتنا الدنيا وبعد مماتنا وفي قبورنا ويوم يبعث تعالى لفصل القضاء جميع الأمم. ولما كان أحسن ما يتدانى به التوفيق حتى إنه لعزازة قدره عند الله لم يذكره في كتابه إلا في موضع واحد وهو قوله تعالى وما توفيقي إلا بالله ومن أورد هنا قوله تعالى فيه إن أردنا إلا إحسانا وتوفيقا وإن يريدا إصلاحا يوفق الله بينهما مردود بأن ذلك توفيق دنيوي والذي كلامنا فيه إنما هو التوفيق الأخروي ولم يتكرر ختم المصنف كلامه به فقال (والله) تبارك وتعالى لا بغيره (التوفيق) التوفيق مصدر وفق عبارة عن خلق القدرة والمقدور في محل العبد على موافقة أمر الله تعالى وهو مبتدأ وقدم الصنف الخبر"], [54, "بالسيادة وإنما العجز لي بالعبودية لأن العجز أمر مفهوم مطلقا وهو الذي نفاه صلى الله عليه وسلم ونزه نفسه عنه فقال ولا فخر خاف صلى الله عليه وسلم أن ينسبه بعض من سمع أول كلامه إلى أنه افتخر فحفظ صلى الله عليه وسلم موضع الفتنة من قلوب السامعين فقال ولا فخر أي إنما أعلمكم بسيادتي لتعلموا بذلك منزلتي ومكاني ولنقوم بواجب حق ربي ولنعمل بأمره في التحدث بنعمه وإشهار أمرها وإشادة ذكرها وقول من قال في معنى الحديث إنما الفخر لي بالعبودية كلام لا أفهمه لأن العبودية نسبتها إليه وإلى غيره نسبة واحدة وإن قالوا إنما عنى بذلك العبودية التي هي حل ومقامه قلنا إنما يصح العجز بها صح من حيث كونها منة من الله تعالى عليه فان صح الفخر بها من هذا الوجه فلم لا يصح افتخاره بالسيادة وهي أيضا منة الله تعالى عليه فالظاهر أنه عليه الصلاة والسلام نفى التفاخر المطلق ولم يخص ذلك بسيادة ولا غيرها كما قال صلى الله عليه وسلم أنا سيد ولد آدم ولا فخر وأنا حامل لواء الحمد يوم القيامة ولا فخر وأنا أول من تنشق عنه الأرض ولا فخر وأنا أول شافع وأول مشفع ولا فخر وأنا أول من يحرك حلق الجنة فأدخلها مع فقراء المؤمنين ولا فخر وأنا أكرم الأولين والآخرين ولا فخر قبان لك بهذا كله أن إطلاق الأولية والأشرفية في بعض الأسماء دون بعض من غير نظر إلى ما ذكرناه من تسمية الله تعالى وتسمية غيره قصور في النظراء بلفظه وقليل منه بالمعنى.\rوليكن هذا آخر ما قصدناه من هذا الشرح المبارك إن شاء الله تعالى والحمد لله على محاسن ما من ّ من بدء ذلك وإتمامه نسأل الله سبحانه أن يجعله خالصا لوجهه الكريم نافعا لنا ولكل من اجتهد في تحصيله يوم لا ينفع مال ولا بنون وأن يجعله نورا يسعى بين أيدينا وأيديهم إلى جنة عدن مع الآباء والأمهات والإخوة والذرية والأحبة ومن كان منهم في الماضي والحال ومن سيكون بجاه نبيه وأشرف خلقه سيدنا ومولانا محمد صلى الله عليه وسلم وعلى آله وصحبه وسلم صلاة وسلام تأمن بهما في كل موطن يخاف فيه أمثالنا أهل الجرائم المذنبون انتهى.\r[المواهب اللدنية]\rلإفادة الحصر وفيه إشارة إلى أن المتصف به قليل. {خاتمة} ونسأل الله العظيم حسنها. معاني هذه العقائد كلها وهي ما يجب الله تعالى وما يستحيل وما يجوز وما يجب للرسل وما يستحيل وما يجوز تندرج تحت معنى لا إله إلا الله محمد رسول الله صلى الله عليه وسلم وبيان ذلك أم معنى الألوهية التي افرد بها مولانا تبارك وتعالى هي استغناؤه تعالى عن كل ما سواه وافتقار كل ما سواه إليه فاندرج من الصفات الواجبة فيه أحد عشرة صفة وهي وجوب الوجود والقدم والبقاء والمخالفة للحوادث والقيام بالنفس والسمع والبصر والكلام وكونه تعالى سميعا وبصيرا ومتكاملا ويندرج في الافتقار المذكور تسع صفات وهي القدرة والإرادة والعلم والحياة وكونه تعالى قادرا ومريدا وعالما وحيا والوحدانية فهذا تمام العشرين صفة التي تجب في حقه تعالى واستلزم ذلك استحالة أضدادها عليه تعالى وجاز ما سوى ذلك في حقه تعالى، فقد اشتملت الجملة الأولى وهي لا إلى إلا الله على أقسام الحكم العقلية الثلاثة الراجعة لله تعالى ويؤخذ من الجملة الثانية وهي محمد رسول الله صلى الله عليه وسلم وجوب التصديق بسائر الأنبياء والرسل والملائكة والكتب السماوية واليوم الآخر وما فيه إذ التصريح برسالته صلى الله عليه وسلم يستلزم تصديقه في كل ما جاء به ومن جملة ما ذكر يعلم منه أيضا وجوب صدق الرسل عليهم الصلاة والسلام واستحالة الكذب والخيانة عليهم وجواز جميع الأعراض البشرية التي لا تنفض في مراتبهم العلية وهذه جملة أقسام الحكم العقلي المتعلقة بالرسل عليهم الصلاة والسلام ولهذا المعنى جعلهما الشارع ترجمة عما في القلب من الإيمان ودليلا على الانقياد الظاهري للإسلام ولم يقبل من أحد الإيمان مع القدرة عليهما إلا بهما وقد نص العلماء على أنه لا بد من فهم معناها يريدون ولو بطريق الإجمال وإلا لم ينتفع الناطق بهما في الخلاص من الخلود في دار الاقتصاص والله أعلم وبه التوفيق.\rقال مؤلفه وليكن هذا آخر ما قصدنا من شرح سيدنا ومولانا العارف بالله تعالى الشيخ المصنف أبي عبد الله محمد بن يوسف السنوسي الحسني نفعنا الله تعالى به وبعلومه في الدنيا والآخرة بحسب الإمكان مع كثرة الشواغل.\rوكان الفراغ منه يوم السبت سادس عشر من شهر محرم المعظم عام 1091 إحدى وتسعين وألف من هجرته عليه الصلاة والسلام عرفنا الله خيرها وخير ما بعدها وكفانا شرها وشر ما بعدها واغفر لنا ولوالدينا ولأولادنا ولاخواننا على العموم ولمشايخنا ولجميع المؤمنين بجاه ذاتك العلية وصفاتك السرمدية وبأسمائك المرفقة بجاه نبيك المصطفى المختار سيد أهل الأرض والسماء. اللهم إنك رحمن رحيم فارحمنا برحمتك وارحم والدينا آمين."], [56, "خاتمة الطبع\r"]], "pg": [45, 56]}, "516.26": {"x": [[56, "بسم الله الرحمن الرحيم\rالحمد لله الواحد المتعال، المنزه عن الشبيه والمثال، الذي تفرد بالعزة والجلال، وتوحد بالكبرياء\rوالكمال، والصلاة والسلام على سيدنا محمد الداعي إلى أشرف الخصال، المنقذ من الضلال، المبين الحرام من الحلال وعلى أصحابه وآله خير آل، ورضي الله عن التابعين والعلماء العاملين إلى يوم المآل.\rوبعد: فقد تم ّ بحمد الله وحسن توفيقه طبع كتاب\rشرح صغرى الصغرى\rلأبي عبد الله محمد بن يوسف السنوسي الحسني"]], "pg": [56, 56]}}, "units": {"1": {"tit": "شرح صغرى الصغرى في علم التوحيد", "lvl": 1, "pg": [1, 2]}, "2": {"tit": "خطبة الكتاب", "lvl": 1, "pg": [2, 4]}, "5": {"tit": "{تتمة} في ذكر حقيقة الحمد والشكر تكميلا للفائدة", "lvl": 1, "pg": [4, 5]}, "7": {"tit": "فضل الصلاة والسلام على النبي صلى الله عليه وسلم", "lvl": 1, "pg": [5, 9]}, "16": {"tit": "الواجب على المكلف أن يعرف ما يجب وما يستحيل وما يجوز في حق مولانا عزوجل وفي حق رسله عليهم الصلاة والسلام", "lvl": 1, "pg": [9, 17]}, "31": {"tit": "من الصفات الواجبة له تعالى: القدم والبقاء والمخالفة للحوادث", "lvl": 1, "pg": [17, 18]}, "33": {"tit": "قيامه بنفسه، ومعنى ذلك", "lvl": 1, "pg": [18, 20]}, "36": {"tit": "الوحدانية في الذات والصفات والأفعال", "lvl": 1, "pg": [20, 21]}, "38": {"tit": "{تنبيه} وينقسم الجائز أيضا إلى خمسة أقسام", "lvl": 1, "pg": [21, 22]}, "41": {"tit": "القدرة والإرادة المتعلقتان بكل ممكن", "lvl": 1, "pg": [22, 23]}, "43": {"tit": "العلم المتعلق بجميع الواجبات والجائزات", "lvl": 1, "pg": [23, 24]}, "44": {"tit": "السمع والبصر المتعلقان بجميع الموجودات", "lvl": 1, "pg": [24, 25]}, "46": {"tit": "المستحيل في حقه تعالى، والجائز أيضا", "lvl": 1, "pg": [25, 26]}, "48": {"tit": "وأنواع) جمع نوع أي أصناف (الشرك ستة)", "lvl": 1, "pg": [26, 27]}, "51": {"tit": "الأول من الستة (شرك الاستقلال)", "lvl": 1, "pg": [27, 28]}, "52": {"tit": "(و) الثالث من أنواع الشرك (شرك التقريب)", "lvl": 1, "pg": [28, 29]}, "54": {"tit": "(و) الرابع من أنواع الشرك (شرك التقليد)", "lvl": 1, "pg": [29, 30]}, "56": {"tit": "(و) السادس من الأنواع الشرك (شرك الأغراض)", "lvl": 1, "pg": [30, 34]}, "64": {"tit": "كل ما أوهم في حقهم عليهم الصلاة والسلام وجب بتأويله", "lvl": 1, "pg": [34, 45]}, "85": {"tit": "أفضلية سيدنا محمد صلى الله عليه وسلم على جميع الأنبياء والمرسلين", "lvl": 1, "pg": [45, 56]}, "100": {"tit": "خاتمة الطبع", "lvl": 1, "pg": [56, 56]}}};
